    (troop_set_note_available, "trp_spiculus", 1),
    (add_troop_note_from_sreg, "trp_spiculus", 3, "@Spiculus is a famous Roman gladiator. Not only he is popular with regular audiences, but he is also greatly admired by Caesar Nero. Nero has even awarded him with many treasuries.", 0),
    (add_troop_note_tableau_mesh, "trp_spiculus", "tableau_troop_note_mesh"),

