    (add_troop_note_from_sreg, "trp_hermes", 3, "@Hermes is a famous Roman gladiator. He is well trained in many different fighting stiles. Also the famous poet Martial praised his skills in his poem 'On Hermes, A Famous Gladiator'.", 0),
    (add_troop_note_tableau_mesh, "trp_hermes", "tableau_troop_note_mesh"),

    (troop_set_note_available, "trp_Flamma", 1),
    (add_troop_note_from_sreg, "trp_Flamma", 3, "@Flamma is a famous Roman gladiator. Flamma is his battle name, meaning 'flame'. Nobody knows his real name. He was a Syrian soldier who was captured by Roman troops.", 0),
    (add_troop_note_tableau_mesh, "trp_Flamma", "tableau_troop_note_mesh"),

    (troop_set_note_available, "trp_Diocles", 1),
    (add_troop_note_from_sreg, "trp_Diocles", 3, "@Appuleius Diocles is a famous Roman racer. Due to his many victories he has become wealthy and renowned.", 0),
    (add_troop_note_tableau_mesh, "trp_Diocles", "tableau_troop_note_mesh"),

