    (add_troop_note_from_sreg, "trp_Scorpius", 3, "@Scorpus is a famous Roman racer. He is the raising star of horse racing.", 0),
    (add_troop_note_tableau_mesh, "trp_Scorpius", "tableau_troop_note_mesh"),

    (troop_set_note_available, "trp_Marcus_Attilius", 1),
    (add_troop_note_from_sreg, "trp_Marcus_Attilius", 3, "@Marcus Attilius is a famous Roman gladiator. The newcomer has scored many victories against famous veteran gladiators.", 0),
    (add_troop_note_tableau_mesh, "trp_Marcus_Attilius", "tableau_troop_note_mesh"),

    (troop_set_note_available, "trp_martial", 1),
    (add_troop_note_from_sreg, "trp_martial", 3, "@Marcus Valerius Martialis, or better known as Martial, is a famous Roman poet and writer of epigramms.", 0),
    (add_troop_note_tableau_mesh, "trp_martial", "tableau_troop_note_mesh"),

