            # (party_add_template, ":result", ":reinforcements_b"),
            # (party_add_template, ":result", ":reinforcements_b"),
            (party_set_slot, ":result", slot_cohort_1, ":reinforcements_b"),
            (call_script, "script_cohort_describe_strength_to_s5_and_refil", ":result", ":reinforcements_b", slot_cohort_1, -1, -1, 1),

            (party_set_ai_behavior,":result",ai_bhvr_travel_to_party),
            (party_set_ai_object,":result",":spawn_center"),
            (party_set_flags, ":result", pf_default_behavior, 1),
            (store_sub, ":item_to_price_slot", slot_town_trade_good_prices_begin, trade_goods_begin),
            (try_for_range, ":cur_goods", trade_goods_begin, trade_goods_end),
