    (store_script_param, ":party_no", 1),

    (party_slot_eq, ":party_no", slot_party_following_orders_of_troop, "trp_kingdom_heroes_including_player_begin"),

    (party_get_slot, ":ai_state", ":party_no", slot_party_ai_state),
