# script_change_player_honor
# Input: arg1 = honor difference
# Output: none
("change_player_honor",[
    (store_script_param_1, ":honor_dif"),

    #Exacerbate the effect of honor losses as the player's honor increases
    (try_begin),
        (ge, "$player_honor", 10),
        (lt, ":honor_dif", 0),
        (store_add, ":honor_multiplier", "$player_honor", 100),
        (val_mul, ":honor_dif", ":honor_multiplier"),
        (val_sub, ":honor_dif", 50),
        (val_div, ":honor_dif", 100),
    (try_end),

    (val_add, "$player_honor", ":honor_dif"),
    (assign, ":save_reg10", reg10),
    (assign, reg10, ":honor_dif"),
    (assign, reg11, "$player_honor"),
    (try_begin),
        (gt, ":honor_dif", 0),
        (display_message, "@Your reputation changed. (+{reg10}) New value: {reg11}.", message_positive),
    (else_try),
        (lt, ":honor_dif", 0),
        (display_message, "@Your reputation changed. (-{reg10}) New value: {reg11}.", message_negative),
    (try_end),
    (assign, reg10, ":save_reg10"),
]),

  # script_cf_player_has_item_without_modifier
