                (faction_slot_eq, ":center_faction", slot_faction_ai_state, sfai_feast),
                (faction_slot_eq, ":center_faction", slot_faction_ai_object, ":center_no"),
                (troop_slot_eq, ":cur_troop", slot_troop_culture, "fac_culture_roman"),
