# script_cf_enter_center_location_bandit_check
# Input: none
# Output: none
("cf_enter_center_location_bandit_check",[
    (neq, "$town_nighttime", 0),
    (eq, "$g_defending_against_siege", 0),#Skip if the center is under siege (because of resting)
    (eq, "$sneaked_into_town", disguise_none),#Skip if sneaked
    (assign, ":continue", 0),
	(try_begin),#if center has bandits
        (party_slot_ge, "$current_town", slot_center_has_bandits, 1),
        (assign, ":continue", 1),
    (else_try),#check quest
        (check_quest_active, "qst_deal_with_night_bandits"),
        (quest_slot_eq, "qst_deal_with_night_bandits", slot_quest_target_center, "$current_town"),
        (neg|check_quest_succeeded, "qst_deal_with_night_bandits"),
        (assign, ":continue", 1),
    (else_try),###nero claudius changes: enemies of the player will send bullies to beat him up
        (eq, "$g_blood", 0),
        (try_for_range, ":npc", heroes_begin, heroes_end),
            (troop_slot_eq, ":npc", slot_troop_assassin_attempt, 0),
            (call_script, "script_troop_get_relation_with_troop", ":npc", "trp_player"),
            (lt, reg0, -20),
            (store_faction_of_troop, ":faction_of_npc", ":npc"),
            (eq, ":faction_of_npc", "$players_kingdom"),
            (assign, ":relation", reg0),
            (troop_get_slot, ":renown", "trp_player", slot_troop_renown),
            (val_abs, ":relation"),
            (val_mul, ":relation", ":renown"),
            (val_div, ":relation", 100),
            (store_random_in_range, ":r", 200, 300),
            (ge, ":relation", ":r"),
            (try_begin),
                (troop_slot_eq, ":npc", slot_lord_reputation_type, lrep_martial),
                (assign, ":chance", 10),
            (else_try),
                (troop_slot_eq, ":npc", slot_lord_reputation_type, lrep_quarrelsome),
                (assign, ":chance", 45),
            (else_try),
                (this_or_next|troop_slot_eq, ":npc", slot_lord_reputation_type, lrep_selfrighteous),
                (this_or_next|troop_slot_eq, ":npc", slot_lord_reputation_type, lrep_cunning),
                (troop_slot_eq, ":npc", slot_lord_reputation_type, lrep_debauched),
                (assign, ":chance", 40),
            (else_try),
                (troop_slot_eq, ":npc", slot_lord_reputation_type, lrep_goodnatured),
                (assign, ":chance", 1),
            (else_try),
                (troop_slot_eq, ":npc", slot_lord_reputation_type, lrep_upstanding),
                (assign, ":chance", 25),
            (else_try),
                (assign, ":chance", 0),
            (try_end),
            (store_random_in_range, ":rand_number", 0, 100),
            (lt, ":rand_number", ":chance"),
            (troop_set_slot, ":npc", slot_troop_assassin_attempt, 15),
            (assign, ":continue", 2),
            (assign, "$g_blood", 1),
        (try_end),
	(try_end),
    (ge, ":continue", 1),

    #get scene
    (try_begin),
        (party_slot_eq, "$current_town", slot_party_type, spt_village),
        (party_get_slot, ":cur_scene", "$current_town", slot_town_center),
    (else_try),
        (party_get_slot, ":cur_scene", "$current_town", slot_town_center),
    (try_end),
    (modify_visitors_at_site, ":cur_scene"),
    (reset_visitors),

    # (party_get_slot, ":bandit_troop", "$current_town", slot_center_has_bandits),

    #calculate bandit troop
    (try_begin),
        (eq, ":continue", 2),
        (assign, ":bandit_troop", "trp_brigand"),
    (else_try),
        (call_script, "script_center_get_bandits", "$current_town", 1),
        (assign, ":bandit_troop", reg0),
    (try_end),
    # (try_begin),
      # (lt, ":bandit_troop", 1),
      # (call_script, "script_center_get_bandits", "$current_town", 1),
      # (assign, ":bandit_troop", reg0),
    # (try_end),
    (store_character_level, ":level", "trp_player"),

    (set_jump_mission, "mt_bandits_at_night"),
    (try_begin),
        (party_slot_eq, "$current_town", slot_party_type, spt_village),
        (assign, ":spawn_amount", 2),
        (store_div, ":level_fac", ":level", 10),
        (val_add, ":spawn_amount", ":level_fac"),
        (try_for_range, ":unused", 0, 3),
            (gt, ":level", 10),
            (store_random_in_range, ":random_no", 0, 100),
            (lt, ":random_no", ":level"),
            (val_add, ":spawn_amount", 1),
        (try_end),
        (set_visitors, 4, ":bandit_troop", ":spawn_amount"),
        (assign, "$num_center_bandits", ":spawn_amount"),
        (set_jump_entry, 2),
    (else_try),
        (assign, ":spawn_amount", 1),
        (assign, "$num_center_bandits", 0),
        (try_begin),
            (gt, ":level", 15),
            (store_random_in_range, ":random_no", 0, 100),
            (lt, ":random_no", ":level"),
            (assign, ":spawn_amount", 2),
        (try_end),
        (val_add, "$num_center_bandits", ":spawn_amount"),
        (set_visitors, 27, ":bandit_troop", ":spawn_amount"),
        (assign, ":spawn_amount", 1),
        (try_begin),
            (gt, ":level", 20),
            (store_random_in_range, ":random_no", 0, 100),
            (lt, ":random_no", ":level"),
            (assign, ":spawn_amount", 2),
        (try_end),
        (set_visitors, 27, ":bandit_troop", ":spawn_amount"),
        (val_add, "$num_center_bandits", ":spawn_amount"),
        (try_begin),
            (gt, ":level", 9),
            (assign, ":spawn_amount", 1),
            (try_begin),
                (gt, ":level", 25),
                (store_random_in_range, ":random_no", 0, 100),
                (lt, ":random_no", ":level"),
                (assign, ":spawn_amount", 2),
            (try_end),
            (set_visitors, 28, ":bandit_troop", ":spawn_amount"),
            (val_add, "$num_center_bandits", ":spawn_amount"),
        (try_end),
        (assign, "$town_entered", 1),
        (assign, "$all_doors_locked", 1),
    (try_end),

    (display_message, "@You have run into a trap!", message_negative),
    #SB : store actual bandit names
    (str_store_troop_name_plural, s1, ":bandit_troop"),
    (try_begin),
        (eq, ":continue", 1),
        (display_message, "@You are attacked by a group of {s1}!", message_negative),
    (else_try),
        (display_message, "@One of the attackers shout: 'Someone wants that you blood my friend HAHAHA!'", message_negative),
    (try_end),
    # (play_sound, "snd_encounter_looters"), #more generic than bandit sounds
    (jump_to_scene, ":cur_scene"),
    (change_screen_mission),
]),

# script_init_town_agent
# Input: none
# Output: none
("init_town_agent",[
    (store_script_param, ":agent_no", 1),#
    (try_begin),
        (agent_get_entry_no, ":entry", ":agent_no"),
        (ge, ":entry", 1),
        (neg|agent_slot_ge, ":agent_no", slot_agent_is_blocked, 1),
        # (str_store_agent_name, s22, ":agent_no"),
        # (display_message, "@script called for {s22}"),

        (agent_get_troop_id, ":troop_no", ":agent_no"),
        (set_fixed_point_multiplier, 100),
        (assign, ":stand_animation", -1),
        (try_begin),
            (neg|is_between, ":troop_no", tavern_minstrels_begin, tavern_minstrels_end),
            (try_begin),
                (this_or_next|is_between, ":troop_no", armor_merchants_begin, armor_merchants_end),
                (is_between, ":troop_no", weapon_merchants_begin, weapon_merchants_end),
                (try_begin),
                    (troop_get_type, ":cur_troop_gender", ":troop_no"),
                    (eq, ":cur_troop_gender", 0),
                    (agent_set_animation, ":agent_no", "anim_stand_townguard"),
                (else_try),
                    (agent_set_animation, ":agent_no", "anim_stand_townguard"),
                (try_end),
            (else_try),
                (is_between, ":troop_no", kingdom_ladies_begin, kingdom_ladies_end),
                (neg|troop_slot_ge, ":troop_no", slot_troop_age, 40),#not too old
                (this_or_next|troop_slot_eq, ":troop_no", slot_lord_reputation_type, lrep_hedonistic),
                (troop_slot_eq, ":troop_no", slot_lord_reputation_type, lrep_adventurous),
                (assign, ":stand_animation", "anim_vyrn_shieldmaiden_stand"),
            (else_try),
                (this_or_next|eq, ":troop_no", "trp_courtier_locusta"),
                (this_or_next|eq, ":troop_no", "trp_courtier_crispinilla"),
                (eq, ":troop_no", "trp_courtier_female"),
                (assign, ":stand_animation", "anim_vyrn_shieldmaiden_stand"),
            (else_try),
                (is_between, ":troop_no", kingdom_ladies_begin, kingdom_ladies_end),
                (assign, ":stand_animation", "anim_stand_lady"),
            (else_try),
                (this_or_next|is_between, ":troop_no", active_npcs_begin, active_npcs_end),
                (is_between, ":troop_no", "trp_town_1_seneschal", "trp_town_1_arena_master"),
                (assign, ":stand_animation", "anim_stand_lord"),
            (else_try),
                (this_or_next|eq, ":troop_no", "trp_praetoriani_milites_vet"),
                (this_or_next|eq, ":troop_no", "trp_praetoriani_milites_exp"),
                (eq, ":troop_no", "trp_praetoriani_milites"),

                (try_for_range, ":item_slot", ek_item_0, ek_head),
                    (agent_get_item_slot, ":item_id", ":agent_no", ":item_slot"),
                    (gt, ":item_id", 0),
                    (agent_unequip_item, ":agent_no", ":item_id"),
                (try_end),

                (try_begin),
                    (agent_get_item_slot, ":item_id", ":agent_no", ek_gloves),
                    (gt, ":item_id", 0),
                    (item_get_type, ":type", ":item_id"),
                    (neq, ":type", itp_type_one_handed_wpn),
                    (agent_unequip_item, ":agent_no", ":item_id"),
                (try_end),
                (store_random_in_range, ":itm_select", "itm_guard_hasta", "itm_throwing_spears_olymp"),
                (agent_equip_item, ":agent_no", ":itm_select", ek_gloves),
                (agent_set_wielded_item, ":agent_no", ":itm_select"),

                (assign, ":stand_animation", "anim_stand_guard_spear"),
            (else_try),
                (is_between, ":troop_no", soldiers_begin, soldiers_end),
                (assign, ":stand_animation", "anim_stand_townguard"),
            (try_end),
        (try_end),
        (try_begin),
            (ge, ":stand_animation", 0),
            (agent_set_stand_animation, ":agent_no", ":stand_animation"),
            (agent_set_animation, ":agent_no", ":stand_animation"),
            (store_random_in_range, ":random_no", 0, 100),
            (agent_set_animation_progress, ":agent_no", ":random_no"),
        (try_end),
    (try_end),
]),

