    (try_end),

    #spawn germans furor teutonicus
    #germanic border
    #castle_9, castle_34, castle_12, castle_33, castle_24, town_15, castle_32
    (try_for_range, ":germanic_faction", kingdoms_begin, kingdoms_end),
