#script_display_policy_string_to_reg
#unify string register usage to one temp s0 and one output s20
#register reg2,3 are used for mode and postfix
("display_policy_string_to_reg", [
    (store_script_param, ":faction_no", 1),
    (store_script_param, reg2, 2), #whether it is third person "the" or first person "our"
    (store_script_param, reg3, 3), #spaces or line breaks as the postfix delimiter

    (str_store_faction_name_link, s5, ":faction_no"),

    (try_begin),
        (le, "$g_civil_war", 0),
        (faction_slot_eq, ":faction_no", slot_faction_culture, "fac_culture_roman"),
        (faction_get_slot, ":leader", ":faction_no", slot_faction_leader),
        # (str_clear, s44),
        (try_begin),
            (le, "$g_unrest", 0),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} is a bulwark of stability. People enjoy the pleasures of Roman lifestyle."),
        (else_try),
            (le, "$g_unrest", 15),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} is stable. People feel safe. Only some bandits rumor on the roads."),
        (else_try),
            (le, "$g_unrest", 40),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} seems quite stable. In rural areas bandits are a common threat."),
        (else_try),
            (le, "$g_unrest", 50),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} is crumbling. Bandits are a common threat and rebel uprisings undermine public order."),
        (else_try),
            (le, "$g_unrest", 75),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} is shaken. Bandits are a menace and rebellions are common."),
        (else_try),
            (lt, "$g_unrest", 100),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} trembles. Bandits and rebels are a plague."),
        (else_try),
            (ge, "$g_unrest", 100),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} is on the edge of collapse."),
        (else_try),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} is on the edge of collapse."),
        (try_end),
        (str_store_string, s20, "@{s20}{s0}{reg3?^^: }"),

        (try_begin),
            (lt, "$g_heir_of_rome", 0),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} currently has no successor."),
        (else_try),
            (eq, "$g_heir_of_rome", 0),
            (str_store_troop_name, s1, "$g_heir_of_rome"),
            (str_store_troop_name, s2, ":leader"),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} has {s1}, {reg0?daughter:son} of {s2}, as successor to the throne of the {s5}."),
        (else_try),
            (str_store_troop_name, s1, "$g_heir_of_rome"),
            (str_store_troop_name, s2, ":leader"),
            (str_store_string, s0, "@{reg2?Our Empire:The {s5}} has {s1}, adoptive {reg0?daughter:son} of {s2}, is successor of the {s5}."),
        (try_end),
        (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),

        (troop_get_slot, reg39, "trp_senator_dummy", slot_senate_next_meeting),
        (try_begin),
            (ge, reg39, 1),
            (str_store_string, s0, "@^Next senate meeting will be in {reg39} days."),
        (else_try),
            (eq, reg39, 0),
            (str_store_string, s0, "@^A senate meeting is going on in Rome."),
        (else_try),
            (str_store_string, s0, "@^Currently, it is not known when the next senate meeting will be."),
        (try_end),
        (str_store_string, s20, "@{s20}{s0}{reg3?^^: }"),

        (try_begin),
            (eq, "$edict1", 1),
            (str_store_string, s0, "@* Edictum de libelli:^  It is no longer allowed to send petitions to the Emperor."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (eq, "$edict2", 1),
            (str_store_string, s0, "@* Lex Iulia et Papia:^  Every Roman citizen in marriageable age is forced to marry. If not he must pay a punitive tax. Families with three children gain tax privileges."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (eq, "$edict3", 1),
            (str_store_string, s0, "@* Lex Christiani:^  The various Christian sects are now under protection of the Roman Empire and accepted religions."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (eq, "$edict4", 1),
            (str_store_string, s0, "@* Edictum securitatis publica:^  To Worship the Christian god is punished by death."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (ge, "$edict5", 1),
            (str_store_string, s0, "@* Constitutio {playername}:^  "),
            (str_clear, s1),
            (try_begin),
                (eq, "$edict5", 1),
                (try_begin),
                    (eq, "$edict6",1),
                    (str_store_string, s1, "@Additionally the Empire has a constitution and a succession law."),
                (try_end),
                (str_store_string, s0, "@{s0}The civitas Romana is granted to every assimilated aristocrat and wealthy free man of the peregrini. {s1}"),
            (else_try),
                (eq, "$edict5", 2),
                (try_begin),
                    (eq, "$edict6",1),
                    (str_store_string, s1, "@Additionally the Empire has a constitution and a succession law."),
                (try_end),
                (str_store_string, s0, "@{s0}The civitas Romana is granted to every free man of the Empire. There are only two social classes: the honestiores and the humiliores. {s1}"),
            (try_end),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (eq, "$edict7", 1),
            (str_store_string, s0, "@* Lex frumentaria et agraria:^  Grain prices are regulated: minimum of 30 denarii per unit, maximum of 59 denarii per unit. Also restrict landownership: There is a maximum of land which someone can obtain. Thus one can only buy 10 latifundia in total."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (eq, "$edict8", 1),
            (str_store_string, s0, "@* Lex militaris:^  The minimum age for conscripts is 17 years, which decreases number of conscripts."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (eq, "$edict9", 1),
            (str_store_string, s0, "@* Lex Alimenta:^  The government founds orphanages and poor families recieve substitutions in form of tax privileges."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (ge, "$edict10", 1),
            (str_store_string, s0, "@* Edictum mensum:^  The {s28} is now known as {s29}."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (try_begin),
            (ge, "$edict11", 1),
            (str_store_string, s0, "@* Vicesima Libertatis Vel Manumissionum:^ For each manumission, the master is required to pay 5% of the slave's value."),
            (str_store_string, s20, "@{s20}{s0}{reg3?^: }"),
        (try_end),
        (str_store_string, s20, "@{s20}{reg3?^:}"),
    (else_try),
        (faction_slot_eq, ":faction_no", slot_faction_culture, "fac_culture_roman"),
        (str_store_string, s20, "@{s20}{reg2?Our Empire:The {s5}} is currently shaken by a civil war.{reg3?^: }"),
    (try_end),

    (assign, ":string", "str_dplmc_neither_centralize_nor_decentralized"),
    (faction_get_slot, ":centralization", ":faction_no", dplmc_slot_faction_centralization),
    (val_add, ":string", ":centralization"),
    (str_store_string, s0, ":string"),
    (str_store_string, s20, "@{s20}{reg2?Our government:The goverment of the {s5}} is {s0}.{reg3?^: }"),

    (assign, ":string", "str_dplmc_neither_aristocratic_nor_plutocratic"),
    (faction_get_slot, ":aristocraty", ":faction_no", dplmc_slot_faction_aristocracy),
    (val_add, ":string", ":aristocraty"),
    (str_store_string, s0, ":string"),
    (str_store_string, s20, "@{s20}The upper class society is {s0}.{reg3?^: }"),

    (assign, ":string", "str_dplmc_mixture_serfs"),
    (faction_get_slot, ":serfdom", ":faction_no", dplmc_slot_faction_serfdom),
    (val_add, ":string", ":serfdom"),
    (str_store_string, s0, ":string"),
    (str_store_string, s20, "@{s20}{reg2?Our:The} people are {s0}.{reg3?^: }"),

    (assign, ":string", "str_dplmc_mediocre_quality"),
    (faction_get_slot, ":quality", ":faction_no", dplmc_slot_faction_quality),
    (val_add, ":string", ":quality"),
    (str_store_string, s0, ":string"),
    (str_store_string, s20, "@{s20}{reg2?Our:The} troops have {s0}.{reg3?^: }"),

    ##nested diplomacy start+ add mercantilism
    (assign, ":string", "str_dplmc_neither_mercantilist_nor_laissez_faire"),
    (faction_get_slot, ":mercantilism", ":faction_no", dplmc_slot_faction_mercantilism),
    (val_add, ":string", ":mercantilism"),
    (str_store_string, s0, ":string"),
    (str_store_string, s20, "@{s20}{reg2?Our:The government's} approach to trade is {s0}.{reg3?^: }"),
]),

