          (call_script, "script_formation_move_position", "$fplayer_team_no", ":division", pos63, -1),

          (store_add, ":slot", slot_team_d0_formation_space, ":division"),
          (team_get_slot, ":div_spacing", "$fplayer_team_no", ":slot"),
