##stores a random center of a specific culture in reg0
("cf_get_random_town_of_culture", [
    (store_script_param, ":culture", 1),
    (assign, ":center", -1),

    # Create a temporary list of all centers with the desired culture
    (assign, ":num_centers", 0),
    (try_for_range, ":village", towns_begin, towns_end),
        (party_get_slot, ":culture_town", ":village", slot_center_culture),
        (eq, ":culture_town", ":culture"),
        (troop_set_slot, "trp_tutorial_chest_1", ":num_centers", ":village"),# abuse trp_tutorial_chest_1 as temp array
        (val_add, ":num_centers", 1),
    (try_end),

    # Check if any centers were found
    (gt, ":num_centers", 0),

    # Select a random center from the list
    (store_random_in_range, ":random_index", 0, ":num_centers"),
    (troop_get_slot, ":center", "trp_tutorial_chest_1", ":random_index"),

    (assign, reg0, ":center"),
]),

