# script_become_emperor
("become_emperor",[
    (store_script_param, ":enemies", 1),
    (troop_set_slot, "trp_player", slot_troop_culture, "fac_culture_roman"),
    (val_add, "$g_unrest", 15),##add unrest
    (display_message, "@Stability of the Empire decreases", color_bad_news),
    ##add equipment
    ##edit: this can be found now in a chest in the palace
    # (troop_add_item, "trp_player", "itm_laurel_gold", 0),
    # (troop_add_item, "trp_player", "itm_laurel_silver", 0),
    # (troop_add_item, "trp_player", "itm_roman_rich_emperor", 0),
    (call_script, "script_change_troop_renown", "trp_player", 50),
    ##set variables
    (assign, "$g_is_emperor", 1),
    # (assign, "$g_rank", 0), done elsewhere
    (assign, "$g_has_senat_sup", 0),
	 # (try_begin),
		# (troop_get_slot, ":office", "trp_player", slot_player_office),
		# (ge, ":office", 1),
		# (str_store_party_name, s30, ":office"),
		# (troop_set_slot, "trp_player", slot_player_office, -1),
		# (display_log_message, "As you are now Emperor you resign from your position in {s30}"),
	 # (try_end),
	 ##check if civil war starts
    (try_begin),
        (gt, ":enemies", 0),
        (assign, "$g_civil_war", 1),
    (try_end),

    (faction_set_slot, "fac_player_faction", slot_faction_government_type, gov_imperial),
    (faction_set_slot, "fac_player_supporters_faction", slot_faction_government_type, gov_imperial),
    (faction_set_slot, "fac_player_supporters_faction", slot_faction_has_nor_titles, 1),

    (try_begin),
        (neg|troop_slot_ge, "trp_senator_dummy", slot_senate_support, 20),
        (troop_set_slot, "trp_senator_dummy", slot_senate_support, 20),
        (display_message, "@You gain support in the senate.", color_good_news),
    (try_end),

    (try_for_range, ":npc_kingdom", npc_kingdoms_begin, npc_kingdoms_end),
        (faction_set_slot, ":npc_kingdom", slot_faction_recognized_player, 1),
    (try_end),
    (try_begin),
        (troop_slot_ge, "trp_player", slot_troop_honorary_title, 1),
        (display_message, "@Since you are now Divine Caesar, you lose your old honorary title."),
        (troop_set_slot, "trp_player", slot_troop_honorary_title, 0),
    (try_end),

    #end the quest if player becomes Emperor
    (try_begin),
        (this_or_next|check_quest_active, "qst_blank_quest_8"),
        (check_quest_succeeded, "qst_blank_quest_8"),
        (call_script, "script_end_quest", "qst_blank_quest_8"),
    (try_end),
    (try_begin),
        (this_or_next|check_quest_active, "qst_petrus"),
        (check_quest_succeeded, "qst_petrus"),
        (call_script, "script_end_quest", "qst_petrus"),
    (try_end),

    (try_begin),
        (neg|is_vanilla_warband),
        (troop_add_item, "trp_bonus_chest_7", "itm_quadriga_chariot_horse"),
    (try_end),

    (faction_set_slot, "fac_player_faction", slot_faction_tax_rate, 30),
    (faction_set_slot, "fac_player_faction", slot_faction_tax_rate_buisness, 25),
    (faction_set_slot, "fac_player_supporters_faction", slot_faction_tax_rate, 30),
    (faction_set_slot, "fac_player_supporters_faction", slot_faction_tax_rate_buisness, 25),
]),

