("visit_temple",[
    (store_script_param_1, ":current_scene"),
    (store_script_param_2, ":priest_troop"),
    (try_begin),
        (is_currently_night),
        (display_message, "str_door_locked"),
    (else_try),
        (modify_visitors_at_site,":current_scene"),
        (reset_visitors),
        (set_jump_mission,"mt_visit_temple"),

        (try_begin),
            (scene_slot_ge, ":current_scene", slot_scene_visited, 1),
            (this_or_next|key_is_down, key_left_shift),
            (key_is_down, key_right_shift),
            (assign,":entry",40), #player
        (else_try),
            (assign,":entry",1), #player
        (try_end),

        (try_begin),
            (call_script, "script_cf_player_use_second_outfit"),#is using second outfit?
            (call_script, "script_init_second_outfit", "mt_visit_temple", ":entry", 0),
            (mission_tpl_entry_set_override_flags, "mt_visit_temple", ":entry", af_override_outfit_1|af_override_horse),
        (try_end),
        (set_visitor,":entry","trp_player"), #player

        (set_visitor,2,":priest_troop"),
        (try_for_range, ":visiterator", 3, 24),
            (try_begin),
                (neq, ":current_scene", "scn_temple_of_mithras"),
                (store_random_in_range, ":sex", 0, 100),
                (lt,":sex",50),
                (set_visitor, ":visiterator", "trp_guest_female",),
            (else_try),
                (set_visitor, ":visiterator", "trp_guest",),
            (try_end),
        (try_end),
        (try_begin),
            (neq, ":current_scene", "scn_temple_of_mithras"),
            (try_for_range, ":visiterator", 32, 40),
                (try_begin),
                    (store_random_in_range, ":sex", 0, 100),
                    (lt,":sex",50),
                    (set_visitor, ":visiterator", "trp_roman_town_walker",),
                (else_try),
                    (set_visitor, ":visiterator", "trp_roman_town_walker_female",),
                (try_end),
            (try_end),
            (call_script, "script_init_town_walkers"),
        (try_end),
        (jump_to_scene, ":current_scene"),
        (change_screen_mission),
        # for ceremony cutscene:
        # 41,42,43,44 musicians, 45 camera
    (try_end),
]),
