##spawns a party using party template
## returns party id in reg0
("spawn_party",[
    (store_script_param_1, ":spawn_point"),
    (store_script_param_2, ":party_template"),
    (spawn_around_party, ":spawn_point", ":party_template"),
    (assign, ":party", reg0),
    (call_script, "script_update_party_icon", ":party"),##update party icon
    (party_set_extra_text, ":party", "str_empty_string"),#fix bug with extra text
    (assign, reg0, ":party"),
    # debug message if needed to find invalide parties
    (try_begin),
        (le, ":party_template", 0),
        (str_store_party_name, s10, ":party"),
        (assign, reg10, ":party_template"),
        (display_log_message, "@ERROR Spawned party {s10} using template {reg10}"),
    (try_end),
]),

###dismiss players follower party
("dismiss_follower_party",[
    (store_party_size_wo_prisoners, ":size", "p_follower_party"),
    (try_begin),
        (ge, ":size", 1),
        (party_clear, "p_follower_party"),
        (troop_clear_inventory, "trp_follower_party_mules"),
        (display_message, "@Your follower party is raided. All goods ae lost, all women enslaved.", color_bad_news),
    (try_end),
]),

 ##this code starts hunting, I used dhorak_keep as temp party
("start_hunting",[
    (assign, "$loot_screen_shown", 0),
    (troop_clear_inventory, "trp_temp_troop"),
    (store_random_in_range, ":r", 2, 6),
    (party_add_members, "p_dhorak_keep", "trp_slave", ":r"),
    (set_jump_mission,"mt_hunting"),
    (try_begin),
        (check_quest_active, "qst_freelancing"),
        (mission_tpl_entry_set_override_flags, "mt_hunting",0, af_override_weapons|af_override_head|af_override_horse),
        (mission_tpl_entry_clear_override_items, "mt_hunting", 0),
        (mission_tpl_entry_add_override_item, "mt_hunting", 0, "itm_boar_spear"),
        (mission_tpl_entry_add_override_item, "mt_hunting", 0, "itm_arrows"),
        (mission_tpl_entry_add_override_item, "mt_hunting", 0, "itm_hunting_bow"),
    (try_end),
    (set_jump_entry, 0),
    (call_script, "script_setup_random_scene_native"),
    (jump_to_scene, reg0),
    (jump_to_menu, "mnu_after_hunt"),
    (change_screen_mission),
]),

###randomize equipment of npcs like merchants at game start for more flavor
("initialize_npc_items",[
    #(display_message, "@called initialize_npc_items"),
    (try_for_range, ":center", towns_begin, towns_end),
        (party_get_slot, ":culture", ":center", slot_center_culture),
        (store_sub, ":town_id", ":center", towns_begin),
        (store_add, ":arena_master", ":town_id", arena_masters_begin),
        (party_get_slot, ":tavernkeeper", ":center", slot_town_tavernkeeper),
        (party_get_slot, ":weaponsmith", ":center", slot_town_weaponsmith),
        (party_get_slot, ":armorer", ":center", slot_town_armorer),
        (party_get_slot, ":merchant", ":center", slot_town_merchant),
        (party_get_slot, ":horsemerchant", ":center", slot_town_horse_merchant),
        (party_get_slot, ":elder", ":center", slot_town_elder),
        (party_get_slot, ":craftsman", ":center", slot_town_mastercraftman),
        (str_store_party_name, s8, ":center"),
        (try_begin),
            (call_script, "script_get_slave_merchant_troop", ":center"),
            (assign, ":slave_trader", reg0),
            (is_between, ":slave_trader", slave_traders_centers_begin, slave_traders_centers_end),
            (call_script, "script_add_item_depending_on_culture", ":slave_trader", ":culture"),
            (str_store_troop_name, s7, ":slave_trader"),
            (troop_set_name, ":slave_trader", "@{s7} from {s8}"),
        (try_end),
        (call_script, "script_add_item_depending_on_culture", ":arena_master", ":culture"),
        (str_store_troop_name, s7, ":arena_master"),
        (troop_set_name, ":arena_master", "@{s7} from {s8}"),
        (call_script, "script_add_item_depending_on_culture", ":tavernkeeper", ":culture"),
        (str_store_troop_name, s7, ":tavernkeeper"),
        (troop_set_name, ":tavernkeeper", "@{s7} from {s8}"),
        (call_script, "script_add_item_depending_on_culture", ":weaponsmith", ":culture"),
        (str_store_troop_name, s7, ":weaponsmith"),
        (troop_set_name, ":weaponsmith", "@{s7} from {s8}"),
        (call_script, "script_add_item_depending_on_culture", ":armorer", ":culture"),
        (str_store_troop_name, s7, ":armorer"),
        (troop_set_name, ":armorer", "@{s7} from {s8}"),
        (call_script, "script_add_item_depending_on_culture", ":craftsman", ":culture"),
        (str_store_troop_name, s7, ":craftsman"),
        (troop_set_name, ":craftsman", "@{s7} from {s8}"),
        (try_begin),
            (neq, ":merchant", "trp_town_6_merchant"),##not the roman merchant he is special
            (call_script, "script_add_item_depending_on_culture", ":merchant", ":culture"),
            (str_store_troop_name, s7, ":merchant"),
            (troop_set_name, ":merchant", "@{s7} from {s8}"),
        (try_end),
        (call_script, "script_add_item_depending_on_culture", ":horsemerchant", ":culture"),
        (str_store_troop_name, s7, ":horsemerchant"),
        (troop_set_name, ":horsemerchant", "@{s7} from {s8}"),
        (call_script, "script_add_item_depending_on_culture", ":elder", ":culture"),
        (str_store_troop_name, s7, ":elder"),
        (troop_set_name, ":elder", "@{s7} from {s8}"),
    (try_end),
    (try_for_range, ":center", villages_begin, villages_end),
        (party_get_slot, ":elder", ":center", slot_town_elder),
        (party_get_slot, ":culture", ":center", slot_center_culture),
        (call_script, "script_add_item_depending_on_culture", ":elder", ":culture"),
    (try_end),
]),

