#set up training mission in freelaner
("training_freelancer",[
    (store_script_param_1, ":team_size_1"),
    (store_script_param_2, ":team_size_2"),
    (store_add, ":total_size", ":team_size_1", ":team_size_2"),
    (assign, "$g_arena_training_kills", 0),
    (set_jump_mission,"mt_freelancer_task_training"),
    (modify_visitors_at_site,"scn_follower_camp"),
    (reset_visitors),
    (party_get_num_companion_stacks, ":num_stacks", "$enlisted_party"),
    (assign, ":cur_entry", 47),
    (assign, ":troop_count", 0),
    (try_for_range, ":troop_iterator", 0, ":num_stacks"),
        (try_begin),
            (eq, ":troop_count", ":team_size_1"),
            (assign, ":cur_entry", 48),
        (try_end),
        (party_stack_get_troop_id, ":cur_troop_id", "$enlisted_party", ":troop_iterator"),
        (neq, ":cur_troop_id", "trp_player"),
        (neg|troop_is_hero, ":cur_troop_id"),
        (try_begin),
            (ge, ":troop_count", ":total_size"),
            (assign, ":num_stacks", -1), #break the loop
        (else_try),
            (party_stack_get_size, ":stack_size","$enlisted_party",":troop_iterator"),
            (party_stack_get_num_wounded, ":num_wounded","$enlisted_party",":troop_iterator"),
            (val_sub, ":stack_size", ":num_wounded"),
            (gt, ":stack_size", 0),
            (try_for_range, ":unused", 0, ":stack_size"), #nested loop ayy lmao
                (set_visitor, ":cur_entry", ":cur_troop_id"),
                (val_add, ":troop_count", 1),
                (try_begin),
                    (eq, ":troop_count", ":team_size_1"),
                    (assign, ":cur_entry", 48),
                (try_end),
                (try_begin),
                    (ge, ":troop_count", ":total_size"),
                    (assign, ":stack_size", -1), #break the loop
                (try_end),
            (try_end),
        (try_end),
    (try_end),
    (set_visitor, 47, "trp_player"),
    (jump_to_scene, "scn_follower_camp"),
    (change_screen_mission),
]),
#script_change_relation_with_family_friends_enemies
("change_relation_with_family_friends_enemies",[
    (store_script_param, ":lord", 1),##who is effected by player action
    (store_script_param, ":enemies_like_or_not", 2),#-1 enemy like, 1 enemy dislike
    (store_script_param, ":strength", 3),#strength: 10 means normal strength
    (store_script_param, ":actor", 4), # the actor, can be player
    (store_faction_of_troop, ":lord_faction", ":lord"),
    (try_for_range, ":troop", heroes_begin, kingdom_ladies_end),
        (neg|troop_slot_eq, ":troop", slot_troop_occupation, dplmc_slto_dead),#alive
        (store_faction_of_troop, ":faction_troop", ":troop"),
        (eq, ":faction_troop", ":lord_faction"),#same faction
        (try_begin),#family of him
            (call_script, "script_dplmc_troop_get_family_relation_to_troop", ":troop", ":lord"),
            (gt, reg0, 0),
            (assign, ":family_relation", reg0),
            (val_mul, ":family_relation", ":strength"),
            (val_div, ":family_relation", 11),

            (val_mul, ":family_relation", ":enemies_like_or_not"),#determines gain or loose
            (call_script, "script_troop_change_relation_with_troop", ":troop", ":actor", ":family_relation"),
        (else_try),
            (call_script, "script_troop_get_relation_with_troop", ":troop", ":lord"),
            (assign, ":relation_ship", reg0),
            (val_div, ":relation_ship", 3),
            (try_begin),#friends
                (ge, ":relation_ship", 1),
                (val_clamp, ":relation_ship", 1, 9), #to avoid getting too high
                #modification
                (val_mul, ":relation_ship", ":strength"),
                (val_div, ":relation_ship", 10),
                #modification end
                (val_mul, ":relation_ship", ":enemies_like_or_not"),#determines gain or loose
                (call_script, "script_troop_change_relation_with_troop", ":troop", ":actor", ":relation_ship"),
            (else_try),#enemies of him
                (le, ":relation_ship", -1),
                (val_clamp, ":relation_ship", -9, -1),#to avoid getting too high
                #modification
                (val_mul, ":relation_ship", ":strength"),
                (val_div, ":relation_ship", 10),
                #modification end
                (val_mul, ":relation_ship", ":enemies_like_or_not"),#determines gain or loose
                (call_script, "script_troop_change_relation_with_troop", ":troop", ":actor", ":relation_ship"),
            (try_end),
        (try_end),
    (try_end),

    (try_begin),
        (eq, ":actor", "trp_player"),
        (str_store_troop_name, s44, ":lord"),
        (try_begin),
            (eq, ":enemies_like_or_not", -1),
            (display_message, "@The enemies of {s44} appreciate your action."),
        (else_try),
            (display_message, "@Friends and family of {s44} appreciate your action."),
        (try_end),
    (try_end),
]),

