# script_calculate_season_light
# Component: Seasons
("calculate_season_light",[
    (set_fixed_point_multiplier, 100),
    (position_get_x, reg1, pos1),	# r
    (position_get_y, reg2, pos1), # g
    (position_get_z, reg3, pos1),	# b
    (try_begin),
        (is_between, "$g_cur_month", 3, 6),#spring
        (val_mul, reg1, 100),
        (val_mul, reg2, 107),
        (val_mul, reg3, 100),
    (else_try),
        (is_between, "$g_cur_month", 6, 9),#summer
        (val_mul, reg1, 145),
        (val_mul, reg2, 145),
        (val_mul, reg3, 130),
    (else_try),
        (is_between, "$g_cur_month", 9, 12),#autumn
        (val_mul, reg1, 85),
        (val_mul, reg2, 70),
        (val_mul, reg3, 70),
    (else_try),
        (val_mul, reg1, 40),
        (val_mul, reg2, 40),
        (val_mul, reg3, 55),
    (try_end),
    (val_div, reg1, 100),
    (val_div, reg2, 100),
    (val_div, reg3, 100),
]),

#bandits go to lair
#script_bandits_go_to_lairs
("bandits_go_to_lairs",[
    (store_script_param_1, ":party_no"),
    (try_begin),
        # (party_is_active, ":party_no"),
        (gt, ":party_no", last_static_party),
        (party_get_slot, ":spawn_point", ":party_no", slot_party_spawn_point),
        (this_or_next|is_between, ":spawn_point", spawn_points_begin, spawn_points_end),# has a spawn point
        (eq, ":spawn_point", centers_begin, centers_end), # or spawned at some center
        (party_get_template_id, ":party_template", ":party_no"),

        ##they have their own AI for minor faction raiders
        (neq, ":party_template", "pt_gaetuli"),
        (neq, ":party_template", "pt_garamantes"),
        (neq, ":party_template", "pt_nabatean"),
        (neq, ":party_template", "pt_nubian"),
        (neq, ":party_template", "pt_sakas"),

        # (str_store_party_name, s1, ":party_no"),
        # (assign, reg1, ":party_no"),
        # (display_message, "@{s1} has entered go to lair code 11, id: {reg1}"),

        (get_party_ai_object, ":ai_object", ":party_no"),
        (assign, ":continue", 1),
        (try_begin),
            (call_script, "script_cf_is_port_party", ":ai_object"),#is already on the way to a port(landing)
            (party_slot_eq, ":party_no", slot_party_on_water, 1),
            (assign, ":continue", 0),
        (try_end),
        (try_begin),
            (party_is_in_any_town, ":party_no"),
            (party_get_cur_town, ":cur_town", ":party_no"),
            (call_script, "script_cf_is_port_party", ":cur_town"),#is already in a port(waiting for landing)
            (assign, ":continue", 0),
        (try_end),
        (eq, ":continue", 1),

        ##if there exists a lair us that
        (party_template_get_slot, ":bandit_lair", ":party_template", slot_party_template_lair_party),
        (try_begin),
            (ge, ":bandit_lair", "p_spawn_points_end"),
            (assign, ":target_spawn_point", ":bandit_lair"),
        (else_try),
            (assign, ":target_spawn_point", ":spawn_point"),
        (try_end),

        (try_begin),#if stuck in port
            (gt, ":ai_object", -1),
            (gt, ":spawn_point", "p_spawn_points_end"),
            (party_slot_eq, ":party_no", slot_party_on_water, 1),
            (party_get_template_id, ":party_template_id", ":ai_object"),
            (eq, ":party_template_id", "pt_port"),
            (party_slot_eq, ":party_no", slot_party_ai_object_backup, -1),

            (party_set_ai_behavior, ":party_no", ai_bhvr_travel_to_party),
            (party_set_ai_object, ":party_no", ":target_spawn_point"),
            (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),
        # (party_set_slot, ":party_no", slot_party_ai_object_backup, ":target_spawn_point"),
            # (try_begin),
                # (eq, ":party_template", "pt_sea_raiders"),
                # (display_message, "@Sea raider stuck in port! Help!"),
            # (try_end),
        (else_try), #land parties that have wandered onto water
            (neq, ":party_template", "pt_sea_raiders"),#not for sea raiders
            (neq, ":party_template", "pt_black_sea_pirates"),#not for sea raiders
            (party_slot_eq, ":party_no", slot_party_on_water, 1),

            (party_set_ai_behavior, ":party_no", ai_bhvr_travel_to_party),
            (party_set_ai_object, ":party_no", ":target_spawn_point"),
            (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),

            # (try_begin),
            # (str_store_party_name, s1, ":party_no"),
            # (display_message, "@{!}INFO: {s1} is a land party that has wandered onto water and is heading back now"),
            # (try_end),
        (else_try),
            (eq, ":party_template", "pt_black_sea_pirates"),#those pirates shall remain on water
            (party_slot_eq, ":party_no", slot_party_on_water, 0),

            (party_set_ai_behavior, ":party_no", ai_bhvr_travel_to_party),
            (party_set_ai_object, ":party_no", ":target_spawn_point"),
            (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),
        (else_try),#If party is active and bandit is far away, then move to location
            (store_distance_to_party_from_party, ":distance", ":spawn_point", ":party_no"),
            (store_distance_to_party_from_party, ":distance_2", ":target_spawn_point", ":party_no"),

            (assign, ":limit", 30),

            (try_begin),
                (eq, ":party_template", "pt_black_sea_pirates"),
                (val_add, ":limit", 30),
            (else_try),
                (eq, ":party_template", "pt_sea_raiders"),
                (val_add, ":limit", 10),
            (else_try),
                (eq, ":party_template", "pt_desert_bandits"),
                (val_add, ":limit", 35),
            (else_try),
                (eq, ":party_template", "pt_steppe_bandits"),
                (val_add, ":limit", 40),
            (else_try),
                (eq, ":party_template", "pt_forest_bandits"),
                (val_add, ":limit", 20),
            (else_try),
                (eq, ":party_template", "pt_judean_rebels_party"),
                (val_sub, ":limit", 10),
            (try_end),

            (gt, ":distance", ":limit"),

            (val_div, ":limit", 2),

            (gt, ":distance_2", ":limit"),

            (party_set_ai_behavior, ":party_no", ai_bhvr_travel_to_party),
            (party_set_ai_object, ":party_no", ":target_spawn_point"),
            (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),
            # (str_store_party_name, s1, ":party_no"),
            # (display_message, "@{s1} is returning to lair"),
        (else_try),#return to drop of prisoners
            (party_get_num_prisoners, ":prisoners", ":party_no"),
            (gt, ":prisoners", 30),
            (get_party_ai_behavior, ":behavior", ":party_no"),
            (neq, ":behavior", ai_bhvr_travel_to_party),

            (party_set_ai_behavior, ":party_no", ai_bhvr_travel_to_party),
            (party_set_ai_object, ":party_no", ":target_spawn_point"),
            (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),
        (else_try),# if reached lair
            (this_or_next|lt, ":distance_2", 3),
            (party_is_in_any_town, ":party_no"),
            #(eq, ":behavior", ai_bhvr_travel_to_party),

            (try_begin),#remove if it is too small
                (store_party_size_wo_prisoners, ":bandit_size", ":party_no"),
                (lt, ":bandit_size", 6),
                (call_script, "script_destroy_party", ":party_no"),
            (else_try),#otherwise patrol again

                (assign, "$g_move_heroes", 0),##no heroes
                (call_script, "script_party_remove_all_prisoners", ":party_no"),#also drop of prisoners

                (party_set_ai_behavior, ":party_no", ai_bhvr_patrol_party),
                (party_set_ai_object, ":party_no", ":target_spawn_point"),
                (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),
            (try_end),
        (else_try), #if lair destroyed
            (eq, ":behavior", ai_bhvr_patrol_party),
            (neq, ":ai_object", ":target_spawn_point"),
            (party_set_ai_object, ":party_no", ":target_spawn_point"),
            (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),
        (else_try), #if lair destroyed
            (eq, ":behavior", ai_bhvr_hold),
            (neq, ":ai_object", ":target_spawn_point"),
            (party_set_ai_object, ":party_no", ":target_spawn_point"),
            (party_set_slot, ":party_no", slot_party_ai_object, ":target_spawn_point"),
            (party_set_ai_behavior, ":party_no", ai_bhvr_patrol_party),
        (try_end),
    (try_end),
]),

