# script_kill_lord_lady
("kill_lord_lady",[
    (store_script_param, ":lord", 1),#can also be a lady
    (store_script_param, ":killer", 2),
    (store_script_param, ":search_new_king", 3), # search for new king

    (store_troop_faction, ":lord_faction", ":lord"),

    #disband party
    (troop_get_slot, ":lord_party", ":lord", slot_troop_leaded_party),
    (call_script, "script_destroy_party", ":lord_party"),
    (troop_set_slot, ":lord", slot_troop_leaded_party, -1),

    #clear slots
    (troop_set_slot, ":lord", slot_prisoner_agreed, 0),
    (troop_set_slot, ":lord", slot_troop_legion, -1),
    (troop_set_slot, ":lord", slot_troop_aux, -1),
    (troop_set_slot, ":lord", slot_troop_prisoner_of_party, -1),
    (troop_set_slot, ":lord", slot_lady_last_suitor, -1),
    (troop_set_slot, ":lord", slot_troop_stance_on_faction_issue, -1),
    (troop_set_slot, ":lord", slot_troop_temp, 0),
    (troop_set_slot, ":lord", slot_troop_lover, -1),
    (troop_set_slot, ":lord", slot_troop_tortured_by, -1),
    (troop_set_slot, ":lord", slot_troop_lover_found, -1),
    (troop_set_slot, ":lord", slot_troop_flirted_with, 0),
    (troop_set_slot, ":lord", dplmc_slot_troop_affiliated, 0),
    (troop_set_slot, ":lord", slot_troop_assassin_attempt, 0),
    (troop_set_slot, ":lord", slot_troop_cur_center, -1),

    ##handle honorary titles
    (try_begin),
        (troop_get_slot, ":title", ":lord", slot_troop_honorary_title),
        (ge, ":title", 1),
        (call_script, "script_ai_assign_title", ":title", ":lord_faction", ":lord", 1, 1),
    (try_end),

    (troop_set_slot, ":lord", slot_troop_occupation, dplmc_slto_dead),
    #handel family
    (try_for_range, ":spouse_family", active_npcs_including_player_begin, kingdom_ladies_end),
        (neq, ":spouse_family", "trp_knight_1_1_wife"),
        (try_begin),
            (eq, ":spouse_family", "trp_kingdom_heroes_including_player_begin"),
            (assign, ":spouse_family", "trp_player"),
        (try_end),

        (try_begin),#end all lover affairs of the npc with other ladies
            (troop_slot_eq, ":spouse_family", slot_troop_occupation, slto_kingdom_lady),
            (troop_slot_eq, ":spouse_family", slot_troop_lover, ":lord"),
            (troop_set_slot, ":spouse_family", slot_troop_lover, -1),
            (str_store_troop_name, s29,":lord"),
            (str_store_troop_name, s30,":spouse_family"),
            (display_log_message, "@{s29} and {s30} are no longer lovers."),
        (try_end),
        # (try_begin),#handle if he is guardian of a lady
          # (troop_slot_eq, ":spouse_family", slot_troop_occupation, slto_kingdom_lady),
          # (call_script, "script_get_kingdom_lady_social_determinants", ":spouse_family"),
          # (assign, ":guardian", reg0),

          # (this_or_next|eq, ":guardian", ":lord"),
          # (eq, ":guardian", -1),

          # (store_faction_of_troop, ":fac", ":spouse_family"),
          # (faction_get_slot, ":leader", ":fac", slot_faction_leader),
          # (troop_set_slot, ":spouse_family", slot_troop_father, ":leader"),
          # (str_store_troop_name, s29,":leader"),
          # (str_store_troop_name, s30,":spouse_family"),
          # (display_log_message, "@{s29} adopts {s30}."),
        # (try_end),
        (try_begin),#divorce if he is married
            (troop_get_slot, ":spouse", ":spouse_family", slot_troop_spouse),
            (eq, ":spouse", ":lord"),
            (call_script, "script_troop_divorce_troop", ":spouse", ":spouse_family"),
        (try_end),
    (try_end),

    # remove them from their faction
    (troop_set_slot, ":lord", slot_troop_change_to_faction, "fac_no_faction"),
    (troop_set_slot, ":lord", slot_troop_original_faction, "fac_no_faction"),

    (try_begin),
        (neq, ":killer", ":lord"),
        (call_script, "script_change_relation_with_family_friends_enemies", ":lord", -1, 30, ":killer"),
    (try_end),
    (str_store_troop_name_link, s44, ":lord"),
    (display_log_message, "@{s44} deceased.", message_negative),
    (try_begin),
        (eq, "$g_player_minister", ":lord"),
        (assign, "$g_player_minister", "trp_temporary_minister"),
        (str_store_troop_name, s45, "trp_temporary_minister"),
        (display_message, "@{s44} was your minister and is now replaced by {s45}"),
    (try_end),

    # apply the honor hit
    (try_begin),
        (eq, ":killer", "trp_player"),
        (call_script, "script_change_player_honor", -15),
        (call_script, "script_change_player_party_morale", 20),
    (try_end),
    # but give them renown for this evil deed (their deed spreads upon every tongue, impressing some, and cowing others)
    (call_script, "script_change_troop_renown", ":killer" , 50),
    # start with the assumption that the fief should return to its faction for redistribution
    (assign, ":fief_faction", ":lord_faction"),
    (try_begin),
        (eq, ":search_new_king", 1),
        # handle executing the King!
        (faction_slot_eq, ":lord_faction", slot_faction_leader, ":lord"),

        # find best candidate to become king
        (assign, ":best_troop", -1),
        (assign, ":best_renown", -1),
        (try_for_range, ":troop", original_kingdom_heroes_begin, active_npcs_end),
            (neg|troop_slot_eq, ":troop", slot_troop_occupation, dplmc_slto_dead), #can't choose a dead hero!
            (store_troop_faction, ":faction", ":troop"),
            (eq, ":faction", ":lord_faction"),
            (troop_slot_eq, ":troop", slot_troop_occupation, slto_kingdom_hero), #only other heros of this faction may become the king
            (troop_get_slot, ":renown", ":troop", slot_troop_renown),
            (gt, ":renown", ":best_renown"),
            (assign, ":best_troop", ":troop"),
            (assign, ":best_renown", ":renown"),
        (try_end),

        (try_begin),
            # check if a candidate was found
            (neq, ":best_troop", -1),
            # make them king
            (faction_set_slot, ":lord_faction", slot_faction_leader, ":best_troop"),
            # announce it!
            #TODO: generate a presentation for this! (start_presentation, "prsnt_enemy_succession"),
            (str_store_troop_name, s1, ":best_troop"),
            (str_store_faction_name, s2, ":lord_faction"),
            (display_log_message, "@{s1} is the new Ruler of {s2}!!!", 0xFFFF2222),
            #TODO: update the game log for this event
        (else_try),
            # all of the lords have been eliminated - so eliminate the faction by making their last fief neutral (q.v. trigger: # Check if a faction is defeated every day)
            (assign, ":fief_faction", "fac_no_faction"),
        (try_end),
    (try_end),

    (try_for_range, ":fief", centers_begin, centers_end),
        (party_get_slot, ":governor", ":fief", slot_town_lord),
        (eq, ":lord", ":governor"),
        (party_set_slot, ":fief", slot_town_lord, stl_unassigned),
        (call_script, "script_give_center_to_faction_aux", ":fief", ":fief_faction"),
    (try_end),
    # no longer our prisoner
    (call_script, "script_remove_troop_from_prison", ":lord"),

    (try_begin),# remove from player party
        (party_count_prisoners_of_type,":prisoner_1","p_main_party",":lord"),
        (ge, ":prisoner_1", 1),
        (party_remove_prisoners, "p_main_party", ":lord", ":prisoner_1"),
    (try_end),

    # remove from dungeon
    (try_for_range, ":walled_centers", walled_centers_begin, walled_centers_end),
        (party_count_prisoners_of_type, ":prisoner_1", ":walled_centers", ":lord"),
        (ge, ":prisoner_1",1),
        (party_remove_prisoners, ":walled_centers", ":lord", ":prisoner_1"),
        (str_store_party_name, s1, ":walled_centers"),
        (display_message, "@Removed him from {s1}"),
    (try_end),

    #Annull all quests of which the lord/lady is giver
    (try_for_range, ":quest", all_quests_begin, all_quests_end),
        (check_quest_active, ":quest"),
        (quest_slot_eq, ":quest", slot_quest_giver_troop, ":lord"),
        (str_store_troop_name, s4, ":lord"),
        (str_store_quest_name, s5, ":quest"),
        (display_message, "str_s4_death_aborts_quest_s5"),
        (call_script, "script_abort_quest", ":quest", 0),
    (try_end),
]),

