##OLYMPIA SCRIPTS
#games over without player
("games_over",[
    (quest_set_slot, "qst_olympic_games", slot_quest_dont_give_again_remaining_days, 336),
    (assign, ":victor", -1),
    (assign, ":score_to_beat",-1),
    (try_for_range, ":participants", 0, 49),#find other victor
        (troop_get_slot,":guy", "trp_olympia_participants", ":participants"),
        (store_character_level, ":level", ":guy"),
        (gt, ":level", ":score_to_beat"),
        (assign, ":score_to_beat", ":level"),
        (assign, ":victor", ":guy"),
    (try_end),
    (call_script, "script_add_notification_menu", "mnu_games_over",":victor",0),
]),

("fill_participants_list",[
    (try_for_range, ":participants", 0, 49),
        (troop_set_slot, "trp_olympia_participants", ":participants", -1),
    (try_end),

    (assign, ":participant_number", 0),
    (try_for_range, ":npc", active_npcs_begin, active_npcs_end),
        (try_begin),
            # Condition 1: If the troop is female, do nothing and skip to the end of this block.
            (call_script, "script_cf_dplmc_troop_is_female", ":npc"),
        (else_try),
            # Condition 2: If the troop is NOT female, check if they meet the criteria.
            (store_faction_of_troop,":fac", ":npc"),
            (this_or_next|faction_slot_eq, ":fac", slot_faction_culture, "fac_culture_roman"),
            (is_between, ":npc", companions_begin, companions_end),

            (store_attribute_level, ":strength",":npc", ca_strength),
            (ge, ":strength", 14),

            (store_skill_level, ":athlets", skl_athletics,":npc"),
            (ge, ":athlets", 3),

            (store_skill_level, ":throw", skl_power_throw,":npc"),
            (ge, ":throw", 3),

            (store_skill_level, ":riding", skl_riding,":npc"),
            (ge, ":riding", 3),

            (assign, ":probability", 5),
            (try_begin),
                (troop_slot_eq, ":npc", slot_troop_occupation, slto_kingdom_hero),
                (val_sub, ":probability", 4),
            (try_end),
            (store_random_in_range, ":r", 0, 10),
            (le, ":r", ":probability"),
            (troop_set_slot, "trp_olympia_participants", ":participant_number", ":npc"),
            (val_add, ":participant_number", 1),
        (try_end),
    (try_end),
]),

("get_random_winer",[
    (quest_set_slot, "qst_olympic_games", slot_quest_expiration_days, 7),
    (assign, ":victor", -1),
    (assign, ":score_to_beat",-1),
    (try_for_range, ":participants", 0, 49),#find other victor
        (troop_get_slot,":guy", "trp_temp_array_olympia_c", ":participants"),
        (gt, ":guy", -1),
        (store_character_level, ":level", ":guy"),
        (store_random_in_range, ":rand_addition", 0, 25),
        (val_add, ":level", ":rand_addition"),
        (gt, ":level", ":score_to_beat"),
        (assign, ":score_to_beat", ":level"),
        (assign, ":victor", ":guy"),
    (try_end),
    (assign, reg0, ":victor"),
]),
#OLYMPIA SCRIPTS END
#script_view_party_members:
#input: party id
# this script allows to view a party, without player being able to add or remove members
# the flag pf_limit_members needs to be cleared though
("view_party_members",[
    (store_script_param_1, ":party"),
    (assign, reg62, 1),
    (party_set_flags, ":party", pf_limit_members, 1),
    (change_screen_give_members,":party"),
]),

# script_troop_default_division MOTO chief
# Input: troop_id, flag 0 for expanded divisions
# Output: reg0 default division
("troop_default_division", [
    (store_script_param, ":troop_no", 1),
    (store_script_param, ":flag_0_for_expanded", 2),
    (assign, ":target_division", grc_infantry),
    (troop_get_inventory_capacity, ":inv_cap", ":troop_no"),
    (try_begin),
        (troop_is_guarantee_horse, ":troop_no"),
        (assign, ":has_horse", 0),
        (try_for_range, reg0, 0, ":inv_cap"),
            (troop_get_inventory_slot, ":item", ":troop_no", reg0),
            (gt, ":item", 0),
            (item_get_type, reg1, ":item"),
            (eq, reg1, itp_type_horse),
            (assign, ":has_horse", 1),
        (try_end),
        (neq, ":has_horse", 0),
        (assign, ":target_division", grc_cavalry),
        (try_begin),
            (eq, ":flag_0_for_expanded", 0),
            (try_for_range, reg0, 0, ":inv_cap"),
                (troop_get_inventory_slot, ":item", ":troop_no", reg0),
                (call_script, "script_cf_is_weapon_ranged", ":item", 1),
                (assign, ":target_division", sdt_harcher),
            (try_end),
        (try_end),
    (else_try),
        (troop_is_guarantee_ranged, ":troop_no"),
        (assign, ":has_ranged", 0),
        (try_for_range, reg0, 0, ":inv_cap"),
            (troop_get_inventory_slot, ":item", ":troop_no", reg0),
            (call_script, "script_cf_is_weapon_ranged", ":item", 1),
            # (item_get_max_ammo, reg1, ":item"), returns 1 for slings, etc.
            # (neg|is_between, reg1, 1, minimum_ranged_ammo), #more than two to
            # throw on a charge?
            (item_get_type, reg1, ":item"),
            (try_begin),
                (this_or_next | eq, reg1, itp_type_thrown),
                (eq, reg1, itp_type_pistol),
                (eq, ":flag_0_for_expanded", 0),
                (neq, ":target_division", grc_archers),
                (assign, ":target_division", sdt_skirmisher),
            (else_try),
                (assign, ":target_division", grc_archers),
            (try_end),
            (assign, ":has_ranged", 1),
        (try_end),
        (neq, ":has_ranged", 0),
    (else_try),
        (eq, ":flag_0_for_expanded", 0),
        (try_for_range, reg0, 0, ":inv_cap"),
            (troop_get_inventory_slot, ":item", ":troop_no", reg0),
            (call_script, "script_cf_is_thrusting_weapon", ":item"),
            (item_get_type, reg1, ":item"),
            (eq, reg1, itp_type_polearm),
            (assign, ":target_division", sdt_polearm),
        (try_end),
    (try_end),
    (assign, reg0, ":target_division"),
]),

#script_troop_set_rank which sets a rank for a lord
("troop_set_rank", [
    (store_script_param, ":troop_no", 1),
    (store_script_param, ":rank_type", 2),
    (store_script_param, ":value", 3),

    (troop_set_slot, ":troop_no", ":rank_type", ":value"),#set slot

    (try_begin),
        (eq, ":rank_type", slot_troop_legion),
        (gt, ":value", 0),
        (store_add, ":slot", slot_legion_commanders_begin, ":value"),
        (troop_set_slot, "trp_province_array", ":slot", ":troop_no"),
        (try_begin),
            (eq, ":troop_no", "trp_player"),
            (assign, "$g_rank", 3),
        (try_end),
    (else_try),
        (eq, ":rank_type", slot_troop_aux),
        (gt, ":value", 0),
        (store_sub, ":slot", ":value", "pt_cohors_aux"),
        (val_add, ":slot", slot_aux_commander_begin),
        (troop_set_slot, "trp_province_array", ":slot", ":troop_no"),
        (try_begin),
            (eq, ":troop_no", "trp_player"),
            (neg|is_between, "$g_rank", 1, 3),
            (assign, "$g_rank", 1),
        (try_end),
    (try_end),

    (try_begin),
        (eq, ":troop_no", "trp_player"),
        (assign, ":troop_faction", "$players_kingdom"),
    (else_try),
        (store_faction_of_troop, ":troop_faction", ":troop_no"),
    (try_end),

    (troop_get_slot, ":party_no", ":troop_no", slot_troop_leaded_party),
    (try_begin),
        (party_is_active, ":party_no"),
        ##update cohorts if rank is updated
        (neq, ":troop_no", "trp_player"),
        (call_script, "script_party_update_cohorts", ":troop_no", ":party_no"),
    (try_end),

    (call_script, "script_troop_set_title_according_to_faction", ":troop_no", ":troop_faction"),#set kingdom
    (call_script, "script_set_troop_banner_according_to_faction", ":troop_no", ":troop_faction"),#set banner properly

    #also update banners of towns, as the troop banner may change
    (try_for_range, ":center_no", walled_centers_begin, walled_centers_end),
        (party_slot_eq, ":center_no", slot_town_lord, ":troop_no"),
        #normal_banner_begin
        (troop_get_slot, ":cur_banner", ":troop_no", slot_troop_banner_scene_prop),
        (try_begin),
            (gt, ":cur_banner", 0),
            (val_sub, ":cur_banner", banner_scene_props_begin),
            (val_add, ":cur_banner", banner_map_icons_begin),
            (party_set_banner_icon, ":center_no", ":cur_banner"),
        # custom_banner_begin
        (else_try),
            (eq, ":cur_banner", -1),
            (troop_get_slot, ":flag_icon", ":troop_no", slot_troop_custom_banner_map_flag_type),
            (ge, ":flag_icon", 0),
            (val_add, ":flag_icon", custom_banner_map_icons_begin),
            (party_set_banner_icon, ":center_no", ":flag_icon"),
        (try_end),
    (try_end),
]),

#script_set_troop_banner_according_to_faction
("set_troop_banner_according_to_faction",[
    (store_script_param, ":troop_no",1),
    (store_script_param, ":faction_no",2),

    (troop_get_slot, ":legion", ":troop_no", slot_troop_legion),
    (troop_get_slot, ":aux_unit", ":troop_no", slot_troop_aux),
    (assign, ":aux_unit_legion", 0),
    (assign, ":selected_banner", -2),
    (assign, ":selected_banner_map_icon", -2),
    (troop_get_slot, ":leaded_party_lord", ":troop_no", slot_troop_leaded_party),
    (try_begin),
        (eq, ":troop_no", "trp_player"),
        (assign, ":leaded_party_lord", "p_main_party"),
    (try_end),

    (try_begin),
        (gt, ":aux_unit", 1),
        (val_sub, ":aux_unit", "pt_cohors_aux"),
        (store_add, ":aux_unit_legion_slot", ":aux_unit", slot_aux_legion_begin),
        (troop_get_slot, ":aux_unit_legion", "trp_province_array", ":aux_unit_legion_slot"),
        # (str_store_troop_name, s1, ":troop_no"),
        # (assign, reg1, ":aux_unit"),
        # (assign, reg2, ":aux_unit_legion"),
        # (display_message, "@{s1} has aux unit: {reg1}, legion {reg2}"),
    (try_end),

    (try_begin),
        (is_between, ":faction_no", kingdoms_begin, kingdoms_end),#is valid faction
        (try_begin),
            (ge, ":legion", 1),
            (call_script, "script_get_legion_banner", ":legion"),
            (assign, ":selected_banner", reg0),
            (assign, ":selected_banner_map_icon", reg1),
        (else_try),
            (ge, ":aux_unit_legion", 1),
            (call_script, "script_get_legion_banner", ":aux_unit_legion"),
            (assign, ":selected_banner", reg0),
            (assign, ":selected_banner_map_icon", reg1),
        (else_try),
            (faction_get_slot, ":no_faction_banner", ":faction_no", slot_faction_banner),
            (try_begin),
                (eq, ":no_faction_banner", -1),
                (troop_get_slot, ":flag_icon", "trp_player", slot_troop_custom_banner_map_flag_type),
                (troop_set_slot, ":troop_no", slot_troop_custom_banner_map_flag_type, ":flag_icon"),
                (assign, ":selected_banner", -1),
                (store_add, ":selected_banner_map_icon", ":flag_icon", custom_banner_map_icons_begin),
            (else_try),
                (val_sub, ":no_faction_banner", banner_meshes_begin),
                (store_add, ":selected_banner", ":no_faction_banner", banner_scene_props_begin),
                (store_add, ":selected_banner_map_icon", ":no_faction_banner", banner_map_icons_begin),
            (try_end),
        (try_end),
        (try_begin),
            (ge, ":no_faction_banner", -1),#if it is custom banner
            (troop_set_slot, ":troop_no", slot_troop_banner_scene_prop, ":selected_banner"),
        (try_end),
        (try_begin),
            (gt, ":selected_banner_map_icon", -1),
            (party_is_active, ":leaded_party_lord"),
            (party_set_banner_icon, ":leaded_party_lord", ":selected_banner_map_icon"),
            (try_begin),
                (ge, "$cheat_mode", 1),
                (str_store_troop_name, s1, ":troop_no"),
                (str_store_party_name, s2, ":leaded_party_lord"),
                (display_message, "@Set banner for party of {s1}, {s2}"),
            (try_end),
        (try_end),
    (try_end),
]),
#script_agent_run_away
#idea is to let agents flee towards their reinforcement point
("agent_run_away",[
    (store_script_param, ":cur_agent",1),

    #get scene boundaries
    (init_position, pos11),
    (get_scene_boundaries, pos10, pos11),
    (position_get_x, ":scene_max_x", pos11),
    (position_get_y, ":scene_max_y", pos11),
    #get center of map
    (val_div, ":scene_max_x", 2),
    (val_div, ":scene_max_y", 2),
    (position_set_x, pos11, ":scene_max_x"),
    (position_set_y, pos11, ":scene_max_y"),

    (try_begin),
        (agent_is_defender, ":cur_agent"),
        (entry_point_get_position, pos10, 1),
    (else_try),
        (entry_point_get_position, pos10, 4),
    (try_end),
    (call_script, "script_point_y_toward_position", pos10, pos11),
    (position_get_x, ":x", pos10),
    (store_random_in_range, ":x_addition", -1500, 1500),
    (val_add, ":x", ":x_addition"),
    (position_set_x, pos10, ":x"),
    (position_move_y, pos10, -100000),

    (agent_start_running_away, ":cur_agent", pos10),
    (agent_set_slot, ":cur_agent", slot_agent_recently_decided, 6),#he recently decided
    # (agent_start_running_away, ":cur_agent"),
]),

("cf_center_night_bandits_check",[
    (store_script_param, ":center_no",1),
    (party_slot_eq, ":center_no", slot_center_has_guard, 0),
    (try_begin),
        (party_slot_ge, ":center_no", slot_center_has_bandits, 1),
        (assign, ":random_chance", 40),
        (try_begin),
            (party_slot_eq, ":center_no", slot_party_type, spt_town),
            (assign, ":random_chance", 20),
        (try_end),
        (try_begin),
            (party_slot_ge, ":center_no", slot_center_decree_law_enforcement, 1),
            (val_add, ":random_chance", 10),
        (try_end),
        (store_random_in_range, ":random_no", 0, 100),
        (lt, ":random_no", ":random_chance"),
        (party_set_slot, ":center_no", slot_center_has_bandits, 0),
        (try_begin),
            (eq, "$cheat_mode", 1),
            (str_store_party_name, s1, ":center_no"),
            (display_message, "@{s1} is no longer infested by bandits (at night)."),
        (try_end),
    (else_try),
        (assign, ":boundery", 111),
        (try_begin),
            (store_faction_of_party, ":center_faction", ":center_no"),
            (faction_get_slot, ":serfdom", ":center_faction", dplmc_slot_faction_serfdom),# + 3 means low slave rights, -3 means high slave rights
            (val_mul, ":serfdom", -1),
            (val_add, ":boundery", ":serfdom"),
        (try_end),

        (store_random_in_range, ":random_no", 0, ":boundery"),
        (assign, ":random_chance", 5),
        (try_begin),
            (party_slot_ge, ":center_no", slot_center_decree_law_enforcement, 1),
            (val_sub, ":random_chance", 1),
        (try_end),
        (try_begin),
            (party_slot_ge, ":center_no", slot_center_decree_control, 1),
            (val_sub, ":random_chance", 1),
        (try_end),
        (try_begin),
            (party_slot_ge, ":center_no", slot_center_decree_housing, 1),
            (val_sub, ":random_chance", 1),
        (try_end),
        (try_begin),
            (party_slot_ge, ":center_no", slot_center_decree_curfew, 1),
            (val_sub, ":random_chance", 1),
        (try_end),

        (le, ":random_no", ":random_chance"),
        (party_set_slot, ":center_no", slot_center_has_bandits, "trp_looter"),
        (try_begin),
            (eq, "$cheat_mode", 1),
            (str_store_party_name, s1, ":center_no"),
            # (str_store_troop_name_plural, s2, ":bandit_troop"),
            (display_message, "@{!}{s1} is infested by bandits (at night)."),
        (try_end),
    (try_end),
]),

#having lords and ladies comment on player equipment
("cf_comment_on_clothing_lady",[
   # (store_random_in_range, ":rand", 0, 10),
    # (le, ":rand", 1),
    (neg|faction_slot_eq, "$g_talk_troop_faction", slot_faction_leader, "trp_player"),#player not leader of action
    (troop_slot_eq,"$g_talk_troop",slot_troop_occupation, slto_kingdom_lady),
    (le,"$talk_context",tc_siege_commander),

    # (display_message, "@Check Lord comment on player clothing begin."),
    # (is_between, "$current_town", walled_centers_begin, walled_centers_end),
    # (store_current_scene, ":scene"),
    # (party_slot_eq, "$current_town", slot_town_castle,":scene"),

    #not relatives of player
    (neg|troop_slot_eq, "$g_talk_troop", slot_troop_spouse, "trp_player"),
    (neg|troop_slot_eq, "$g_talk_troop", slot_troop_father, "trp_player"),
    (neg|troop_slot_eq, "$g_talk_troop", slot_troop_mother, "trp_player"),

    (agent_slot_eq, "$g_talk_agent", slot_agent_has_commented, 0),
    (str_clear, s68),
    (str_clear, s69),
    (get_player_agent_no, ":player"),
    (agent_is_active, ":player"),
    (agent_is_alive, ":player"),

    (agent_get_item_slot, ":body", ":player", ek_body),
    (assign, ":c", 1),

    (faction_get_slot, ":culture", "$g_talk_troop_faction", slot_faction_culture),

    (store_sub, ":id", "$g_talk_troop", active_npcs_begin),
    (store_add, ":slot", slot_item_has_commented, ":id"),
    (try_begin),
        (ge, ":body", 0),
        (item_get_slot, ":has_commented", ":body", ":slot"),
    (else_try),
        (assign, ":has_commented", 1),
    (try_end),
    (try_begin),
        (eq, ":has_commented", 0),
        (is_between, ":body", "itm_linothorax_alexander", "itm_nothing_body"),

        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_otherworldly),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_hedonistic),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_adventurous),
            (try_begin),
                (troop_slot_ge, "$g_talk_troop", slot_troop_player_relation, 30),
                (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", 2),
                (str_store_string, s68, "@Is this the legendary armor you found? People have been talking about it. Some claim you had a blacksmith forge it for you, but I'm certain they're wrong."),
            (else_try),
                (str_store_string, s68, "@Is this the legendary armor you discovered? People have been talking about it. Though, I must admit, it's possible you simply had a blacksmith forge it for you."),
            (try_end),
        (else_try),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -1),
            (str_store_string, s68, "@I've heard of this legendary armor before. Forgive me, but I can't help thinking you paid a blacksmith to forge it for you—how else could you have acquired it?"),
        (try_end),

        (item_set_slot, ":body", ":slot", 1),

        # (assign, reg33, ":has_commented"),
        # (display_message, "@{reg33}"),
        (assign, ":c", 0),
    (else_try),
        (eq, ":body", "itm_minotaur_armor"),
        (str_store_string, s1, "@What is that foul-smelling thing you're wearing? It reeks terribly!"),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_otherworldly),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_adventurous),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -10),
        (else_try),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -20),
        (try_end),
        (assign, ":c", 0),
    (else_try),
        (ge, ":body", 0),
        # either same faction or in same culture group
        (this_or_next|eq, "$g_talk_troop_faction", "$players_kingdom"),
        (faction_slot_eq, "$players_kingdom", slot_faction_culture, ":culture"),
        (neg|item_has_faction, ":body", ":culture"),
        (str_store_string, s68, "@You could have purchased proper clothing from one of our skilled tailors. Instead, you're dressed like a barbarian."),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_otherworldly),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_adventurous),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -1),
        (else_try),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -5),
        (try_end),
        (assign, ":c", 0),
    (else_try),
        (ge, ":body", 0),
        (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_ambitious),
        (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_moralist),
        (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_conventional),
        (item_get_value, ":base_price", ":body"),
        (le, ":base_price", 500),
        (str_store_string, s68, "@Your outfit seems a bit on the cheap side, doesn't it?"),
        (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -1),
        (play_sound, "snd_female_laugh"),
        (assign, ":c", 0),
    (else_try),
        (ge, ":body", 0),
        (item_get_value, ":base_price", ":body"),
        (le, ":base_price", 500),
        (str_store_string, s68, "@Allow me to offer you some advice, {playername}. Your outfit appears rather inexpensive, which could harm your reputation and renown. It would be wise to invest some coins in more suitable attire."),
        (assign, ":c", 0),
        (play_sound, "snd_female_laugh"),
    (else_try),
        (le, ":body", -1),
        (str_store_string, s68, "@You're completely naked! Oh! Aren't you ashamed to appear like this in front of a lady? Do you not have the means to afford clothing?"),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_hedonistic),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_adventurous),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -2),
        (else_try),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -10),
        (try_end),
        (assign, ":c", 0),
    (try_end),

    (agent_get_item_slot, ":foot", ":player", ek_foot),

    (try_begin),
        (le, ":foot", -1),
        (str_store_string, s69, "@Why are you without shoes or boots? Are you unable to afford a pair?"),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_hedonistic),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_adventurous),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -1),
        (else_try),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -5),
        (try_end),
        (assign, ":c", 0),
    (try_end),
    (eq, ":c", 0),
    (agent_set_slot, "$g_talk_agent", slot_agent_has_commented, 1),
    (call_script, "script_dplmc_store_troop_is_female", "$g_talk_troop"),
]),
