#script_cf_comment_on_piety
("cf_comment_on_piety",[
    (eq, "$g_talk_troop_faction", "$players_kingdom"),
    (this_or_next|le, "$player_piety", 40),
    (ge, "$player_piety", 300),
    (store_random_in_range, ":rand", 0, 10),
    (le, ":rand", 7),

    # (neg|faction_slot_eq, "$g_talk_troop_faction", slot_faction_leader, "trp_player"),#player not leader of action
    (this_or_next|troop_slot_eq,"$g_talk_troop", slot_troop_occupation, slto_kingdom_hero),
    (troop_slot_eq,"$g_talk_troop", slot_troop_occupation, slto_kingdom_lady),
    (neq, "$g_talk_troop", "trp_legatus_12"),#not kaeso
    (le,"$talk_context",tc_siege_commander),

    # (display_message, "@Check Lord comment on player clothing begin."),
    # (is_between, "$current_town", walled_centers_begin, walled_centers_end),
    # (store_current_scene, ":scene"),
    # (party_slot_eq, "$current_town", slot_town_castle,":scene"),

    #not relatives of player
    (neg|troop_slot_eq, "$g_talk_troop", slot_troop_spouse, "trp_player"),
    (neg|troop_slot_eq, "$g_talk_troop", slot_troop_father, "trp_player"),
    (neg|troop_slot_eq, "$g_talk_troop", slot_troop_mother, "trp_player"),

    (agent_slot_eq, "$g_talk_agent", slot_agent_has_commented, 0),
    (str_clear, s69),
    (get_player_agent_no, ":player"),
    (agent_is_active, ":player"),
    (agent_is_alive, ":player"),

    (try_begin),
        (le, "$player_piety", 10),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_conventional),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_moralist),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -2),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@Oh, {playername}, it pains me to see you so estranged from the gods. A life without their blessings is fraught with hardship. I implore you, for your own sake, to seek their forgiveness."),
            (else_try),
                (str_store_string, s69, "@{playername}, I mean no offense, but your lack of devotion troubles me. The gods' favor is not easily earned, and to be so estranged from their grace is a perilous path. I urge you to reflect on your ways before misfortune befalls you."),
            (try_end),
        (else_try),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", -1),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@{playername}, your disregard for the gods is both shocking and foolish. How can you expect to prosper when even the heavens turn their back on you?"),
            (else_try),
                (str_store_string, s69, "@Just some word of advice, {playername}. Do you think one can rise in this world while earning the wrath of the gods? Your irreverence is an insult to heaven itself, and it won't be long before you face the consequences."),
            (try_end),
        (try_end),
    (else_try),
        (le, "$player_piety", 40),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_conventional),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_moralist),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@{playername}, your devotion appears faint, and I worry for your soul. A little more reverence might bring you not only favor from the divine but also respect from those around you."),
            (else_try),
                (str_store_string, s69, "@{playername}, I sense your faith wavers. While you may have avoided outright scorn from the gods, it is unwise to neglect their blessings. A little more pietas could go a long way toward ensuring your future success."),
            (try_end),
        (else_try),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@{playername}, your lukewarm faith does you no favors. The gods dislike the indifferent, and such neglect may invite their displeasure upon you."),
            (else_try),
                (str_store_string, s69, "@{playername}, I notice your lack of regard for the divine. Tread carefully. Without the gods' favor, even the strongest leaders are brought low by the weight of their own arrogance."),
            (try_end),
        (try_end),
    (else_try),
        (ge, "$player_piety", 450),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_conventional),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_moralist),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", 2),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@Oh, {playername}, your devotion is truly beautiful. The gods must look upon you with great love and pride. Such pietas inspires everyone around you, myself included."),
            (else_try),
                (str_store_string, s69, "@{playername}, your devotion to the divine is truly inspiring. It's no wonder the gods favor you so deeply, for your pietas shines like a beacon. Such faith will undoubtedly lead to blessings for you and those you serve."),
            (try_end),
        (else_try),
            (call_script, "script_change_player_relation_with_troop", "$g_talk_troop", 1),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@{playername}, I must admit, your devotion is impressive. To be so deeply loved by the gods is no small feat. I'm curious—does such favor come naturally, or is it something you work tirelessly to maintain?"),
            (else_try),
                (str_store_string, s69, "@Impressive, {playername}. Your devotion has clearly earned you the gods' highest favor. A wise choice, I must admit—having the heavens on your side is always a strong advantage in both peace and war."),
            (try_end),
        (try_end),
    (else_try),
        (ge, "$player_piety", 300),
        (try_begin),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_martial),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_conventional),
            (troop_slot_eq, "$g_talk_troop", slot_lord_reputation_type, lrep_moralist),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@{playername}, your faith is admirable, and I can tell the gods smile upon you. It's a comfort to know that someone so devoted walks among us."),
            (else_try),
                (str_store_string, s69, "@{playername}, your dedication to the gods has not gone unnoticed. You carry yourself with a grace that can only come from divine favor. May their blessings continue to guide and protect you."),
            (try_end),
        (else_try),
            (try_begin),
                (call_script, "script_cf_dplmc_troop_is_female", "$g_talk_troop"),
                (str_store_string, s69, "@{playername}, your pietas is commendable. The gods clearly look favorably upon you, though I wonder if you find their favor as rewarding as it seems."),
            (else_try),
                (str_store_string, s69, "@{playername}, I see the gods favor you—perhaps more than most. Such favor is no small thing, though I hope you'll use it wisely to strengthen your position."),
            (try_end),
        (try_end),
    (try_end),
    (neg|str_is_empty, s69),
    (agent_set_slot, "$g_talk_agent", slot_agent_has_commented, 1),
]),

