        (store_faction_of_troop, ":faction", ":character"),
        (faction_get_slot, ":leader", ":faction", slot_faction_leader),

        #player relation
        (call_script, "script_troop_get_player_relation", ":leader"),
        (assign, ":relation", reg0),
        (val_mul, ":relation", -1),
        (val_add, ":outcome", ":relation"),

        #relation with target
        (call_script, "script_troop_get_relation_with_troop", ":leader", ":character"),
        (assign, ":relation", reg0),
        (val_mul, ":relation", -1),
        (val_add, ":outcome", ":relation"),

        #higher renown makes it smaller
        (troop_get_slot, ":renown", ":character", slot_troop_renown),
