#script_change_influence
#script to change troop influence
("change_influence",[
    (store_script_param, ":character", 1),
    (store_script_param, ":cost", 2),
    (try_begin),
        (try_begin),
            (eq, ":character", "trp_player"),
            (assign, ":faction_no", "$players_kingdom"),
        (else_try),
            (store_faction_of_troop, ":faction_no", ":character"),
        (try_end),
        (neg|faction_slot_eq, ":faction_no", slot_faction_leader, ":character"),
        (troop_get_slot, ":influence", ":character", slot_troop_influence),
        (store_add, ":new_influence", ":influence", ":cost"),
        (val_max, ":new_influence", 0),
        (troop_set_slot, ":character", slot_troop_influence, ":new_influence"),
        (try_begin),
            (eq, ":character", "trp_player"),
            (assign, reg11, ":influence"),
            (assign, reg12, ":new_influence"),
            (display_message, "@Your influence has changed from {reg11} to {reg12}.", message_alert),
        (try_end),

        (try_begin),
            (eq, ":character", "trp_player"),
            # (str_store_troop_name, s1, ":troop_no"),
            (assign, reg12, ":cost"),
            (val_abs, reg12),
            (try_begin),
                (gt, ":cost", 0),
                (display_message, "@You gained {reg12} influence.", message_positive),
            (else_try),
                (lt, ":cost", 0),
                (display_message, "@You lose {reg12} influence.", message_negative),
            (try_end),
        (try_end),
    (try_end),
]),
