    (assign, ":store_fixed_point", 1),
    (convert_to_fixed_point, ":store_fixed_point"),
    (set_fixed_point_multiplier, 100),
    (party_get_position, pos22, ":party_no"),
    (party_get_current_terrain, ":terrain_type", ":party_no"),

