("get_cohort_info_to_s5",[
    (store_script_param, ":party_template", 1),
    (store_script_param, ":cur_faction", 2),

    (party_clear, "p_temp_party"),
    (party_add_template, "p_temp_party", ":party_template"),
    (party_get_num_companion_stacks, ":num_stacks", "p_temp_party"),

    (str_clear, s5),
    (assign, reg2, 0),
    (assign, reg3, 0),
    (assign, reg4, 0),
    (assign, reg5, 0),
    (assign, reg6, 0),
    (assign, reg7, 0),

    (try_for_range, ":troop_iterator", 0, ":num_stacks"),
        (party_stack_get_troop_id, ":cur_troop_id", "p_temp_party", ":troop_iterator"),
        (party_stack_get_size, reg1, "p_temp_party", ":troop_iterator"),
        (str_store_troop_name, s1, ":cur_troop_id"),
        (str_store_string, s5, "@{reg1} {s1}. {s5}"),
        (val_add, reg2, reg1),
        (try_begin),
            (call_script, "script_cf_is_mercenary", ":cur_troop_id"),
            (val_add, reg7, reg1),
        (else_try),
            (call_script, "script_cf_is_noble", ":cur_troop_id"),
            (val_add, reg3, reg1),
        (else_try),
            (val_add, reg4, reg1),
        (try_end),
        (call_script, "script_game_get_troop_wage", ":cur_troop_id", 0),
        (val_mul, reg0, reg1),
        (val_add, reg5, reg0),
        (call_script, "script_game_get_join_cost", ":cur_troop_id", 0),
        (assign, ":join_cost", reg0),
        (try_begin),
            (is_between, ":cur_faction", kingdoms_begin, kingdoms_end),
            (faction_get_slot, ":quality", ":cur_faction", dplmc_slot_faction_quality),
            (neq, ":quality", 0),
            (val_add, ":quality", 100),
            (val_mul, ":quality", 10),
            (val_mul, ":join_cost", ":quality"),
            (val_div, ":join_cost", 1000),
        (try_end),
        (val_mul, ":join_cost", reg1),
        (val_add, reg6, ":join_cost"),
    (try_end),

    (try_begin),
        (is_between, ":cur_faction", kingdoms_begin, kingdoms_end),
        (faction_slot_eq, ":cur_faction", slot_faction_culture, "fac_culture_roman"),
        (str_store_string, s4, "@officers"),
    (else_try),
        (str_store_string, s4, "@nobles"),
    (try_end),

    (try_begin),
        (is_between, ":cur_faction", kingdoms_begin, kingdoms_end),
        (faction_slot_eq, ":cur_faction", slot_faction_player_tributary, 1),
        (val_div, reg6, 2),
    (try_end),

    # (try_begin),
    #     (faction_get_slot, ":quality", ":cur_faction", dplmc_slot_faction_quality),
    #     (neq, ":quality", 0),
    #     (val_add, ":quality", 100),
    #     (val_mul, ":quality", 10),
    #     (val_mul, reg6, ":quality"),
    #     (val_div, reg6, 1000),
    # (try_end),

    (str_store_string, s5, "@Recruitment cost: {reg6}. Upkeep cost: {reg5}. Total size: {reg2}. {s4} needed: {reg3}. Recruits needed: {reg4}. Mercenaries needed: {reg7}. Consists of: {s5}"),

    (party_clear, "p_temp_party"),
]),

# script_cohort_describe_strength_to_s5_and_refil
("cohort_describe_strength_to_s5_and_refil",[
    (store_script_param, ":party_no", 1),
    (store_script_param, ":party_template", 2),
    (store_script_param, ":party_template_slot", 3),
    (store_script_param, ":cur_center", 4),
    (store_script_param, ":lord", 5),
    (store_script_param, ":refil_y", 6),

    (party_clear, "p_temp_party"),
    (party_add_template, "p_temp_party", ":party_template"),

    # (assign, reg1, ":party_template"),
    # (str_store_party_name, s10, ":cur_center"),
    # (call_script, "script_get_cohort_name_to_s5", ":party_template"),
    # (display_message, "@party_template {s10}: {reg1} ({s5})"),


    (assign, ":num_of_cohorts_of_type", 0),

    (assign, ":cohort_begin", slot_cohort_begin),
    (try_begin),
        (is_between, ":party_no", centers_begin, centers_end),
        (assign, ":cohort_begin", slot_cohort_town_begin),
    (try_end),

    (assign, ":lord_faction", -1),
    (assign, ":cur_center_faction", -1),
    (try_begin),
        (eq, ":lord", "trp_player"),
        (assign, ":lord_faction", "$players_kingdom"),
    (else_try),
        (is_between, ":lord", active_npcs_begin, active_npcs_end),
        (store_faction_of_troop, ":lord_faction", ":lord"),
    (try_end),

    (try_begin),
        (is_between, ":cur_center", centers_begin, centers_end),
        (store_faction_of_party, ":cur_center_faction", ":cur_center"),
    (try_end),

    (try_for_range, ":cohort_dummy", ":cohort_begin", ":party_template_slot"),
        (party_slot_eq, ":party_no", ":cohort_dummy", ":party_template"),
        (val_add, ":num_of_cohorts_of_type", 1),
    (try_end),

    (try_begin),
        (eq, ":refil_y", 1),
        (try_begin),
            (is_between, ":cur_center", walled_centers_begin, walled_centers_end),
            (assign, ":nobles", 0),
            (assign, ":peasants", 0),
            (assign, ":mercenaries", 0),
            (party_get_slot, ":province", ":cur_center", slot_center_province),
            (try_for_range, ":center", centers_begin, centers_end),
                (party_slot_eq, ":center", slot_center_province, ":province"),
                (store_faction_of_party, ":center_faction", ":center"),
                (eq, ":center_faction", ":cur_center_faction"),
                (party_get_slot, ":cur_number_nobles", ":center", slot_center_volunteer_noble_troop_amount),
                (val_add, ":nobles", ":cur_number_nobles"),
                (party_get_slot, ":cur_number_peasants", ":center", slot_center_peasant_troop_amount),
                (val_add, ":peasants", ":cur_number_peasants"),
                (party_get_slot, ":cur_number_mercenaries", ":center", slot_center_mercenary_troop_amount_2),
                (val_add, ":mercenaries", ":cur_number_mercenaries"),
            (try_end),
        (else_try),#let AI have infinite recruits
            (assign, ":nobles", 1000),
            (assign, ":peasants", 1000),
            (assign, ":mercenaries", 1000),
        (try_end),
        (try_begin),
            (is_between, ":lord", active_npcs_begin, active_npcs_end),
            (faction_slot_eq, ":lord_faction", slot_faction_government_type, gov_imperial),
            (this_or_next|is_between, ":party_no", centers_begin, centers_end),
            (this_or_next|faction_slot_eq, ":lord_faction", slot_faction_leader, ":lord"), # is emperor
            (this_or_next|troop_slot_ge, ":lord", slot_troop_legion, 1),
            (troop_slot_ge, ":lord", slot_troop_aux, 1),
            (assign, ":gold", 1000000),
        (else_try),
            (eq, ":lord", "trp_player"),
            (lt, "$g_is_emperor", 1),#as emperor it goes into imperial bugdet
            #Remove any remaining gold from the treasury
            (store_troop_gold, ":gold", "trp_household_possessions"),
            (try_begin),
                (ge, "$g_rank", 1),
                (troop_get_slot, ":player_rec_limit", "trp_global_variables", g_player_recruitement_limit),
                (val_add, ":gold", ":player_rec_limit"),
            (try_end),
            #Remove the gold from the player
            (store_troop_gold, ":cur_gold", "trp_player"),
            (val_add, ":gold", ":cur_gold"),

            # (assign, reg1, ":gold"),
            # (display_message, "@Gold: {reg1}"),
        (else_try),
            (is_between, ":lord", active_npcs_begin, active_npcs_end),
            (troop_get_slot, ":gold", ":lord", slot_troop_wealth),
        (else_try),#no lord = infinite money
            (assign, ":gold", 1000000),
        (try_end),
    (else_try),
        (str_clear, s5),
    (try_end),

    (assign, ":total_size", 0),
    (assign, ":total_nobles_needed", 0),
    (assign, ":total_recruits_needed", 0),
    (assign, ":total_upkeep_cost", 0),
    (assign, ":total_refill_cost", 0),
    (assign, ":actual_refill_cost", 0),
    (assign, ":total_mercs_needed", 0),
    (assign, ":nobles_needed", 0),
    (assign, ":peasants_needed", 0),
    (assign, ":mercenaries_needed", 0),
    (party_get_num_companion_stacks, ":num_stacks", "p_temp_party"),
    (try_for_range, ":troop_iterator", 0, ":num_stacks"),
        (party_stack_get_troop_id, ":cur_troop_id", "p_temp_party", ":troop_iterator"),
        (party_stack_get_size, ":needed_troops_of_type", "p_temp_party", ":troop_iterator"),

        # (assign, reg1, ":needed_troops_of_type"),
        # (str_store_troop_name, s10, ":cur_troop_id"),
        # (display_message, "@needed_troops_of_type {s10}: {reg1}"),

        #we need to correct for same templates using the same troops
        (assign, ":correction", 0),
        (try_for_range, ":cohort_dummy", ":cohort_begin", ":party_template_slot"),
            (party_get_slot, ":cohort", ":party_no", ":cohort_dummy"),
            (gt, ":cohort", 1),
            (neq, ":cohort", ":party_template"),
            (call_script, "script_cohort_count_troop", ":cohort", ":cur_troop_id"),
            (gt, reg0, 0),
            (val_add, ":correction", reg0),
        (try_end),

        # (assign, reg1, ":correction"),
        # (str_store_troop_name, s10, ":cur_troop_id"),
        # (display_message, "@Check correction {s10}: {reg1}"),

        (party_count_members_of_type, ":cur_number_troops",":party_no", ":cur_troop_id"),
        ##correct for upgrades
        (try_begin),
            (call_script, "script_cf_troop_has_experienced_version", ":cur_troop_id"),
            (troop_get_upgrade_troop,":cur_troop_upgrade_1",":cur_troop_id",0),
            (troop_get_upgrade_troop,":cur_troop_upgrade_2",":cur_troop_upgrade_1",0),
            (party_count_members_of_type, ":cur_addition",":party_no", ":cur_troop_upgrade_1"),
            (val_add, ":cur_number_troops", ":cur_addition"),
            (party_count_members_of_type, ":cur_addition",":party_no", ":cur_troop_upgrade_2"),
            (val_add, ":cur_number_troops", ":cur_addition"),

            # (assign, reg1, ":cur_addition"),
            # (str_store_troop_name, s10, ":cur_troop_id"),
            # (display_message, "@Check correction of veterans {s10}: {reg1}"),
        (try_end),

        (try_for_range, ":unused", 0, ":num_of_cohorts_of_type"),
            (val_sub, ":cur_number_troops", ":needed_troops_of_type"),
        (try_end),
        (val_sub, ":cur_number_troops", ":correction"),#correct it
        (val_min, ":cur_number_troops", ":needed_troops_of_type"),
        (val_max, ":cur_number_troops", 0),

        (store_sub, ":needed_to_refil", ":needed_troops_of_type", ":cur_number_troops"),

        (val_add, ":total_size", ":cur_number_troops"),
        (try_begin),
            (call_script, "script_cf_is_mercenary", ":cur_troop_id"),
            (val_add, ":total_mercs_needed", ":needed_to_refil"),
        (else_try),
            (call_script, "script_cf_is_noble", ":cur_troop_id"),
            (val_add, ":total_nobles_needed", ":needed_to_refil"),
        (else_try),
            (val_add, ":total_recruits_needed", ":needed_to_refil"),
        (try_end),

        (call_script, "script_game_get_join_cost", ":cur_troop_id"),
        (assign, ":join_cost", reg0),
        (try_begin),
            (is_between, ":lord_faction", kingdoms_begin, kingdoms_end),
            (faction_get_slot, ":quality", ":lord_faction", dplmc_slot_faction_quality),
            (neq, ":quality", 0),
            (val_add, ":quality", 100),
            (val_mul, ":quality", 10),
            (val_mul, ":join_cost", ":quality"),
            (val_div, ":join_cost", 1000),
        (else_try),
            (is_between, ":cur_center_faction", kingdoms_begin, kingdoms_end),
            (faction_get_slot, ":quality", ":cur_center_faction", dplmc_slot_faction_quality),
            (neq, ":quality", 0),
            (val_add, ":quality", 100),
            (val_mul, ":quality", 10),
            (val_mul, ":join_cost", ":quality"),
            (val_div, ":join_cost", 1000),
        (try_end),

        (assign, ":join_cost_per_unit", ":join_cost"),
        (val_mul, ":join_cost", ":needed_to_refil"),
        (val_add, ":total_refill_cost", ":join_cost"),

        (try_begin),
            (eq, ":refil_y", 1),

            # (assign, reg1, ":needed_to_refil"),
            # (str_store_troop_name, s10, ":cur_troop_id"),
            # (display_message, "@1 Needed to refil {s10}: {reg1}"),

            (try_begin),
                (call_script, "script_cf_is_mercenary", ":cur_troop_id"),
                (val_min, ":needed_to_refil", ":mercenaries"),
            (else_try),
                (call_script, "script_cf_is_noble", ":cur_troop_id"),
                (val_min, ":needed_to_refil", ":nobles"),
            (else_try),
                (val_min, ":needed_to_refil", ":peasants"),
            (try_end),

            # (assign, reg1, ":needed_to_refil"),
            # (str_store_troop_name, s10, ":cur_troop_id"),
            # (display_message, "@2 Needed to refil {s10}: {reg1}"),
            (gt, ":needed_to_refil", 0),
            (gt, ":join_cost_per_unit", 1),
            (store_div, ":troops_able_to_buy", ":gold", ":join_cost_per_unit"),


            # (assign, reg1, ":gold"),
            # (assign, reg2, ":join_cost_per_unit"),
            # (assign, reg3, ":troops_able_to_buy"),
            # (str_store_troop_name, s10, ":cur_troop_id"),
            # (display_message, "@troops_able_to_buy {s10}: {reg3} | join_cost: {reg2} | gold: {reg1}"),

            (val_min, ":needed_to_refil", ":troops_able_to_buy"),


            # (assign, reg1, ":needed_to_refil"),
            # (str_store_troop_name, s10, ":cur_troop_id"),
            # (display_message, "@3 Needed to refil {s10}: {reg1}"),

            (party_add_members, ":party_no", ":cur_troop_id", ":needed_to_refil"),

            (try_begin),
                (call_script, "script_cf_is_mercenary", ":cur_troop_id"),
                (val_add, ":mercenaries_needed", ":needed_to_refil"),
                (val_sub, ":mercenaries", ":needed_to_refil"),
            (else_try),
                (call_script, "script_cf_is_noble", ":cur_troop_id"),
                (val_add, ":nobles_needed", ":needed_to_refil"),
                (val_sub, ":nobles", ":needed_to_refil"),
            (else_try),
                (val_add, ":peasants_needed", ":needed_to_refil"),
                (val_sub, ":peasants", ":needed_to_refil"),
            (try_end),

            (store_mul, ":actual_join_cost", ":join_cost_per_unit", ":needed_to_refil"),
            (val_sub, ":gold", ":actual_join_cost"),

            # (assign, reg1, ":actual_join_cost"),
            # (str_store_troop_name, s10, ":cur_troop_id"),
            # (display_message, "@actual_join_cost {s10}: {reg1}"),

            # (assign, reg1, ":actual_refill_cost"),
            # (str_store_troop_name, s10, ":cur_troop_id"),
            # (display_message, "@actual_refill_cost {s10}: {reg1}"),

            (val_add, ":actual_refill_cost", ":actual_join_cost"),

            (val_max, ":gold", 0),
            (val_max, ":mercenaries", 0),
            (val_max, ":nobles", 0),
            (val_max, ":peasants", 0),
            (try_begin),
                (eq, ":gold", 0),
                (assign, ":num_stacks", -1),
            (else_try),
                (eq, ":mercenaries", 0),
                (eq, ":nobles", 0),
                (eq, ":peasants", 0),
                (assign, ":num_stacks", -1),
            (try_end),
        (else_try),
            (eq, ":refil_y", -1),
            (str_store_troop_name, s1, ":cur_troop_id"),
            (assign, reg11, ":cur_number_troops"),
            (str_store_string, s5, "@{reg11} {s1} been removed. {s5}"),
            (party_remove_members, ":party_no", ":cur_troop_id", ":cur_number_troops"),
        (else_try),
            (str_store_troop_name, s1, ":cur_troop_id"),
            (assign, reg1, ":needed_troops_of_type"),
            (assign, reg11, ":cur_number_troops"),
            (str_store_string, s5, "@{reg11} of {reg1} {s1}. {s5}"),
            (call_script, "script_game_get_troop_wage", ":cur_troop_id", ":party_no"),
            (val_mul, reg0, ":cur_number_troops"),
            (val_add, ":total_upkeep_cost", reg0),
        (try_end),
    (try_end),

    (try_begin),
        (eq, ":refil_y", 1),
        (try_begin),
            (ge, ":lord", 0),
            (ge, ":actual_join_cost", 1),
            (faction_slot_eq, ":lord_faction", slot_faction_government_type, gov_imperial),
            (this_or_next|is_between, ":party_no", centers_begin, centers_end),
            (this_or_next|faction_slot_eq, ":lord_faction", slot_faction_leader, ":lord"), # is emperor
            (this_or_next|troop_slot_ge, ":lord", slot_troop_legion, 1),
            (troop_slot_ge, ":lord", slot_troop_aux, 1),

            (assign, ":continue", 1),
            (try_begin),
                (eq, ":lord", "trp_player"),
                (ge, "$g_is_emperor", 1),
            (else_try),
                (eq, ":lord", "trp_player"),
                (is_between, ":party_no", centers_begin, centers_end),
            (else_try),
                (eq, ":lord", "trp_player"),
                (assign, ":continue", 0),
            (try_end),
            (eq, ":continue", 1),
            (try_begin),
                (is_between, ":party_no", centers_begin, centers_end),
                (assign, ":slot", slot_faction_garrison),
            (else_try),
                (assign, ":slot", slot_faction_hire),
            (try_end),
            (call_script, "script_add_to_faction_bugdet", ":slot", ":lord_faction", ":actual_refill_cost"),
            (try_begin),
                (eq, ":lord", "trp_player"),
                (str_store_party_name, s2, ":party_no"),
                (assign, reg6, ":actual_refill_cost"),
                (display_message, "@{reg6} denarii were taken from the imperial treasury on your order to recruit troops for {s2}."),
                (play_sound, "snd_money_paid"),
            (try_end),
        (else_try),
            (ge, ":lord", 0),
            (ge, ":actual_join_cost", 1),
            #use budget
            (try_begin),
                (eq, ":lord", "trp_player"),
                (ge, "$g_rank", 1),
                (troop_get_slot, ":funds", "trp_global_variables", g_player_recruitement_limit),
                (val_min, ":funds", ":actual_refill_cost"),
                (val_sub, ":actual_refill_cost", ":funds"),
                (troop_get_slot, ":player_rec_limit", "trp_global_variables", g_player_recruitement_limit),
                (val_sub, ":player_rec_limit", ":funds"),
                (val_max, ":player_rec_limit", 0),
                (troop_set_slot, "trp_global_variables", g_player_recruitement_limit, ":player_rec_limit"),
            (try_end),
            (call_script, "script_dplmc_remove_gold_from_lord_and_holdings", ":actual_refill_cost", ":lord"),#requires a positive number
        (try_end),
        (try_begin),
            (is_between, ":cur_center", centers_begin, centers_end),
            (this_or_next|gt, ":nobles_needed", 0),
            (this_or_next|gt, ":peasants_needed", 0),
            (gt, ":mercenaries_needed", 0),
            (call_script, "script_take_recruits_from_province", ":cur_center", ":cur_center_faction", ":nobles_needed", ":peasants_needed", ":mercenaries_needed"),
        (try_end),
        (try_begin),
            (eq, ":refil_y", 1),
            (eq, ":lord", 0),
            (eq, ":total_nobles_needed", 0),
            (eq, ":total_recruits_needed", 0),
            (eq, ":total_mercs_needed", 0),
            (store_sub, reg1, ":party_template_slot", ":cohort_begin"),
            (val_add, reg1, 1),
            (call_script, "script_get_cohort_name_to_s5", ":party_template"),
            (display_message, "@The {reg1}. cohort {s5} is fully manned.", message_positive),
        # (else_try),
        #     (eq, ":refil_y", 1),
        #     (eq, ":lord", 0),
        #     (store_sub, reg1, ":party_template_slot", ":cohort_begin"),
        #     (val_add, reg1, 1),
        #     (call_script, "script_get_cohort_name_to_s5", ":party_template"),
        #     (display_message, "@The {reg1}. cohort {s5} is not fully manned, but not enough gold or recruits available.", message_alert),
        (try_end),
    (else_try),
        (eq, ":refil_y", -1),
        (eq, ":party_no", "p_main_party"),
        (display_message, "@The cohort has been removed from your party. {s5}", message_alert),
    (else_try),
        (try_begin),
            (is_between, ":cur_center", centers_begin, centers_end),
            (faction_slot_eq, ":cur_center_faction", slot_faction_culture, "fac_culture_roman"),
            (str_store_string, s4, "@officers"),
        (else_try),
            (str_store_string, s4, "@nobles"),
        (try_end),
        (assign, reg2, ":total_size"),
        (assign, reg3, ":total_nobles_needed"),
        (assign, reg4, ":total_recruits_needed"),
        (assign, reg7, ":total_mercs_needed"),
        (assign, reg5, ":total_upkeep_cost"),
        (assign, reg6, ":total_refill_cost"),
        (str_store_string, s5, "@Refill cost: {reg6}. Upkeep cost: {reg5}. Total size: {reg2}."
        +" {reg3?{reg3} {s4} needed to refill.:}{reg4? {reg4} recruits needed to refill.:}{reg7? {reg7} mercenaries needed to refill.:}"
        +" Consists of: {s5}"),
    (try_end),
    (party_clear, "p_temp_party"),
]),


