("cf_can_manage_garrision",[
    (store_script_param, ":party_no", 1),
    (assign, ":player_can_draw_from_garrison", 0),
    (try_begin),
        (party_slot_eq, ":party_no", slot_town_lord, "trp_player"),
        (this_or_next|party_slot_eq, ":party_no", slot_party_type, spt_castle),
        (party_slot_eq, ":party_no", slot_party_type, spt_town),
        (assign, ":player_can_draw_from_garrison", 1),
    (else_try),
        (party_slot_eq, ":party_no", slot_town_lord, "trp_player"),
        (party_slot_eq, ":party_no", slot_party_type, spt_village),
        (party_slot_ge, ":party_no", slot_center_has_manor, 1),
        (assign, ":player_can_draw_from_garrison", 1),
    (else_try),
        (store_faction_of_party, ":faction", ":party_no"),
        (faction_slot_eq, ":faction", slot_faction_leader, "trp_player"),
        (faction_slot_ge, ":faction", dplmc_slot_faction_centralization, 3),
        (assign, ":player_can_draw_from_garrison", 1),
    (else_try),
        (faction_slot_eq, ":faction", slot_faction_marshal, "trp_player"),
        (assign, ":player_can_draw_from_garrison", 1),
    (else_try),
        (troop_get_slot, ":legion", "trp_player", slot_troop_legion),
        (store_add, ":legion_hq", ":legion", slot_legion_home_begin),
        (troop_slot_eq, "trp_province_array", ":legion_hq", ":party_no"),
        (assign, ":player_can_draw_from_garrison", 1),
    (try_end),
    (eq, ":player_can_draw_from_garrison", 1),
]),

("cf_can_donate_to_garrision",[
    (store_script_param, ":party_no", 1),
    (assign, ":player_can_draw_from_garrison", 0),
    (try_begin),
        (party_slot_eq, ":party_no", slot_town_lord, "trp_player"),
    (else_try),
        (call_script, "script_cf_can_manage_garrision", ":party_no"),
        # (display_message, "@Hey"),
    (else_try),
        (store_faction_of_party, ":faction", ":party_no"),
        # (display_message, "@Hey 2"),
        (eq, ":faction", "$players_kingdom"),
        (assign, ":player_can_draw_from_garrison", 1),
    (try_end),
    (eq, ":player_can_draw_from_garrison", 1),
]),

###RENAME CLASS/DIVISION NAMES, used in sieges
#division names are same as class names

("save_class_name",[
    (assign, ":troop", "trp_bonus_chest_1"),
    (try_for_range, ":class", 0, 9),
        (str_store_class_name, s1, ":class"),
        (troop_set_plural_name, ":troop", s1),
        (val_add, ":troop",1),
    (try_end),
    (assign, "$g_recover_class_name", 1),
]),

("recover_class_name",[
    (try_begin),
        (eq, "$g_recover_class_name", 1),
        (assign, ":troop", "trp_bonus_chest_1"),
        (try_for_range, ":class", 0, 9),
            (str_store_troop_name_plural, s1, ":troop"),
            (class_set_name, ":class", s1),
            (val_add, ":troop",1),
        (try_end),
        (assign, "$g_recover_class_name", 0),
    (try_end),
]),

("rename_class_siege",[
    (call_script, "script_save_class_name"),
    (try_begin),
        (eq, "$temp4", 2),# player is defender
        (class_set_name, 0, "@First-ladder defenders"),
        (class_set_name, 2, "@Second-ladder defenders"),
        (class_set_name, 3, "@Third-ladder defenders"),
        (class_set_name, 4, "@Fourth-ladder defenders"),
        (class_set_name, 1, "@Archers"),
        (class_set_name, 5, "@Unused"),
        (class_set_name, 6, "@Unused"),
        (class_set_name, 7, "@Unused"),
        (class_set_name, 8, "@Unused"),
    (else_try),
        (class_set_name, 0, "@First attack division"),
        (class_set_name, 1, "@Second attack division"),
        (class_set_name, 2, "@Third attack division"),
        (class_set_name, 3, "@Fourth attack division"),
        (class_set_name, 4, "@Unused"),
        (class_set_name, 5, "@First Support Archers"),
        (class_set_name, 6, "@Second Support Archers"),
        (class_set_name, 7, "@Third Support Archers"),
        (class_set_name, 8, "@Fourth Support Archers"),
    (try_end),
]),
