#script_calculate_loot_for_troop
("calculate_loot_for_troop",[
    (store_script_param, ":root_winner_party",1),
    (store_script_param, ":root_defeated_party",2),
    (store_script_param, ":loot_option",3),

    (assign, ":number_of_lords_to_share", 0),

    (party_stack_get_troop_id, ":winner_party_leader", ":root_winner_party", 0),
    (try_begin),
        (is_between, ":winner_party_leader", active_npcs_begin, active_npcs_end),
        (val_add, ":number_of_lords_to_share", 1),
    (try_end),

    (party_get_num_attached_parties, ":num_attached_parties", ":root_winner_party"),
    (try_for_range, ":attached_party_rank", 0, ":num_attached_parties"),
        (party_get_attached_party_with_rank, ":attached_party", ":root_winner_party", ":attached_party_rank"),
        (party_stack_get_troop_id, ":party_leader", ":attached_party", 0),
        (is_between, ":party_leader", active_npcs_begin, active_npcs_end),
        (val_add, ":number_of_lords_to_share", 1),
    (try_end),

    #calculate loot amount
    (call_script, "script_center_get_capital", ":root_defeated_party"),
    (assign, ":loot", reg0),

    (party_get_slot, ":wealth", ":root_defeated_party", slot_town_wealth),
    (val_add, ":loot", ":wealth"),

    (party_get_slot, ":prosperity", ":root_defeated_party", slot_town_prosperity),
    (val_add, ":prosperity", 100),
    (val_mul, ":loot", ":prosperity"),
    (val_div, ":loot", 100),

    (party_get_slot, ":tax", ":root_defeated_party", slot_center_accumulated_rents),
    (val_add, ":loot", ":tax"),
    (party_get_slot, ":tax", ":root_defeated_party", slot_center_accumulated_tariffs),
    (val_add, ":loot", ":tax"),

    (try_begin),
        (eq, ":loot_option", 1),
        (val_mul, ":loot", 5),
        (val_div, ":loot", 4),
    (try_end),

    (try_begin),
        (store_faction_of_party, ":winner_faction", ":root_winner_party"),
        (faction_slot_eq, ":winner_faction", slot_faction_government_type, gov_imperial),
        (store_mul, ":loot_tax", ":loot", 1),
        (val_div, ":loot_tax", 3),
        (call_script, "script_add_to_faction_bugdet", slot_faction_taxes_war, ":winner_faction", ":loot_tax"),
        (val_sub, ":loot", ":loot_tax"),
    (try_end),

    (try_begin),
        (ge, ":number_of_lords_to_share", 1),
        (val_div, ":loot", ":number_of_lords_to_share"),
    (try_end),

    (try_for_range, ":attached_party_rank", 0, ":num_attached_parties"),
        (party_get_attached_party_with_rank, ":attached_party", ":root_winner_party", ":attached_party_rank"),
        (party_stack_get_troop_id, ":party_leader", ":attached_party", 0),
        (is_between, ":party_leader", active_npcs_begin, active_npcs_end),
        (try_begin),##add loot for captuaring a castle
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_conventional),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_otherworldly),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_adventurous),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_moralist),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_benefactor),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_custodian),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_goodnatured),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_upstanding),
            (troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_martial),
            (store_mul, ":loot_addition", ":loot", 5),
            (val_div, ":loot_addition", 4),
        (else_try),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_ambitious),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_quarrelsome),
            (troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_cunning),
            (store_mul, ":loot_addition", ":loot", 5),
            (val_div, ":loot_addition", 3),
        (else_try),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_selfrighteous),
            (this_or_next|troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_roguish),
            (troop_slot_eq, ":party_leader", slot_lord_reputation_type, lrep_debauched),
            (store_mul, ":loot_addition", ":loot", 3),
            (val_div, ":loot_addition", 2),
        (else_try),
            (assign, ":loot_addition", ":loot"),
        (try_end),
        (call_script, "script_add_to_troop_wealth", ":party_leader", ":loot_addition"),
        (try_begin),
            (ge, "$cheat_mode", 1),
            (str_store_troop_name, s1, ":party_leader"),
            (assign, reg1, ":loot_addition"),
            (display_message, "@{s1} gained {reg1} from looting"),
        (try_end),
    (try_end),

    (try_begin),#if center is destroyed it will decrease prosperity anyway
        (eq, ":loot_option", 0),
        (call_script, "script_change_center_prosperity", ":root_defeated_party", -5),
        (val_add, "$newglob_total_prosperity_from_townloot", -5),
    (try_end),
]),

