("get_strongest_enemy_faction",[
    (store_script_param, ":faction_no", 1),
    (assign, ":score", 0),
    (assign, ":strongest_faction", -1),
    (try_for_range, ":cur_faction", kingdoms_begin,kingdoms_end),
        (faction_slot_eq, ":cur_faction", slot_faction_state, sfs_active),
        (store_relation, ":relation", ":cur_faction", ":faction_no"),
        (lt, ":relation", 0),
        (faction_get_slot, ":strength", ":cur_faction", slot_faction_num_armies),
        (faction_get_slot, ":castles", ":cur_faction", slot_faction_num_castles),
        (val_add, ":strength", ":castles"),
        (faction_get_slot, ":towns", ":cur_faction", slot_faction_num_towns),
        (val_add, ":strength", ":towns"),
        (gt, ":strength", ":score"),
        (assign, ":score", ":strength"),
        (assign, ":strongest_faction", ":cur_faction"),
    (try_end),
    (assign, reg0, ":strongest_faction"),
]),

