# reason for this to be necessary is that for |other(trp_id) to work max troop-id shouldnt be higher than 2047, but we have some heros out of this range
("set_conversation_troop",[
    (store_script_param, ":troop_no", 1),

    (try_begin),
        # (is_vanilla_warband),
        (set_conversation_speaker_troop, ":troop_no"),

        (assign, ":agent_troop_found", -1),
        (try_for_agents,":agent_no"),
            (agent_is_active, ":agent_no"),
            (agent_is_alive,":agent_no"),
            (agent_is_human,":agent_no"),
            (agent_get_troop_id, ":agent_troop_no", ":agent_no"),
            (eq, ":agent_troop_no", ":troop_no"),
            (assign, ":agent_troop_found", ":agent_no"),
        (try_end),

        (try_begin),
            (agent_is_active, ":agent_troop_found"),
            (set_conversation_speaker_agent, ":agent_troop_found"),
        (else_try),
            (display_message, "@ERROR, ERROR, ERROR: Conversation agent not active", color_bad_news),
        (try_end),
    (try_end),
]),

#script_change_scene_fog_clouds
("change_scene_fog",[
    (store_script_param, ":fog_distance", 1),
    (store_script_param, ":cloud_number", 2),
    (store_script_param, ":colour", 3),
    (store_script_param, ":terrain", 4),
    (store_script_param, ":cur_region", 5),

    #tweaking
    (val_mul, ":fog_distance", 2),

    (store_mul, ":fog_amount", ":cloud_number", 150),
    (val_div, ":fog_amount", 100),

    (set_global_haze_amount, ":fog_amount"),

    (store_time_of_day, ":day_time"),

    (try_begin),
        (is_between, ":day_time", 10, 20),
        (this_or_next|eq, ":terrain", rt_desert),
        (this_or_next|eq, ":terrain", rt_desert_forest),
        (this_or_next|eq, ":cur_region", region_nile_delta),
        (this_or_next|eq, ":cur_region", region_greece),
        (this_or_next|eq, ":cur_region", region_persianhill_green),
        (this_or_next|eq, ":cur_region", region_persianhill_desert),
        (this_or_next|eq, ":cur_region", region_anatolia_coastal),
        (this_or_next|eq, ":cur_region", region_anatolia_central),
        (this_or_next|eq, ":cur_region", region_mesopotamia),
        (this_or_next|eq, ":cur_region", region_north_africa),
        (this_or_next|eq, ":cur_region", region_africa_green),
        (this_or_next|eq, ":cur_region", region_southitaly),
        (this_or_next|eq, ":cur_region", region_nile),
        (eq, ":cur_region", region_syria_palestine),
        # (set_postfx, "pfx_sunny_desert"),
        # (display_message, "@set"),
    (try_end),

    (try_begin),
        (is_between, ":day_time", 9, 17),
        (val_mul, ":fog_distance", 3),
        (val_div, ":fog_distance", 4),
        (set_fog_distance, ":fog_distance", ":colour"),
    (else_try),
        (this_or_next|is_between, ":day_time", 5, 9),
        (is_between, ":day_time", 17, 21),
        (val_mul, ":fog_distance", 3),
        (val_div, ":fog_distance", 5),
        (set_fog_distance, ":fog_distance", ":colour"),
    (else_try),
        # (set_fog_distance, ":fog_distance", ":colour"),
    (try_end),
]),

# script_change_lord_party_to_fit_rank
("change_lord_party_to_fit_rank",[
    (store_script_param, ":lord", 1),
    (troop_get_slot, ":party", ":lord", slot_troop_leaded_party),
    (try_begin),
        (party_is_active, ":party"),
        (neq, ":party", "p_main_party"),
        (try_for_range, ":unused", 0, 9999),
            (store_party_size_wo_prisoners, ":size", ":party"),
            (gt, ":size", 1),
            (party_get_num_companion_stacks,":l", ":party"),
            (try_for_range, ":r", 0, ":l"),
                (party_stack_get_troop_id, ":t", ":party", ":r"),
                (neg|troop_is_hero, ":t"),
                (party_stack_get_size, ":s", ":party", ":r"),
                (party_remove_members, ":party", ":t", ":s"),
            (try_end),
        (try_end),
        (call_script, "script_get_cohort_limit", ":party"),
        (assign, ":cohorts_end", reg0),
        (try_for_range, ":cohort", slot_cohort_begin, ":cohorts_end"),
            (call_script, "script_hire_men_to_kingdom_hero_party", ":lord", -1, ":cohort"),
        (try_end),
    (try_end),
]),

("print_cognomen_to_s1",[
    (str_clear, s1),
    (assign, reg0, 0),
    (try_for_range, ":quests", "qst_blank_quest_22", "qst_blank_quest_26"),
        (quest_slot_ge, "qst_blank_quest_22", slot_quest_target_dna, 1),
        (try_begin),
            (eq, ":quests", "qst_blank_quest_22"),
            (str_store_string, s0, "@Germanicus"),
        (else_try),
            (eq, ":quests", "qst_blank_quest_25"),
            (str_store_string, s0, "@Britannicus"),
        (else_try),
            (eq, ":quests", "qst_blank_quest_24"),
            (str_store_string, s0, "@Dacicus"),
        (else_try),
            (str_store_string, s0, "@Parthicus"),
        (try_end),
        (try_begin),
            (eq, reg0, 0),
            (str_store_string, s1, "str_s0"),
        (else_try),
            (eq, reg0, 1),
            (str_store_string, s1, "@{s0} and {s1}"),
        (else_try),
            (str_store_string, s1, "@{s0}, {s1}"),
        (try_end),
        (val_add, reg0, 1),
    (try_end),

    (try_begin),
        (str_is_empty, s1),
        (str_store_string, s1, "@None"),
    (try_end),
]),

#script_assign_center_to_lord
("assign_center_to_lord",[
    (store_script_param, ":center_no", 1),
    #BEGIN assign lords to empty fief
    (try_begin),
        (is_between, ":center_no", walled_centers_begin,walled_centers_end),
        (neg|party_slot_ge, ":center_no", slot_town_lord, 0),

        (store_faction_of_party, ":faction", ":center_no"),
        (is_between, ":faction", kingdoms_begin, kingdoms_end),
        (try_begin),#if faction is imperial government
            (faction_slot_eq, ":faction", slot_faction_government_type, gov_imperial),
            (party_get_slot, ":province", ":center_no", slot_center_province),
            (troop_get_slot, ":governor", "trp_province_array", ":province"),

            (faction_get_slot, ":leader", ":faction", slot_faction_leader),
            (try_begin),#if there already exists a governor
                (ge, ":governor", 0),
                (try_begin),
                    (eq, ":governor", "trp_player"),
                    (assign, ":gov_faction", "$players_kingdom"),
                (else_try),
                    (store_faction_of_troop, ":gov_faction", ":governor"),
                (try_end),
                (eq, ":gov_faction", ":faction"),
                (call_script, "script_give_center_to_lord2", ":center_no", ":governor", 0),
                (str_store_troop_name, s22, ":governor"),
                (val_add, ":province", "str_province_begin"),
                (str_store_string, s23, ":province"),
                (str_store_party_name, s24, ":center_no"),
                (display_log_message, "@{s22}, governor of {s23}, integrates {s24} into his province."),
            (else_try),#there is no governor, if it is senatorial
                (lt, ":governor", 0),
                (store_add, ":slot", slot_province_senatorial_begin, ":province"),
                (troop_slot_ge, "trp_province_array", ":slot", 1),

                # (str_store_party_name, s24, ":center_no"),
                # (display_message, "@Check for {s24}"),
                #search for a new governor
                (assign, ":score", -100),
                (assign, ":candiate", -1),
                (try_for_range, ":active_npc", active_npcs_including_player_begin, heroes_end),
                    (neq, ":leader", ":active_npc"),
                    (assign, ":c", 1),
                    (try_begin),
                        (eq, ":active_npc", active_npcs_including_player_begin),
                        (assign, ":active_npc", "trp_player"),
                        (assign, ":npc_faction", "$players_kingdom"),
                        (try_begin),
                            (gt, "$g_rank", 0),#no rank
                            (assign, ":c", 0),
                        (else_try),
                            (gt, "$g_dont_give_fief_to_player_days", 0),#player has not refused a honour previously
                            (assign, ":c", 0),
                        (try_end),
                    (else_try),
                        (store_faction_of_troop, ":npc_faction", ":active_npc"),
                    (try_end),
                    (eq, ":c", 1),
                    (eq, ":npc_faction", ":faction"),#same faction

                    (this_or_next|troop_slot_eq, ":active_npc", slot_troop_occupation, slto_kingdom_hero),
                    (eq, ":active_npc", "trp_player"),

                    (neg|troop_slot_ge, ":active_npc", slot_troop_legion, 1),
                    (neg|troop_slot_ge, ":active_npc", slot_troop_aux, 1),
                    (neg|troop_slot_ge, ":active_npc", slot_troop_govern, 1),
                    # (str_store_troop_name, s22, ":active_npc"),
                    # (display_message, "@@Check for {s22}"),

                    #we can assume he has no governorship via the slot
                    #lord does not already govern a province
                    # (assign, ":end", p_provinces_end),
                    # (try_for_range, ":slot", slot_province_governor_begin, ":end"),
                        # (troop_slot_eq, "trp_province_array", ":slot", ":active_npc"),
                        # (assign, ":end", -1),
                    # (try_end),
                    # (eq, ":end", p_provinces_end),
                    # (str_store_troop_name, s22, ":active_npc"),
                    # (display_message, "@@Check for {s22} 2"),
                    (troop_get_slot, ":renown", ":active_npc", slot_troop_renown),
                    (assign, ":score_1", ":renown"),
                    #controversy is from 0 to 100
                    (troop_get_slot, ":controversy", ":active_npc", slot_troop_controversy),
                    (val_clamp, ":controversy", 0, 101),

                    (store_sub, ":modifier", 101, ":controversy"),
                    (val_mul, ":score_1", ":modifier"),
                    (val_div, ":score_1", 100),

                    (try_begin),
                        (eq, ":active_npc", "trp_player"),
                        (troop_get_slot, ":senate_support", "trp_senator_dummy", slot_senate_support),
                        (val_mul, ":score_1", ":senate_support"),
                        (val_div, ":score_1", 100),
                    (try_end),

                    (gt, ":score_1", ":score"),
                    (assign, ":score", ":score_1"),
                    (assign, ":candiate", ":active_npc"),
                (try_end),
                #governor found?
                (gt, ":candiate", -1),

                # (str_store_party_name, s24, ":center_no"),
                # (display_message, "@Check for {s24}, candiate found"),
                (try_begin),
                    (eq, ":candiate", "trp_player"),
                    (call_script, "script_add_notification_menu", "mnu_notification_player_faction_province_appointed", ":center_no", ":province"),
                (else_try),
                    (try_begin),
                        (eq, ":faction", "$players_kingdom"),
                        (eq, "$g_governor_appointment_message", 1),
                        (troop_slot_ge, "trp_senator_dummy", slot_senate_support, 20),#has some influence
                        (call_script, "script_add_notification_menu", "mnu_notification_player_faction_province_decide", ":candiate", ":province"),
                    (else_try),
                        (troop_set_slot, "trp_province_array", ":province", ":candiate"),
                        (call_script, "script_troop_set_rank", ":candiate",slot_troop_govern, ":province"),
                        (call_script, "script_give_center_to_lord2", ":center_no", ":candiate", 0),
                        (str_store_troop_name, s22, ":candiate"),
                        (val_add, ":province", "str_province_begin"),
                        (str_store_string, s23, ":province"),
                        (str_store_party_name, s24, ":center_no"),
                        (display_log_message, "@The senate has assigned {s22} the governorship of {s23}. {s24} is integrated into the newly created province."),
                    (try_end),
                (try_end),
            (else_try),#if it is imperial
                (gt, ":leader", 0),#not player
                # (str_store_party_name, s24, ":center_no"),
                # (display_message, "@Check for {s24}"),

                (try_begin), # rome goes to italy
                    (eq, ":province", p_ita_ital),
                    (assign, ":candiate", ":leader"),
                    (try_begin),
                        (troop_get_slot, ":province", ":leader", slot_troop_govern),
                        (ge, ":province", 1),

                        (try_for_range, ":center", centers_begin, centers_end),
                            (store_faction_of_party, ":center_faction", ":center"),
                            (eq, ":center_faction", ":faction"),
                            (party_slot_eq, ":center", slot_center_province, ":province"),
                            (party_set_slot, ":center", slot_town_lord, stl_unassigned),
                        (try_end),
                    (try_end),
                (else_try),
                    #search for a new governor
                    (assign, ":score", -100),
                    (assign, ":candiate", -1),
                    (try_for_range, ":active_npc", active_npcs_including_player_begin, heroes_end),
                        # (str_store_troop_name, s22, ":active_npc"),
                        # (display_message, "@@Check for {s22} 1"),
                        (assign, ":c", 1),
                        # (str_store_troop_name, s22, ":active_npc"),
                        # (display_message, "@@Check for {s22} 2"),
                        (try_begin),
                            (eq, ":active_npc", active_npcs_including_player_begin),
                            (assign, ":active_npc", "trp_player"),
                            (assign, ":npc_faction", "$players_kingdom"),
                            (try_begin),
                                (gt, "$g_rank", 0),#no rank
                                (assign, ":c", 0),
                            (else_try),
                                (gt, "$g_dont_give_fief_to_player_days", 0),#player has not refused a honour previously
                                (assign, ":c", 0),
                            (try_end),
                        (else_try),
                            (store_faction_of_troop, ":npc_faction", ":active_npc"),
                        (try_end),
                        (eq, ":c", 1),
                        # (str_store_troop_name, s22, ":active_npc"),
                        # (str_store_faction_name, s23, ":npc_faction"),
                        # (display_message, "@@Check for {s22} ({s23}) 3"),

                        (eq, ":npc_faction", ":faction"),#same faction

                        # (str_store_troop_name, s22, ":active_npc"),
                        # (display_message, "@@Check for {s22} 4"),

                        (this_or_next|troop_slot_eq, ":active_npc", slot_troop_occupation, slto_kingdom_hero),
                        (eq, ":active_npc", "trp_player"),

                        (neg|troop_slot_ge, ":active_npc", slot_troop_legion, 1),
                        (neg|troop_slot_ge, ":active_npc", slot_troop_aux, 1),
                        (neg|troop_slot_ge, ":active_npc", slot_troop_govern, 1),
                        # (str_store_troop_name, s22, ":active_npc"),
                        # (display_message, "@@Check for {s22} 5"),

                        #we can assume he has no governorship via the slot
                        #lord does not already govern a province
                        # (assign, ":end", p_provinces_end),
                        # (try_for_range, ":slot", slot_province_governor_begin, ":end"),
                            # (troop_slot_eq, "trp_province_array", ":slot", ":active_npc"),
                            # (assign, ":end", -1),
                        # (try_end),
                        # (eq, ":end", p_provinces_end),
                        # (str_store_troop_name, s22, ":active_npc"),
                        # (display_message, "@@Check for {s22} 2"),

                        (call_script, "script_troop_get_relation_with_troop", ":active_npc", ":leader"),
                        (assign, ":score_1", reg0),
                        (troop_get_slot, ":renown", ":active_npc", slot_troop_renown),
                        (val_add, ":score_1", ":renown"),
                        #controversy is from 0 to 100
                        (troop_get_slot, ":controversy", ":active_npc", slot_troop_controversy),
                        (val_clamp, ":controversy", 0, 101),

                        (store_sub, ":modifier", 101, ":controversy"),
                        (val_mul, ":score_1", ":modifier"),
                        (val_div, ":score_1", 100),

                        (gt, ":score_1", ":score"),
                        (assign, ":score", ":score_1"),
                        (assign, ":candiate", ":active_npc"),
                    (try_end),
                (try_end),
                #governor found?
                (gt, ":candiate", -1),
                # (str_store_party_name, s24, ":center_no"),
                # (display_message, "@Check for {s24}, candiate found"),
                (try_begin),#player
                    (eq, ":candiate", "trp_player"),
                    (call_script, "script_add_notification_menu", "mnu_notification_player_faction_province_appointed", ":center_no", ":province"),
                (else_try),
                    (try_begin),
                        (eq, ":faction", "$players_kingdom"),
                        (eq, "$g_governor_appointment_message", 1),
                        (troop_slot_ge, "trp_player", slot_troop_influence, 100),#has some influence
                        (call_script, "script_add_notification_menu", "mnu_notification_player_faction_province_decide", ":candiate", ":province"),
                    (else_try),
                        (call_script, "script_get_province_relation_modifier", ":province", ":candiate"),
                        (assign, ":relation_change", reg0),
                        (call_script, "script_troop_change_relation_with_troop", ":leader", ":candiate", ":relation_change"),

                        (troop_set_slot, "trp_province_array", ":province", ":candiate"),
                        (call_script, "script_troop_set_rank", ":candiate", slot_troop_govern, ":province"),
                        (call_script, "script_give_center_to_lord2", ":center_no", ":candiate", 0),
                        (str_store_troop_name, s22, ":candiate"),
                        (val_add, ":province", "str_province_begin"),
                        (str_store_string, s23, ":province"),
                        (str_store_party_name, s24, ":center_no"),
                        (str_store_troop_name, s21, ":leader"),
                        (display_log_message, "@{s21} assigns {s22} governorship of {s23}. {s24} is integrated into the newly found province."),
                    (try_end),
                (try_end),
            (try_end),
        (else_try),##if faction is not imperial give center to a lord
            (faction_get_slot, ":leader", ":faction",slot_faction_leader),
            (gt, ":leader", 0),# not player!
            (try_for_range, ":active_npc", heroes_begin, heroes_end),#Changed range to include kingdom ladies
                (troop_set_slot, ":active_npc", dplmc_slot_troop_temp_slot, 0), #this will hold distance to closest owned fief
                (troop_set_slot, ":active_npc", slot_troop_temp_slot, 0), #reset to zero
            (try_end),

            (try_for_range, ":center", walled_centers_begin, walled_centers_end),
                (store_faction_of_party, ":center_faction", ":center"),
                (eq, ":center_faction", ":faction"),
                (party_get_slot, ":lord", ":center", slot_town_lord),
                (ge, ":lord", 0),

                (try_begin),
                    (party_slot_eq, ":center", slot_party_type, spt_town),
                    (assign, ":center_value", 3),
                (else_try),
                    (party_slot_eq, ":center", slot_party_type, spt_castle),
                    (assign, ":center_value", 2),
                (else_try),
                    (assign, ":center_value", 1),
                (try_end),

                (troop_get_slot, ":temp_slot", ":lord", slot_troop_temp_slot),
                (val_add, ":temp_slot", ":center_value"),
                (troop_set_slot, ":lord", slot_troop_temp_slot, ":temp_slot"),

                (try_begin),
                    (neq, ":center", ":center_no"),
                    (troop_get_slot, ":dplmc_temp_slot", ":lord", dplmc_slot_troop_temp_slot),
                    (store_distance_to_party_from_party, ":distance", ":center", ":center_no"),
                    (gt, ":distance", 0),
                    (try_begin),
                        (eq, ":dplmc_temp_slot", 0),
                        (assign, ":dplmc_temp_slot", ":distance"),
                    (else_try),
                        (val_min, ":dplmc_temp_slot", ":distance"),
                    (try_end),
                    (troop_set_slot, ":lord", dplmc_slot_troop_temp_slot, ":dplmc_temp_slot"),
                (try_end),

            (try_end),
            (assign, ":candidate", -1),
            (assign, ":break", heroes_end),
            (assign, ":score_to_beat", 0),
            (try_for_range, ":active_npc", active_npcs_including_player_begin, ":break"),
                (gt, ":active_npc", -1),
                (assign, ":c", 1),
                (try_begin),
                    (eq, ":active_npc", active_npcs_including_player_begin),
                    (assign, ":active_npc", "trp_player"),
                    (assign, ":npc_faction", "$players_kingdom"),
                    (try_begin),
                        (gt, "$g_dont_give_fief_to_player_days", 0),
                        (assign, ":c", 0),
                    (try_end),
                (else_try),
                    (store_faction_of_troop, ":npc_faction", ":active_npc"),
                (try_end),
                (eq, ":c", 1),
                (eq, ":npc_faction", ":faction"),
                (assign, ":c", 0),
                (try_begin),
                    (troop_slot_eq, ":active_npc", slot_troop_occupation, slto_kingdom_hero),
                    (assign, ":c", 1),
                (else_try),
                    (eq, ":active_npc", "trp_player"),
                    (assign, ":c", 1),
                (try_end),
                (eq, ":c", 1),
                (try_begin),
                    (troop_slot_eq, ":active_npc", slot_troop_temp_slot,0), #has no fief, choose him
                    (assign, ":candidate", ":active_npc"),
                    (assign, ":break", -1),
                (else_try),
                    (call_script, "script_dplmc_calculate_troop_score_for_center_aux", ":leader", ":active_npc", ":center_no"),#reg0 = score, reg1 = explanation
                    (assign, ":scroe", reg0),
                    (gt, ":scroe", ":score_to_beat"),
                    (assign, ":score_to_beat", ":scroe"),
                    (assign, ":candidate", ":active_npc"),
                (try_end),
            (try_end),
            # (str_store_party_name, s23, ":center_no"),
            # (display_message, "@Search for candiate stopped, {s23}"),
            (gt, ":candidate", -1),
            # (str_store_party_name, s23, ":center_no"),
            # (str_store_troop_name, s22, ":candidate"),
            # (display_message, "@Search for candiate found: {s22}, {s23}"),
            (try_begin),
                (eq, ":candidate", "trp_player"),
                (eq, "$players_kingdom", ":faction"),
                (call_script, "script_add_notification_menu", "mnu_notification_player_faction_fief_appointed", ":center_no", 0),
            (else_try),
                (call_script, "script_give_center_to_lord2", ":center_no", ":candidate", 0), #Zero means don't add garrison
				        #If the player had requested a captured fief
                (try_begin),
                    (eq, ":center_no", "$g_castle_requested_by_player"),
                    (party_slot_ge, ":center_no", slot_town_lord, active_npcs_begin),
                    (eq, ":faction", "$players_kingdom"),
                    (assign, "$g_center_to_give_to_player", ":center_no"),
                    (try_begin),
                        (troop_get_slot, ":husband", "trp_player", slot_troop_spouse),
                        (is_between, ":husband", active_npcs_begin, active_npcs_end),
                        (eq, "$g_castle_requested_for_troop", ":husband"),
                        (neq, ":candidate", ":husband"),
                        (jump_to_menu, "mnu_requested_castle_granted_to_another_female"),
                    (else_try),
                        (jump_to_menu, "mnu_requested_castle_granted_to_another"),
                    (try_end),
                (try_end),
            (try_end),
        (try_end),
    (try_end),
    #END assign lords to empty fief
]),

#script_weekly_imperial_balance
("weekly_imperial_balance",[
    (store_script_param_1, ":faction_no"),
    #total spending
    (assign, ":total_spending", 0),
    (try_for_range, ":slot", slot_faction_hire, slot_faction_spending_diplomacy+1),
        (faction_get_slot, ":spending", ":faction_no", ":slot"),
        (val_add, ":total_spending", ":spending"),
        (faction_set_slot, ":faction_no", ":slot", 0),
    (try_end),
    #total income
    (assign, ":total_tax", 0),
    (try_for_range, ":slot", slot_faction_taxes_govern, slot_faction_taxes_diplomacy+1),
        (faction_get_slot, ":tax", ":faction_no", ":slot"),
        (val_add, ":total_tax", ":tax"),
        (faction_set_slot, ":faction_no", ":slot", 0),
    (try_end),
    #special spending: emperos pocket, can be either emperor paying into the treasury or taking money from it for himself
    (faction_get_slot, ":emperor_bocket", ":faction_no", slot_faction_emperors_bocket),
    (try_begin),#book the spending accordingly
        (neq, ":emperor_bocket", 0),
        (faction_get_slot, ":emperor", ":faction_no", slot_faction_leader),
        (try_begin),
            (gt, ":emperor", 0),
            (call_script, "script_add_to_troop_wealth", ":emperor", ":emperor_bocket"), # player emperor will be booked inside the normal bugdet_report
        (else_try),
            (eq, ":emperor", "trp_player"),
            (store_mul, ":amount_taken", ":emperor_bocket", -1),
            (call_script, "script_event_player_takes_money_imperial_treasury", ":amount_taken"), # this is the effect of taking money form the treasury
        (try_end),
    (try_end),

    (call_script, "script_calculate_imperial_corruption", ":faction_no"),
    (assign, ":corruption", reg0),
    (store_mul, ":corruption_loss", ":total_tax", ":corruption"),
    (val_div, ":corruption_loss", 100),
    (val_add, ":total_spending", ":corruption_loss"),

    (faction_get_slot, ":debts_interest", ":faction_no", slot_faction_debts),
    (val_mul, ":debts_interest", 4),
    (val_div, ":debts_interest", 100),
    (val_add, ":total_spending", ":debts_interest"),

    (val_add, ":total_tax", ":emperor_bocket"),
    # (assign, reg1, ":total_tax"),
    # (display_message, "@Total tax: {reg1}."),

    (val_sub, ":total_tax", ":total_spending"),

    # (assign, reg1, ":total_spending"),
    # (display_message, "@Total spending: {reg1}."),
    # (assign, reg1, ":debts_interest"),
    # (display_message, "@Total debts interest: {reg1}."),
    (call_script, "script_add_to_faction_treasury", ":total_tax", ":faction_no"),
]),

