#script_make_sacrifice
("make_sacrifice",[
    (store_script_param, ":amount", 1),
    (store_script_param, ":diety", 2),
    (store_script_param, ":base_cost", 3),

    (store_troop_gold, ":gold", "trp_player"),
    (store_troop_gold, ":gold_2", "trp_household_possessions"),
    (val_add, ":gold", ":gold_2"),
    (try_begin),
        (ge, ":gold", ":amount"),
        (call_script, "script_dplmc_remove_gold_from_lord_and_holdings", ":amount", "trp_player"),
        (display_message, "@The sacrifice is performed to appease the gods on your behalf."),

        (store_div, ":luck", ":base_cost", 1000),
        (store_random_in_range, ":r", 0, 75),
        (assign, reg10, ":luck"),
        (assign, reg11, ":r"),
        (display_message, "@Probability: {reg10}. Dice: {reg11}."),

        (store_attribute_level, ":ag","trp_player", ca_agility),
        (store_attribute_level, ":str","trp_player", ca_strength),
        (store_attribute_level, ":cha","trp_player", ca_charisma),
        (store_attribute_level, ":int","trp_player", ca_intelligence),
        (assign, ":randomized", -1),
        (try_begin),
            (this_or_next|eq, ":diety", worships_yhwhe),
            (this_or_next|eq, ":diety", worships_mazda),
            (this_or_next|eq, ":diety", worships_allat),
            (this_or_next|eq, ":diety", worships_ifri),
            (this_or_next|eq, ":diety", worships_ammon),
            (eq, ":diety", worships_apedemak),
            (store_random_in_range, ":randomized", 0, 4),
        (try_end),
        (store_add, ":god_name_stry", ":diety", "str_gods_begin"),
        (str_store_string, s19, ":god_name_stry"),
        (try_begin),
            (le, ":r", ":luck"),
            (try_begin),
                (this_or_next|eq, ":randomized", 0),
                (this_or_next|eq, ":diety", worships_vest),
                (this_or_next|eq, ":diety", worships_mars),
                (this_or_next|eq, ":diety", worships_goitosuros),
                (this_or_next|eq, ":diety", worships_gebeleizis),
                (eq, ":diety", worships_baduhenna),
                (lt, ":str", 35),
                (troop_raise_attribute, "trp_player", ca_strength, 1),
                (display_message, "@{s19} guards you in fight"),
            (else_try),
                (this_or_next|eq, ":randomized", 1),
                (this_or_next|eq, ":diety", worships_aphrodite),
                (this_or_next|eq, ":diety", worships_jupiter),
                (this_or_next|eq, ":diety", worships_armazi),
                (this_or_next|eq, ":diety", worships_andraste),
                (eq, ":diety", worships_dunraz),
                (lt, ":cha", 35),
                (troop_raise_attribute, "trp_player", ca_charisma, 1),
                (display_message, "@{s19} help you to lead"),
            (else_try),
                (this_or_next|eq, ":randomized", 2),
                (this_or_next|eq, ":diety", worships_castor_pollux),
                (this_or_next|eq, ":diety", worships_artimpasa),
                (this_or_next|eq, ":diety", worships_maponos),
                (eq, ":diety", worships_alcis),
                (lt, ":ag", 35),
                (troop_raise_attribute, "trp_player", ca_agility, 1),
                (display_message, "@{s19} favour you"),
            (else_try),
                (this_or_next|eq, ":randomized", 3),
                (this_or_next|eq, ":diety", worships_saturn),
                (this_or_next|eq, ":diety", worships_mithras),
                (this_or_next|eq, ":diety", worships_mihr),
                (this_or_next|eq, ":diety", worships_zalmoxis),
                (eq, ":diety", worships_frijo),
                (lt, ":int", 35),
                (troop_raise_attribute, "trp_player", ca_intelligence, 1),
                (display_message, "@{s19} blesses your mind"),
            (else_try),
                (add_xp_to_troop, 500),
                (display_message, "@{s19} gives you experience"),
            (try_end),
        (else_try),
            (add_xp_to_troop, 100),
            (display_message, "@{s19} gives you experience"),
        (try_end),
        (assign, "$can_sacrific", 0),
        (assign, ":piety", 1),
        (assign, ":reputation", 1),
        (assign, ":renown", 2),
        (try_begin),
            (eq, ":base_cost", small_sacrifice_cost),
            (assign, ":piety", 3),
            (assign, ":reputation", 1),
            (assign, ":renown", 2),
        (else_try),
            (eq, ":base_cost", medium_sacrifice_cost),
            (assign, ":piety", 7),
            (assign, ":reputation", 2),
            (assign, ":renown", 5),
        (else_try),
            (eq, ":base_cost", large_sacrifice_cost),
            (assign, ":piety", 20),
            (assign, ":reputation", 4),
            (assign, ":renown", 10),
        (else_try),
            (eq, ":base_cost", huge_sacrifice_cost),
            (assign, ":piety", 35),
            (assign, ":reputation", 6),
            (assign, ":renown", 15),
        (try_end),
        # (call_script, "script_add_piety", ":piety", 1),
        (call_script, "script_add_piety_culture_effect", ":piety", ":diety"),
        (call_script, "script_change_player_honor", ":reputation"),
        (call_script, "script_change_troop_renown", "trp_player", ":renown"),

        (try_for_range, ":festival_quest", festival_quests_begin, festival_quests_end),
            (check_quest_active, ":festival_quest"),
            (quest_get_slot, ":quest_diety", ":festival_quest", slot_quest_temp_slot),
            (eq, ":quest_diety", ":diety"),
            (quest_set_slot, ":festival_quest", slot_quest_temp_slot, 0),
            (display_message, "str_quest_log_updated"),
            (add_xp_as_reward, 1500),
            (add_quest_note_from_sreg, ":festival_quest", 4, "@You performed a sacrifice!", 0),
        (try_end),
    (else_try),
        (display_message, "str_not_enough_gold"),
        (call_script, "script_change_troop_renown", "trp_player", -25),
    (try_end),
]),
#script_add_piety
("add_piety", [
    (store_script_param, ":amount", 1),
    (store_script_param, ":display_message", 2),
    (try_begin),
        (gt, ":amount", 0),
        (ge, "$player_piety", 200),
        (store_div, ":subtraction", "$player_piety", 200),
        (val_sub, ":amount", ":subtraction"),
        (val_max, ":amount", 1),
    (try_end),
    #Exacerbate the effect of pietas losses as the player's pietas increases
    #also increase positive effect if pietas is very low
    (try_begin),
        (ge, "$player_piety", 150),
        (lt, ":amount", 0),
        (store_add, ":subtraction", "$player_piety", 10),
        (val_mul, ":amount", ":subtraction"),
        (val_sub, ":amount", 50),
        (val_div, ":amount", 100),
    (else_try),
        (lt, "$player_piety", 75),
        (gt, ":amount", 0),
        (store_sub, ":subtraction", 75, "$player_piety"),
        (val_add, ":subtraction", 100),
        (val_mul, ":amount", ":subtraction"),
        (val_sub, ":amount", 50),
        (val_div, ":amount", 100),
    (try_end),

    (val_add, "$player_piety", ":amount"),
    (val_max, "$player_piety", 0),
    (try_begin),
        (eq, ":display_message", 1),
        (assign, reg0, ":amount"),
        (try_begin),
            (ge, ":amount", 1),
            (display_message, "@You gained {reg0} pietas!", color_good_news),
        (else_try),
            (le, ":amount", -1),
            (display_message, "@You lost {reg0} pietas!", color_terrible_news),
        (try_end),
    (try_end),
]),
