    (try_end),
    # copy diplomatic situation of rome?
    # (try_for_range, ":slot", 0, 500),
    #     (neq, ":slot", slot_faction_leader),
    #     (faction_get_slot, ":value", "fac_kingdom_7", ":slot"),
