# script_get_list_of_legions
("get_list_of_legions_s1",[
    (store_script_param, ":faction", 1),
    (str_clear, s1),
    (assign, ":counter", 0),
    (try_for_range, ":commander_slot", slot_legion_commanders_begin, slot_legion_commanders_end),
        (troop_get_slot, ":commander", "trp_province_array", ":commander_slot"),
        (is_between, ":commander", active_npcs_begin, active_npcs_end),
        (store_faction_of_troop, ":commander_faction", ":commander"),
        (eq, ":faction", ":commander_faction"),
        (store_sub, ":legion", ":commander_slot", slot_legion_commanders_begin),
        (try_begin),
            (eq, ":legion", 13),
            (str_store_troop_name, s0, "trp_players_legion"),
        (else_try),
            (val_add, ":legion", "str_legion_names_begin"),
            (str_store_string, s0, ":legion"),
        (try_end),
        (try_begin),
            (eq, ":counter", 0),
            (str_store_string, s1, "str_s0"),
        (else_try),
            (eq, ":counter", 1),
            (str_store_string, s1, "@{s0} and {s1}"),
        (else_try),
            (str_store_string, s1, "@{s0}, {s1}"),
        (try_end),
        (val_add, ":counter", 1),
    (try_end),
    (try_begin),
        (str_is_empty, s1),
        (str_store_string, "str_noone"),
    (try_end),
]),

#script_switch_legion_to_faction
("switch_legion_to_faction",[
    (store_script_param, ":legion", 1),
    (store_script_param, ":faction", 2),
    (store_add, ":slot", slot_legion_commanders_begin, ":legion"),#Alaudae
    (troop_get_slot, ":legate", "trp_province_array", ":slot"),

    (try_begin),
        (is_between, ":legate", active_npcs_begin, active_npcs_end),

        (try_for_range, ":aux_commander_slot", slot_aux_commander_begin, slot_aux_commander_end),
            (store_sub, ":aux_legion_slot", ":aux_commander_slot", slot_aux_commander_begin),
            (val_add, ":aux_legion_slot", slot_aux_legion_begin),
            (troop_slot_eq, "trp_province_array", ":aux_legion_slot", ":legion"),
            (troop_get_slot, ":aux_comander", "trp_province_array", ":aux_commander_slot"),
            (is_between, ":aux_comander", active_npcs_begin, active_npcs_end),

            (troop_get_slot, ":aux", ":aux_comander",slot_troop_aux),
            (ge, ":aux", 1),

            (call_script, "script_change_troop_faction", ":aux_comander", ":faction"),
            (troop_set_slot, ":aux_comander", slot_troop_occupation, slto_kingdom_hero),
            (str_store_string, s28, ":aux"),
            (str_store_troop_name, s0, ":aux_comander"),
            (str_store_string, s29, "@{s28}, commanded by {s0} switches sides as related legion does."),
        (try_end),

        (call_script, "script_change_troop_faction", ":legate", ":faction"),
        (troop_set_slot, ":legate", slot_troop_occupation, slto_kingdom_hero),
    (else_try),
        (val_add, ":legion", "str_legion_names_begin"),
        (str_store_string, s14, ":legion"),
        (str_store_string, s15, "str_noone"),
        (try_begin),
            (ge, ":legate", 0),
            (str_store_troop_name, s15, ":legate"),
        (try_end),
        (display_message, "@Could not switch legion {s14} with legate {15}"),
    (try_end),
]),

# script_find_new_commander_for_legion
("find_new_commander_for_legion",[
    (store_script_param, ":legion", 1),
    (store_script_param, ":faction", 2),

    (store_add, ":slot_legion_commander", slot_legion_commanders_begin, ":legion"),

    (assign, ":score_to_beat", -1000),
    (assign, ":candiate", -1),
    (faction_get_slot, ":faction_leader", ":faction", slot_faction_leader),
    (try_for_range, ":active_npc", active_npcs_begin, active_npcs_end),
        (store_faction_of_troop, ":fac", ":active_npc"),
        (eq, ":fac", ":faction"),#same faction
        (neq, ":faction_leader", ":active_npc"),
        (neg|troop_slot_ge, ":active_npc", slot_troop_legion, 1),
        (neg|troop_slot_ge, ":active_npc", slot_troop_aux, 1),
        (neg|troop_slot_ge, ":active_npc", slot_troop_govern, 1),
        (troop_slot_eq, ":active_npc", slot_troop_occupation, slto_kingdom_hero),# alive
        (call_script, "script_troop_get_family_relation_to_troop", ":faction_leader", ":active_npc"),
        (assign, ":score", reg0),
        (call_script, "script_troop_get_relation_with_troop", ":faction_leader", ":active_npc"),
        (val_add, ":score", reg0),

        # (str_store_troop_name, s2, ":active_npc"),
        # (assign, reg1, ":score"),
        # (display_message, "@Checking: {s2}, score: {reg1}"),

        (ge, ":score", ":score_to_beat"),
        (assign, ":score_to_beat", ":score"),
        (assign, ":candiate", ":active_npc"),
    (try_end),

    (try_begin),
        (gt, ":candiate", -1),
        # only perform the change if there is a canditate
        (troop_get_slot, ":old_commander", "trp_province_array", ":slot_legion_commander"),
        (try_begin),
            (gt, ":old_commander", -1),
            (call_script, "script_troop_set_rank", ":old_commander", slot_troop_legion, -1),
            (call_script, "script_change_lord_party_to_fit_rank", ":old_commander"),
            (str_store_troop_name, s2, ":old_commander"),
            (display_message, "@Old commander {s2} was dismissed."),
        (try_end),

        (call_script, "script_troop_set_rank", ":candiate", slot_troop_legion, ":legion"),
        (call_script, "script_change_lord_party_to_fit_rank", ":candiate"),
        (troop_set_slot, "trp_province_array", ":slot_legion_commander", ":candiate"),

        (str_store_troop_name, s1, ":candiate"),
        (str_store_faction_name, s2, ":faction"),
        (store_add, ":legion_string", "str_legion_names_begin", ":legion"),
        (str_store_string, s3, ":legion_string"),
        (display_log_message, "@{s1} ({s2}) is new commander of {s3}.", message_alert),
    (try_end),
]),

# script_find_new_commander_for_aux
("find_new_commander_for_aux",[
    (store_script_param, ":auxiliar", 1),
    (store_script_param, ":faction", 2),

    (assign, ":score_to_beat", -1000),
    (assign, ":candiate", -1),
    (faction_get_slot, ":faction_leader", ":faction", slot_faction_leader),
    (try_for_range, ":active_npc", active_npcs_begin, active_npcs_end),
        (store_faction_of_troop, ":fac", ":active_npc"),
        (eq, ":fac", ":faction"),#same faction
        (neq, ":faction_leader", ":active_npc"),
        (neg|troop_slot_ge, ":active_npc", slot_troop_legion, 1),
        (neg|troop_slot_ge, ":active_npc", slot_troop_aux, 1),
        (neg|troop_slot_ge, ":active_npc", slot_troop_govern, 1),
        (troop_slot_eq, ":active_npc", slot_troop_occupation, slto_kingdom_hero),# alive
        (call_script, "script_troop_get_relation_with_troop", ":faction_leader", ":active_npc"),
        (assign, ":score", reg0),
        (troop_get_slot, ":renown", ":active_npc", slot_troop_renown),
        (val_add, ":score", ":renown"),
        (ge, ":score", ":score_to_beat"),
        (assign, ":score_to_beat", ":score"),
        (assign, ":candiate", ":active_npc"),
    (try_end),

    (try_begin),
        (gt, ":candiate", -1),

        (store_add, ":aux_commander_slot", slot_aux_commander_begin, ":auxiliar"),
        (val_sub, ":aux_commander_slot", "pt_cohors_aux"),
        (troop_get_slot, ":old_commander", "trp_province_array", ":aux_commander_slot"),
        (try_begin),
            (gt, ":old_commander", -1),
            (call_script, "script_troop_set_rank", ":old_commander", slot_troop_aux, -1),
            (call_script, "script_change_lord_party_to_fit_rank", ":old_commander"),
            (str_store_troop_name, s2, ":old_commander"),
            (display_message, "@Old commander {s2} was dismissed."),
        (try_end),

        (call_script, "script_troop_set_rank", ":candiate", slot_troop_aux, ":auxiliar"),
        (call_script, "script_change_lord_party_to_fit_rank", ":candiate"),
        (troop_set_slot, "trp_province_array", ":aux_commander_slot", ":candiate"),

        (str_store_troop_name, s1, ":candiate"),
        (str_store_faction_name, s2, ":faction"),
        (store_sub, ":aux_string", ":auxiliar", "pt_cohors_aux"),
        (val_add, ":aux_string", "str_cohors_aux"),
        (try_begin),
            (eq, ":aux_string", "str_player_aux_cav"),
            (str_store_troop_name, s1, "trp_players_aux_cav"),
        (else_try),
            (eq, ":aux_string", "str_player_aux_inf"),
            (str_store_troop_name, s1, "trp_players_aux_inf"),
        (try_end),
        (str_store_string, s3, ":aux_string"),
        (display_log_message, "@{s1} ({s2}) is new commander of {s3}.", message_alert),
    (try_end),
]),

