# script_cf_can_kill_troop
("cf_can_kill_troop",[
    (store_script_param, ":troop", 1),
    (assign, ":c", 1),
    (try_begin),
        (this_or_next|eq, ":troop", "trp_kingdom_1_lady_1"),
        (this_or_next|eq, ":troop", "trp_kingdom_7_lord"),
        (this_or_next|eq, ":troop", "trp_senator_1"),
        (this_or_next|eq, ":troop", "trp_senator_5"),
        (this_or_next|eq, ":troop", "trp_legatus_11"),
        (eq, ":troop", "trp_senator_2"),
        (eq, "$g_campaign_type", g_campaign_story_rome),
        (assign, ":c", 0),
    (try_end),
    (eq, ":c", 1),
]),

# script_spawn_agent_unique_face
# will destroy the face keys of the troop
("spawn_agent_unique_face",[
    (store_script_param, ":troop", 1),
    (store_script_param, ":randomize_face", 2),
    (store_script_param, ":type", 3),

    # (str_store_troop_face_keys, s69, ":troop", 0),
    # (troop_set_face_keys, "trp_merchants_end", s69, 0),
    # (str_store_troop_face_keys, s69, ":troop", 1),
    # (troop_set_face_keys, "trp_merchants_end", s69, 1),

    (try_begin),
        (eq, ":randomize_face", 1),
        (try_begin),
            (call_script, "script_cf_dplmc_troop_is_female", ":troop"),
            (try_begin),
                (eq, ":type", white),
                (store_random_in_range, ":face", white_faces_begin, white_faces_end),
            (else_try),
                (eq, ":type", brown),
                (store_random_in_range, ":face", brown_faces_begin, brown_faces_end),
            (else_try),
                (eq, ":type", black),
                (store_random_in_range, ":face", black_faces_begin, black_faces_end),
            (else_try),
                (store_random_in_range, ":face", white_faces_begin, black_faces_end),
            (try_end),
            (str_store_string, s68, ":face"),
            # (display_message, "@Selected face before: {s68}"),
            (face_keys_set_age, s68, 0),
            (troop_set_age, ":troop", 0),
            (troop_set_face_keys, ":troop", s68, 0),
            (troop_set_face_keys, ":troop", s68, 1),
            # (display_message, "@Selected face after: {s68}"),
        # (else_try),
        #     (display_message, "@Error: No male faces! At: script_spawn_agent_unique_face"),
        (try_end),
    (try_end),

    (spawn_agent, ":troop"),
    (assign,":agent",reg0),

    # (str_store_troop_face_keys, s69, "trp_merchants_end", 0),
    # (troop_set_face_keys, ":troop", s69, 0),
    # (str_store_troop_face_keys, s69, "trp_merchants_end", 1),
    # (troop_set_face_keys, ":troop", s69, 1),

    (assign, reg0, ":agent"),
]),

