#script_perform_miracle
("perform_miracle",[
    (store_script_param, ":miracle", 1),
    (troop_get_slot,":god", "trp_player", slot_troop_religion),
    (store_add, ":string", ":god", "str_gods_begin"),
    (str_store_string, s30, ":string"),
    (try_begin),
        (eq, ":miracle", miracle_battle_heal),
        (get_player_agent_no, ":player_agent"),
        (agent_set_damage_modifier, ":player_agent", 250),
        (display_message, "@{s30} increases your strength!", color_good_news),
    (else_try),
        (eq, ":miracle", miracle_battle_morale),
        (store_party_size_wo_prisoners, ":men", "p_main_party"),
        (ge, ":men", 10),
        (try_for_agents, ":cur_agent"),#effect
            (agent_is_human, ":cur_agent"),
            (agent_is_alive, ":cur_agent"),
            (agent_is_active,":cur_agent"),
            (agent_is_ally, ":cur_agent"),
            (agent_set_slot, ":cur_agent", slot_agent_courage_score, max_morale),
        (try_end),
        (display_message, "@{s30} gives your troops courage!", color_good_news),
    (else_try),
        (eq, ":miracle", miracle_battle_strength),
        (store_troop_health, ":h", "trp_player"),
        (le, ":h", 90),
        (get_player_agent_no, ":player_agent"),
        (agent_set_hit_points, ":player_agent", 100),
        (troop_set_health, "trp_player", 100),
        (display_message, "@{s30} heals you!", color_good_news),
    (else_try),
        (display_message, "@{s30} is watching your actions", color_good_news),
    (try_end),
]),

