            (this_or_next|faction_slot_eq, ":lord_faction", slot_faction_marshall, reg5),
            (this_or_next|troop_slot_ge, reg5, slot_troop_renown, reg0),
            (is_between, ":lord", kingdom_ladies_begin, kingdom_ladies_end),
