        (try_end),
        (gt, ":impressive_relative", -1),
        (call_script, "script_dplmc_troop_get_family_relation_to_troop", ":lord", ":impressive_relative"),
        (str_store_string, s8, reg1),
        (str_store_troop_name, s9, ":impressive_relative"),
