# script_reactivate_kingdom
("reactivate_kingdom",[
    (store_script_param, ":cur_kingdom", 1),
    (store_script_param, ":liberate_faction", 2),
    (store_script_param, ":new_center", 3),
    (faction_set_slot, ":cur_kingdom", slot_faction_state, sfs_active),
    (str_store_faction_name, s35, ":cur_kingdom"),
    (display_log_message, "@The {s35} has been restored."),
    (faction_get_slot,":king", ":cur_kingdom", slot_faction_leader),
    (try_begin),
        (eq, ":king", -1),
        (display_message, "@Error: They have no king", color_bad_news),
    (else_try),
        (store_troop_faction, ":troop_faction", ":king"),
        (this_or_next|troop_slot_eq, ":king", slot_troop_occupation, dplmc_slto_exile),
        (this_or_next|eq, ":troop_faction", "fac_outlaws"),
        (eq, ":troop_faction", "fac_commoners"),
        #Now actually change the faction
        (call_script, "script_change_troop_faction", ":king", ":cur_kingdom"),
        (troop_set_slot, ":king", slot_troop_occupation, slto_kingdom_hero),
        #Log event
        (str_store_troop_name_link, s4, ":king"),
        (str_store_faction_name_link, s5, ":cur_kingdom"),
        (faction_get_color, ":color", ":cur_kingdom"),
        (display_log_message, "@{s4} has has returned to {s5}.", ":color"),
        # lord party settings
        (troop_set_slot, ":king", slot_troop_spawned_before, 0),
        (troop_get_slot, ":led_party", ":king", slot_troop_leaded_party),
        (call_script, "script_destroy_party", ":led_party"),
        (troop_set_slot, ":king", slot_troop_leaded_party, -1),
    (else_try),
        (troop_slot_eq, ":king", slot_troop_occupation, dplmc_slto_dead),
        (store_random_in_range, ":age", 20, 40),
        (call_script, "script_give_birth_to_lord", ":king", ":cur_kingdom", ":age"),
    (try_end),
    (try_begin),
        (is_between, ":new_center", walled_centers_begin, walled_centers_end),
        (gt, ":king", 0),
        (call_script, "script_give_center_to_lord2", ":new_center", ":king", 1),
    (try_end),
    (try_for_range, ":cur_troop_2", active_npcs_begin, active_npcs_end),
        (troop_slot_eq,":cur_troop_2",slot_troop_original_faction,":cur_kingdom"),
        (neg|troop_slot_ge, ":cur_troop_2", slot_troop_legion, 1), #no legions or aux commanders
        (neg|troop_slot_ge, ":cur_troop_2", slot_troop_aux, 1),   #no legions or aux commanders
        (neg|troop_slot_ge, ":cur_troop_2", slot_troop_govern, 1), #no governors
        (try_begin),
            (troop_slot_eq, ":cur_troop_2", slot_troop_occupation, dplmc_slto_dead),
            (store_random_in_range, ":age", 16, 36),
            (call_script, "script_give_birth_to_lord", ":cur_troop_2", ":cur_kingdom", ":age"),
        (try_end),
        #set up other lords for transfer
        (try_begin),##lords from other factions
            (troop_slot_eq, ":cur_troop_2", slot_troop_occupation, slto_kingdom_hero),
            (neq, ":cur_troop_2", ":king"),
            (store_troop_faction, ":faction_no_2", ":cur_troop_2"),
            (neq, ":faction_no_2", ":cur_kingdom"),
            (troop_get_slot, ":wealth", ":cur_troop_2", slot_troop_wealth),
            (val_add, ":wealth", 10000),
            (troop_set_slot, ":cur_troop_2", slot_troop_wealth, ":wealth"),
            (troop_set_slot, ":cur_troop_2", slot_troop_change_to_faction, ":cur_kingdom"),
        (else_try),##exiled lords come back
            (troop_slot_eq, ":cur_troop_2", slot_troop_occupation, dplmc_slto_exile),
            (call_script, "script_dplmc_lord_return_from_exile", ":cur_troop_2", ":cur_kingdom"),
        (try_end),
        #transfer lords
    (try_end),
    (try_begin),
        (is_between, ":liberate_faction", kingdoms_begin, kingdoms_end),
        (call_script, "script_add_notification_menu", "mnu_notification_kingdom_liberated", ":cur_kingdom", ":liberate_faction"),
    (else_try),
        (call_script, "script_add_notification_menu", "mnu_notification_kingdom_restored", ":cur_kingdom", 0),
    (try_end),
]),
# script_change_culture_of_center
("change_culture_of_center",[
    (store_script_param, ":center_no", 1),
    (store_script_param, ":culture", 2),

    (str_store_party_name, s0, ":center_no"),
    (str_store_faction_name, s1, ":culture"),
    (party_get_slot, ":orig_culture", ":center_no", slot_center_culture),
    (str_store_faction_name, s2, ":orig_culture"),
    (display_log_message, "@{s0} changed from {s2} to {s1} culture.", message_alert),

    (party_set_slot, ":center_no", slot_center_culture, ":culture"),

    (try_for_range, ":walker_no", 0, num_town_walkers),
        (call_script, "script_center_set_walker_to_type", ":center_no", ":walker_no", walkert_default),
    (try_end),

    # update scene: for now only if romanizing barbarian villages or forts
    (try_begin),
        (party_get_slot, ":original_faction", ":center_no", slot_center_original_faction),
        (is_between, ":original_faction", kingdoms_begin, kingdoms_end),
        (faction_get_slot, ":original_culture", ":original_faction", slot_faction_culture),
        (is_between, ":original_culture", cultures_begin, cultures_end),

        (try_begin),
            (eq, ":culture", "fac_culture_roman"),

            (this_or_next|eq, ":original_culture", "fac_culture_celtic"),
            (this_or_next|eq, ":original_culture", "fac_culture_germanic"),
            (eq, ":original_culture", "fac_culture_dacian"),

            (try_begin),
                (party_slot_eq, ":center_no", slot_party_type, spt_village),

                (try_begin),# not set yet
                    (party_slot_eq, ":center_no", slot_town_center_original, 0),
                    (party_get_slot, ":old_scene", ":center_no", slot_town_center),
                    (party_set_slot, ":center_no", slot_town_center_original, ":old_scene"),
                (try_end),

                (party_set_slot, ":center_no", slot_town_center, "scn_romanized_celt_village"),
            (else_try),
                (party_slot_eq, ":center_no", slot_party_type, spt_castle),
                (try_begin),# not set yet
                    (party_slot_eq, ":center_no", slot_town_center_original, 0),
                    (party_get_slot, ":old_scene", ":center_no", slot_town_center),
                    (party_set_slot, ":center_no", slot_town_center_original, ":old_scene"),
                (try_end),

                (try_begin),# not set yet
                    (party_slot_eq, ":center_no", slot_town_castle_original, 0),
                    (party_get_slot, ":old_scene", ":center_no", slot_town_castle),
                    (party_set_slot, ":center_no", slot_town_castle_original, ":old_scene"),
                (try_end),

                (try_begin),# not set yet
                    (party_slot_eq, ":center_no", slot_town_prison_original, 0),
                    (party_get_slot, ":old_scene", ":center_no", slot_town_prison),
                    (party_set_slot, ":center_no", slot_town_prison_original, ":old_scene"),
                (try_end),

                (party_set_slot, ":center_no", slot_town_center, "scn_romanized_celt_castle_ext"),#londinium
                (party_set_slot, ":center_no", slot_town_castle, "scn_romanized_celt_castle_int"),#londinium
                (party_set_slot, ":center_no", slot_town_prison, "scn_romanized_celt_castle_prison"),#londinium

                (call_script, "script_set_icon_for_walled_center", ":culture", ":center_no"),
            (try_end),
        (else_try),
        # otherwise set old slots if available if new culture = original culture
            (eq, ":original_culture", ":culture"),
            (this_or_next|party_slot_eq, ":center_no", slot_party_type, spt_village),
            (party_slot_eq, ":center_no", slot_party_type, spt_castle),
            (try_begin),
                (party_get_slot, ":old_scene", ":center_no", slot_town_center_original),
                (ge, ":old_scene", 1),
                (party_set_slot, ":center_no", slot_town_center, ":old_scene"),
            (try_end),
            (try_begin),
                (party_get_slot, ":old_scene", ":center_no", slot_town_castle_original),
                (ge, ":old_scene", 1),
                (party_set_slot, ":center_no", slot_town_castle, ":old_scene"),
            (try_end),
            (try_begin),
                (party_get_slot, ":old_scene", ":center_no", slot_town_prison_original),
                (ge, ":old_scene", 1),
                (party_set_slot, ":center_no", slot_town_prison, ":old_scene"),
            (try_end),
            (try_begin),
                (party_get_slot, ":old_scene", ":center_no", slot_town_tavern_original),
                (ge, ":old_scene", 1),
                (party_set_slot, ":center_no", slot_town_tavern, ":old_scene"),
            (try_end),
            (try_begin),
                (party_get_slot, ":old_scene", ":center_no", slot_town_store_original),
                (ge, ":old_scene", 1),
                (party_set_slot, ":center_no", slot_town_store, ":old_scene"),
            (try_end),
            (try_begin),
                (party_get_slot, ":old_scene", ":center_no", slot_town_arena_original),
                (ge, ":old_scene", 1),
                (party_set_slot, ":center_no", slot_town_arena, ":old_scene"),
            (try_end),
            (try_begin),
                (party_get_slot, ":old_scene", ":center_no", slot_town_walls_original),
                (ge, ":old_scene", 1),
                (party_set_slot, ":center_no", slot_town_walls, ":old_scene"),
            (try_end),
            (try_begin),
                (party_slot_eq, ":center_no", slot_party_type, spt_castle),
                (call_script, "script_set_icon_for_walled_center", ":culture", ":center_no"),
            (try_end),
        (try_end),
    (try_end),

    (call_script, "script_update_town_watch", ":center_no"),
]),

