#script_remove_office_from_troop
("remove_office_from_troop",[
    (store_script_param, ":troop_id", 1),
    (store_script_param, ":office", 2),

    (try_begin),
        (eq, ":troop_id", "trp_player"),
        (assign, ":troop_faction", "$players_kingdom"),
    (else_try),
        (store_faction_of_troop, ":troop_faction", ":troop_id"),
    (try_end),

    (try_begin),
        (this_or_next|eq, ":office", remove_all),
        (eq, ":office", remove_governor),
        (try_for_range, ":province", slot_province_governor_begin, p_provinces_end),
            # (store_add, ":slot", ":province", slot_province_senatorial_begin),
            # (troop_slot_ge, "trp_province_array", ":slot", 1),
            (troop_slot_eq, "trp_province_array", ":province", ":troop_id"),
            (troop_set_slot, "trp_province_array", ":province", -1),
            (store_add, ":string", ":province", "str_province_begin"),
            (str_store_string, s30, ":string"),
            (display_log_message, "@You are no longer the governor of {s30}."),
            (try_for_range, ":center", centers_begin, centers_end),
                (party_slot_eq, ":center", slot_center_province, ":province"),
                (party_slot_eq, ":center", slot_town_lord, ":troop_id"),
                (call_script, "script_give_center_to_faction", ":center", "fac_neutral"),
                (call_script, "script_give_center_to_faction", ":center", ":troop_faction"),
            (try_end),
            (call_script, "script_change_senate_support", -5, 0),
            (try_begin),
                (eq, ":troop_id", "trp_player"),
                (tutorial_box, "@You are no longer the governor of {s30}."),
            (try_end),
        (try_end),
        (call_script, "script_troop_set_rank", ":troop_id", slot_troop_govern, -1),
    (try_end),

    (try_begin),
        (this_or_next|eq, ":office", remove_all),
        (eq, ":office", remove_military),

        (troop_set_slot, "trp_global_variables", g_global_player_office, "$g_rank"),
        (try_begin),
            (eq, ":troop_id", "trp_player"),
            (ge, "$g_rank", 1),
            (display_log_message, "@You have been dismissed from service and won't recieve salery anymore."),
            (assign, "$g_rank", 0),
        (try_end),
        (try_begin),
            (troop_get_slot, ":auxiliar", ":troop_id", slot_troop_aux),
            (call_script, "script_troop_set_rank", ":troop_id", slot_troop_aux, -1),
            (call_script, "script_find_new_commander_for_aux", ":auxiliar", ":troop_faction"),
        (else_try),
            (troop_get_slot, ":legion", ":troop_id", slot_troop_legion),
            (call_script, "script_troop_set_rank", ":troop_id", slot_troop_legion, -1),
            (call_script, "script_find_new_commander_for_legion", ":legion", ":troop_faction"),
        (try_end),
        (try_begin),# resign as marshal
            (faction_slot_eq, ":troop_faction", slot_faction_marshall, ":troop_id"),
            (call_script, "script_faction_dismisses_marshall", ":troop_faction"),
        (try_end),
    (try_end),

    (try_begin),
        (this_or_next|eq, ":office", remove_all),
        (eq, ":office", remove_honorary),

        (troop_get_slot, ":title", ":troop_id", slot_troop_honorary_title),
        (ge, ":title", 1),
        (call_script, "script_ai_assign_title", ":title", ":troop_faction", ":troop_id", 0, 1),
    (try_end),

    (try_begin),
        (eq, ":troop_id", "trp_player"),
        (assign, "$g_dont_give_fief_to_player_days", 30),
    (try_end),
]),

