# script_get_slave_merchant_troop
("get_slave_merchant_troop", [
    (store_script_param, ":party", 1),
    (try_begin),
        (is_between, ":party", walled_centers_begin, walled_centers_end),
        (store_sub, ":offset", ":party", walled_centers_begin),
        (store_add, reg0, slave_traders_centers_begin, ":offset"),
    (else_try),
        (party_get_template_id, ":template", ":party"),
        (eq, ":template", "pt_steppe_bandit_lair"),
        (assign, reg0, "trp_slave_trader_alans"),
    (else_try),
        (eq, ":template", "pt_taiga_bandit_lair"),
        (assign, reg0, "trp_slave_trader_illyrian"),
    (else_try),
        (eq, ":template", "pt_desert_bandit_lair"),
        (assign, reg0, "trp_slave_trader_arab"),
    (else_try),
        (eq, ":template", "pt_egyptian_bandit_lair"),
        (assign, reg0, "trp_slave_trader_egyptian"),
    (else_try),
        (eq, ":template", "pt_nabatean_lair"),
        (assign, reg0, "trp_slave_trader_nabatean"),
    (else_try),
        (eq, ":template", "pt_nubian_lair"),
        (assign, reg0, "trp_slave_trader_nubian"),
    (else_try),
        (eq, ":template", "pt_numidian_bandit_lair"),
        (assign, reg0, "trp_slave_trader_garamantian"),
    (else_try),
        (eq, ":template", "pt_gaetuli_bandit_lair"),
        (assign, reg0, "trp_slave_trader_gaetulian"),
    (else_try),
        (eq, ":template", "pt_forest_bandit_lair"),
        (assign, reg0, "trp_slave_trader_hispanic"),
    (else_try),
        (eq, ":template", "pt_mountain_bandit_lair"),
        (assign, reg0, "trp_slave_trader_judean"),
    (else_try),
        (eq, ":template", "pt_sea_raider_lair"),
        (assign, reg0, "trp_slave_trader_sea_raiders"),
    (else_try),
        (eq, ":template", "pt_black_sea_pirates_lair"),
        (assign, reg0, "trp_slave_trader_black_sea"),
    (else_try),
        (eq, ":template", "pt_saka_camp"),
        (assign, reg0, "trp_slave_trader_saka"),
    (else_try),
        (party_get_slot, ":culture", ":party", slot_center_culture),
        (eq, ":culture", "fac_culture_arabian"),
        (assign, reg0, "trp_slave_trader_arab"),
    (else_try),
        (party_get_slot, ":culture", ":party", slot_center_culture),
        (eq, ":culture", "fac_culture_berber"),#Berber
        (assign, reg0, "trp_slave_trader_gaetulian"),
    (else_try),
        (party_get_slot, ":culture", ":party", slot_center_culture),
        (eq, ":culture", "fac_culture_garmantian"),#Garmantian
        (assign, reg0, "trp_slave_trader_garamantian"),
    (else_try),
        (party_get_slot, ":culture", ":party", slot_center_culture),
        (eq, ":culture", "fac_culture_nubian"),#Nubian
        (assign, reg0, "trp_slave_trader_nubian"),
    (else_try),
        (party_get_slot, ":culture", ":party", slot_center_culture),
        (eq, ":culture", "fac_culture_saka"),#Saka
        (assign, reg0, "trp_slave_trader_saka"),
    (else_try),
        (assign, reg0, "trp_slave_trader_bandit"),
    (try_end),
]),

