#script_assign_household_slave
("assign_household_slave", [
    (store_script_param, ":troop", 1),
    (store_script_param, ":is_dialogue", 2),
    (assign, ":break", household_slaves_end),
    (try_for_range, ":slave", household_slaves_begin, ":break"),
        (troop_slot_eq, ":slave", slot_slave_template_troop, 0),
        (troop_set_slot, ":slave", slot_slave_template_troop, ":troop"),

        ## copy inventory
        (troop_clear_inventory, ":slave"),
        (call_script, "script_dplmc_copy_inventory", ":troop", ":slave"),

        (troop_get_type, ":race", ":troop"),
        (troop_set_type, ":slave", ":race"),

        ## copy face
        (try_begin),
            (eq, ":is_dialogue", 1),
            (agent_is_active, "$g_talk_agent"),
            (str_store_agent_face_keys, s19, "$g_talk_agent"),
            (troop_set_face_keys, ":slave", s19),
        (else_try), # if not dialogue we need to randomize the face
            (str_store_troop_face_keys, s1, ":troop", 0),# lower bound
            (str_store_troop_face_keys, s2, ":troop", 1),# upper bound
            (call_script, "script_generate_random_face_between_keys"),
            (troop_set_face_keys, ":slave", s3),
        (try_end),

        # give slave a name
        (troop_get_slot, ":culture", "trp_player", slot_troop_culture),
        (call_script, "script_get_character_name_for_troop", ":race", ":culture"),
        (troop_set_name, ":slave", s12),
        (troop_set_plural_name, ":slave", s12),

        (assign, ":break", -1),
    (try_end),
    (try_begin),
        (eq, ":break", household_slaves_end),
        (display_message, "@Maximum number of slaves reached.", message_alert),
    (try_end),
]),
