#script_describe_slave_skills_to_s0
# Given a troop ID, this script populates string register s0 with a formatted description of their aptitudes for various tasks.
# Input:
#   - script_param_1: ":slave_troop_id"
# Output:
#   - s0: Formatted string for tooltips.
#
# Skill Mapping:
# - looting     => corruption (Stealth/Thievery)
# - trade       => management (Commerce/Stewardship)
# - engineering => building (Construction/Siegecraft), management
# - power_strike=> mining (Labor/Strength), building
# - athletics   => farming (Endurance/Agility), general labor
# - inventory management => cooking
("describe_slave_skills_to_s0", [
    (store_script_param, ":slave_troop_id", 1),

    (str_clear, s0),
    (str_store_string, s0, "@--- Attributes ---^"), # Tooltip header

    (assign, ":any_skill_found", 0),

    # 1. Athletics (Farming/Endurance/General Labor)
    (store_skill_level, ":athletics_level", "skl_athletics", ":slave_troop_id"),
    (try_begin),
        (gt, ":athletics_level", 0),
        (assign, ":any_skill_found", 1),
        (try_begin),
            (is_between, ":athletics_level", 7, 11),
            (str_store_string, s1, "@- Exceptionally strong and tireless; ideal for farm work."),
        (else_try),
            (is_between, ":athletics_level", 4, 7),
            (str_store_string, s1, "@- Well-suited for farming and strenuous labor."),
        (else_try),
            (str_store_string, s1, "@- Some aptitude for farming and general labor."),
        (try_end),
        (str_store_string, s0, "@{s0}^{s1}"),
    (try_end),

    # 2. Power Strike (Mining/Labor/Strength)
    (store_skill_level, ":power_strike_level", "skl_power_strike", ":slave_troop_id"),
    (try_begin),
        (gt, ":power_strike_level", 0),
        (assign, ":any_skill_found", 1),
        (try_begin),
            (is_between, ":power_strike_level", 7, 11),
            (str_store_string, s1, "@- Powerful physique, perfect for the quarry or construction."),
        (else_try),
            (is_between, ":power_strike_level", 4, 7),
            (str_store_string, s1, "@- A strong back, good for mining and building projects."),
        (else_try),
            (str_store_string, s1, "@- Shows potential for mining or construction work."),
        (try_end),
        (str_store_string, s0, "@{s0}^{s1}"),
    (try_end),

    # 3. Trade (Management/Commerce/Stewardship)
    (store_skill_level, ":trade_level", "skl_trade", ":slave_troop_id"),
    (try_begin),
        (gt, ":trade_level", 0),
        (assign, ":any_skill_found", 1),
        (try_begin),
            (is_between, ":trade_level", 7, 11),
            (str_store_string, s1, "@- A keen mind for commerce and management."),
        (else_try),
            (is_between, ":trade_level", 4, 7),
            (str_store_string, s1, "@- Has a good head for numbers; suitable for stewardship."),
        (else_try),
            (str_store_string, s1, "@- Can handle basic accounts and workshop management."),
        (try_end),
        (str_store_string, s0, "@{s0}^{s1}"),
    (try_end),

    # 4. Engineering (Building/Construction)
    (store_skill_level, ":engineering_level", "skl_engineer", ":slave_troop_id"),
    (try_begin),
        (gt, ":engineering_level", 0),
        (assign, ":any_skill_found", 1),
        (try_begin),
            (is_between, ":engineering_level", 7, 11),
            (str_store_string, s1, "@- A natural engineer, capable of overseeing major constructions."),
        (else_try),
            (is_between, ":engineering_level", 4, 7),
            (str_store_string, s1, "@- Skilled in construction projects."),
        (else_try),
            (str_store_string, s1, "@- Possesses a knack for building and simple construction."),
        (try_end),
        (str_store_string, s0, "@{s0}^{s1}"),
    (try_end),

    # 5. Looting (Corruption/Thievery)
    (store_skill_level, ":looting_level", "skl_looting", ":slave_troop_id"),
    (try_begin),
        (gt, ":looting_level", 0),
        (assign, ":any_skill_found", 1),
        (try_begin),
            (is_between, ":looting_level", 7, 11),
            (str_store_string, s1, "@- Deeply corrupt and an expert thief. Placing this one in any position of trust guarantees losses."),
        (else_try),
            (is_between, ":looting_level", 4, 7),
            (str_store_string, s1, "@- Highly proficient in theft. Will likely embezzle goods and skim profits if unmanaged."),
        (else_try),
            (str_store_string, s1, "@- Keen-eyed and light-fingered. Best not left unsupervised around valuables."),
        (try_end),
        (str_store_string, s0, "@{s0}^{s1}"),
    (try_end),

    # 6. Inventory Management (Cooking) - HUMOROUS
    # This block always provides a description, even for skill level 0.
    (store_skill_level, ":cooking_level", "skl_inventory_management", ":slave_troop_id"),
    (call_script, "script_describe_cook_quality_to_s1", ":cooking_level", 1),
    (str_store_string, s0, "@{s0}^{s1}"),

    # Fallback message if no relevant skills are found
    (try_begin),
        (eq, ":any_skill_found", 0),
        (str_store_string, s0, "@{s0}^This one seems suited only for the most basic, unskilled tasks."),
    (try_end),
]),

# script_generate_random_face_between_keys
# This script generates a new, randomized face key and stores it in a destination string register.
# The new face key's components (hair, age, morphs, etc.) are chosen randomly from the range
# defined by the two source face keys.
#
# Parameters:
# s3 - Where the new random face key will be stored.
# s1 - String register holding the first face key.
# s2 - String register holding the second face key.
("generate_random_face_between_keys",[
    # Ensure source strings are valid
    # (display_message, "@Generating random face between {s1} and {s2}."),

    # Initialize the destination string with one of the source strings.
    # This ensures any unhandled values have a valid default.
    (str_store_string_reg, s3, s1),

    # --- Process each face component one by one ---

    # 1. Hair
    (face_keys_get_hair, ":val_1", s1),
    (face_keys_get_hair, ":val_2", s2),
    # (assign, reg1, ":val_1"),
    # (assign, reg2, ":val_2"),
    # (display_message, "@Hair values: {reg1} and {reg2}."), # Debug message to show hair values
    # Ensure val_1 is min and val_2 is max
    (try_begin),
        (gt, ":val_1", ":val_2"),
        (assign, ":temp", ":val_1"),
        (assign, ":val_1", ":val_2"),
        (assign, ":val_2", ":temp"),
    (try_end),
    (store_add, ":range_high", ":val_2", 1), # store_random_in_range is exclusive of the upper bound
    (store_random_in_range, ":random_val", ":val_1", ":range_high"),

    # (assign, reg1, ":random_val"),
    # (display_message, "@Random hair value: {reg3}."), # Debug message

    (face_keys_set_hair, s3, ":random_val"),

    # 2. Beard
    (face_keys_get_beard, ":val_1", s1),
    (face_keys_get_beard, ":val_2", s2),

    # (assign, reg1, ":val_1"),
    # (assign, reg2, ":val_2"),
    # (display_message, "@Beard values: {reg1} and {reg2}."), # Debug message to show beard values

    (try_begin),
        (gt, ":val_1", ":val_2"),
        (assign, ":temp", ":val_1"),
        (assign, ":val_1", ":val_2"),
        (assign, ":val_2", ":temp"),
    (try_end),
    (store_add, ":range_high", ":val_2", 1),
    (store_random_in_range, ":random_val", ":val_1", ":range_high"),

    # (assign, reg1, ":random_val"),
    # (display_message, "@Random beard value: {reg3}."), # Debug message

    (face_keys_set_beard, s3, ":random_val"),

    # 3. Face Texture
    (face_keys_get_face_texture, ":val_1", s1),
    (face_keys_get_face_texture, ":val_2", s2),

    # (assign, reg1, ":val_1"),
    # (assign, reg2, ":val_2"),
    # (display_message, "@Face texture values: {reg1} and {reg2}."), # Debug message to show face texture values

    (try_begin),
        (gt, ":val_1", ":val_2"),
        (assign, ":temp", ":val_1"),
        (assign, ":val_1", ":val_2"),
        (assign, ":val_2", ":temp"),
    (try_end),
    (store_add, ":range_high", ":val_2", 1),
    (store_random_in_range, ":random_val", ":val_1", ":range_high"),

    # (assign, reg1, ":random_val"),
    # (display_message, "@Random face texture value: {reg3}."), # Debug message

    (face_keys_set_face_texture, s3, ":random_val"),

    # 4. Hair Color (0-63)
    (face_keys_get_hair_color, ":val_1", s1),
    (face_keys_get_hair_color, ":val_2", s2),

    # (assign, reg1, ":val_1"),
    # (assign, reg2, ":val_2"),
    # (display_message, "@Hair color values: {reg1} and {reg2}."), # Debug message to show hair color values

    (try_begin),
        (gt, ":val_1", ":val_2"),
        (assign, ":temp", ":val_1"),
        (assign, ":val_1", ":val_2"),
        (assign, ":val_2", ":temp"),
    (try_end),
    (store_add, ":range_high", ":val_2", 1),
    (store_random_in_range, ":random_val", ":val_1", ":range_high"),

    # (assign, reg1, ":random_val"),
    # (display_message, "@Random hair color value: {reg3}."), # Debug message

    (face_keys_set_hair_color, s3, ":random_val"),

    # 5. Age (0-63)
    (face_keys_get_age, ":val_1", s1),
    (face_keys_get_age, ":val_2", s2),

    # (assign, reg1, ":val_1"),
    # (assign, reg2, ":val_2"),
    # (display_message, "@Age values: {reg1} and {reg2}."), # Debug message to show age values

    (try_begin),
        (gt, ":val_1", ":val_2"),
        (assign, ":temp", ":val_1"),
        (assign, ":val_1", ":val_2"),
        (assign, ":val_2", ":temp"),
    (try_end),
    (store_add, ":range_high", ":val_2", 1),
    (store_random_in_range, ":random_val", ":val_1", ":range_high"),

    # (assign, reg1, ":random_val"),
    # (display_message, "@Random age value: {reg3}."), # Debug message

    (face_keys_set_age, s3, ":random_val"),

    # 6. Morph Keys (Loop through all 8 accessible morphs)
    # These control face shape: chin, cheeks, nose, etc.
    # Indices 0-7 are 'chin_size' through 'cheeks'
    (try_for_range, ":morph_key_no", 0, 27),
        (face_keys_get_morph_key, ":val_1", s1, ":morph_key_no"),
        (face_keys_get_morph_key, ":val_2", s2, ":morph_key_no"),

        # (assign, reg1, ":val_1"),
        # (assign, reg2, ":val_2"),
        # (display_message, "@Morph key {reg1} values: {reg1} and {reg2}."), # Debug message to show morph key values

        (try_begin),
            (gt, ":val_1", ":val_2"),
            (assign, ":temp", ":val_1"),
            (assign, ":val_1", ":val_2"),
            (assign, ":val_2", ":temp"),

            (store_add, ":range_high", ":val_2", 1), # Morph values are 0-7
            (store_random_in_range, ":random_val", ":val_1", ":range_high"),

        (else_try),
            (eq, ":val_1", 0),
            (eq, ":val_2", 0),
            # both are 0, so make normal distributed random value with the mean of possible values being the expectation value
            # possible values are 0 to 7
            (store_random_in_range, ":random_val_1", 0, 4),
            (store_random_in_range, ":random_val", 0, 4),
            (val_add, ":random_val", ":random_val_1"),
        (try_end),

        # (assign, reg1, ":random_val"),
        # (display_message, "@Random morph key {reg3} value: {reg1}."), # Debug message

        (face_keys_set_morph_key, s3, ":morph_key_no", ":random_val"),
    (try_end),

    # print the vinal string
    # (display_message, "@Generated random face: {s3}"),
]),
