        (val_max, ":final_amount_male", 0),
        (val_max, ":final_amount_female", 0),
        (troop_set_slot, ":slave_trader", ":male_slot", ":final_amount_male"),
        (troop_set_slot, ":slave_trader", ":female_slot", ":final_amount_female"),

