# script_init_temp_party
# Prepares a temporary party for trading slaves stored in troop slots.
# INPUT:
# param1: ":slave_trader_troop_id"
("init_temp_party", [
    (store_script_param, ":slave_trader", 1),
    (party_clear, "p_temp_party_2"),
    (try_for_range, ":current_slave_slot", slot_troop_slaves_begin, slot_troop_slaves_end),
        (troop_get_slot, ":slave_amount", ":slave_trader", ":current_slave_slot"),
        (gt, ":slave_amount", 0),
        (store_sub, ":offset", ":current_slave_slot", slot_troop_slaves_begin),
        (store_add, ":slave_troop_id", "trp_slave", ":offset"),
        (is_between, ":slave_troop_id", slaves_begin, slaves_end),
        (party_add_prisoners, "p_temp_party_2", ":slave_troop_id", ":slave_amount"),
    (try_end),
]),

# script_apply_changes_to_slave_trader
# After trading with p_temp_party_2, this script updates the slave trader's slots to match.
# INPUT:
# param1: ":slave_trader_troop_id"
("apply_changes_to_slave_trader", [
    (store_script_param, ":slave_trader", 1),

    # First, wipe all existing slave slots for this trader to 0.
    (try_for_range, ":i_slot", slot_troop_slaves_begin, slot_troop_slaves_end),
        (troop_set_slot, ":slave_trader", ":i_slot", 0),
    (try_end),

    # Now, iterate through the remaining prisoners in the temporary party and set the new slot values.
    (party_get_num_prisoner_stacks, ":num_stacks_after", "p_temp_party_2"),
    (try_for_range, ":i_stack", 0, ":num_stacks_after"),
        (party_prisoner_stack_get_troop_id, ":troop_id", "p_temp_party_2", ":i_stack"),
        (party_prisoner_stack_get_size, ":stack_size", "p_temp_party_2", ":i_stack"),

        # Convert the troop_id back to its corresponding slot
        (store_sub, ":offset", ":troop_id", "trp_slave"), # Assumes your first slave troop is named "trp_slave"
        (store_add, ":slave_slot", slot_troop_slaves_begin, ":offset"),

        (is_between, ":slave_slot", slot_troop_slaves_begin, slot_troop_slaves_end), # Failsafe
        (troop_set_slot, ":slave_trader", ":slave_slot", ":stack_size"),
    (try_end),
    # Clean up the temporary party
    (party_clear, "p_temp_party_2"),
]),
#script_get_labour_slave_skill_modifier
("get_labour_slave_skill_modifier",[
    (store_script_param, ":party_id", 1),
    (store_script_param, ":skill", 2),
    (assign, ":modifier", 0),
    # (assign, ":total_slaves", 0),
    (party_get_num_prisoner_stacks, ":num_prisoner_stacks", ":party_id"),
    (try_for_range, ":i_stack", 0, ":num_prisoner_stacks"),
        (party_prisoner_stack_get_troop_id, ":troop_id", ":party_id", ":i_stack"),
        (is_between, ":troop_id", slaves_begin, slaves_end),

        # (display_message, "@Check 1"),

        (party_prisoner_stack_get_size, ":stack_size", ":party_id", ":i_stack"),
        (store_skill_level, ":cur_skill", ":skill", ":troop_id"),
        (val_mul, ":cur_skill", 2),
        (val_add, ":cur_skill", -4),

        # (assign, reg10, ":cur_skill"),
        # (assign, reg11, ":stack_size"),
        # (display_message, "@Check skill: {reg10} | stack_size: {reg11}"),

        (val_add, ":cur_skill", 100),#factor of -4 to 12%
        (store_mul, ":weighted_number_slaves", ":cur_skill", ":stack_size"),
        (val_div, ":weighted_number_slaves", 100),

        # (assign, reg10, ":cur_skill"),
        # (assign, reg11, ":weighted_number_slaves"),
        # (display_message, "@Check skill: {reg10} | weighted_number_slaves: {reg11}"),

        # Add this stack's total to the grand total
        (val_add, ":modifier", ":weighted_number_slaves"),
        # (val_add, ":total_slaves", ":stack_size"),
    (try_end),
    (assign, reg0, ":modifier"),
]),
# script_count_party_slaves
# Counts the number of slave prisoners in a given party.
# INPUT:
# param1: ":party_id"
# param2: ":gender" (0 = any, 1 = male, 2 = female)
# OUTPUT:
# reg0: The total count of specified slaves.
("count_party_slaves", [
    (store_script_param, ":party_id", 1),
    (store_script_param, ":gender_to_count", 2),

    (assign, ":total_slave_count", 0),

    (party_get_num_prisoner_stacks, ":num_prisoner_stacks", ":party_id"),
    (try_for_range, ":i_stack", 0, ":num_prisoner_stacks"),
        (party_prisoner_stack_get_troop_id, ":troop_id", ":party_id", ":i_stack"),
        (is_between, ":troop_id", slaves_begin, slaves_end),

        (assign, ":add_this_stack", 0),
        (try_begin),
            # Case 1: Count any gender
            (eq, ":gender_to_count", 0),
            (assign, ":add_this_stack", 1),
        (else_try),
            # Case 2: Count males only
            (eq, ":gender_to_count", 1),
            (call_script, "script_dplmc_store_troop_is_female", ":troop_id"),
            (assign, ":is_female", reg0),
            (eq, ":is_female", 0),
            (assign, ":add_this_stack", 1),
        (else_try),
            # Case 3: Count females only
            (eq, ":gender_to_count", 2),
            (call_script, "script_dplmc_store_troop_is_female", ":troop_id"),
            (assign, ":is_female", reg0),
            (eq, ":is_female", 1),
            (assign, ":add_this_stack", 1),
        (try_end),
        (eq, ":add_this_stack", 1),
        (party_prisoner_stack_get_size, ":stack_size", ":party_id", ":i_stack"),
        (val_add, ":total_slave_count", ":stack_size"),
    (try_end),

    (assign, reg0, ":total_slave_count"),
]),
# script_remove_slaves_from_party
# Removes a specified number of slave prisoners from a party.
# INPUT:
# param1: ":party_id"
# param2: ":number_to_remove"
# param3: ":gender" (0 = any, 1 = male, 2 = female)
("remove_slaves_from_party", [
    (store_script_param, ":party_id", 1),
    (store_script_param, ":number_to_remove", 2),
    (store_script_param, ":gender_to_remove", 3),

    (assign, ":slaves_still_to_remove", ":number_to_remove"),

    (party_get_num_prisoner_stacks, ":num_prisoner_stacks", ":party_id"),
    (try_for_range_backwards, ":i_stack", 0, ":num_prisoner_stacks"),
        (gt, ":slaves_still_to_remove", 0),

        (party_prisoner_stack_get_troop_id, ":troop_id", ":party_id", ":i_stack"),
        (is_between, ":troop_id", slaves_begin, slaves_end),

        (assign, ":is_correct_gender", 0),
        (try_begin),
            (eq, ":gender_to_remove", 0), # Any
            (assign, ":is_correct_gender", 1),
        (else_try),
            (eq, ":gender_to_remove", 1), # Male
            (call_script, "script_dplmc_store_troop_is_female", ":troop_id"),
            (assign, ":is_female", reg0),
            (eq, ":is_female", 0),
            (assign, ":is_correct_gender", 1),
        (else_try),
            (eq, ":gender_to_remove", 2), # Female
            (call_script, "script_dplmc_store_troop_is_female", ":troop_id"),
            (assign, ":is_female", reg0),
            (eq, ":is_female", 1),
            (assign, ":is_correct_gender", 1),
        (try_end),
        (eq, ":is_correct_gender", 1),

        (party_prisoner_stack_get_size, ":stack_size", ":party_id", ":i_stack"),
        (assign, ":num_to_remove_from_this_stack", ":stack_size"),
        (val_min, ":num_to_remove_from_this_stack", ":slaves_still_to_remove"),
        (party_remove_prisoners, ":party_id", ":troop_id", ":num_to_remove_from_this_stack"),

        (try_begin),
            (eq, ":party_id", "p_main_party"),
            (str_store_troop_name_by_count, s0, ":troop_id", ":num_to_remove_from_this_stack"),
            (assign, reg0, ":num_to_remove_from_this_stack"),
            (display_message, "@Removed {reg0} {s0} from your party"),
        (try_end),

        (val_sub, ":slaves_still_to_remove", ":num_to_remove_from_this_stack"),
    (try_end),
]),

#script_chariot_trigger
("chariot_trigger", [
    (store_script_param, ":scene_prop", 1),
    (try_begin),
        (scene_prop_get_num_instances, ":number_chariots", ":scene_prop"),
        (ge, ":number_chariots", 1),
        (set_fixed_point_multiplier, 1000),
        (try_for_range, ":dummy", 0, ":number_chariots"),
            (scene_prop_get_instance, ":scene_prop_id", ":scene_prop", ":dummy"),
            (prop_instance_is_valid, ":scene_prop_id"),#valid
            (neg|scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_moving, prop_disabled),#not disable

            (scene_prop_get_slot, ":horse", ":scene_prop_id", slot_attached_horse),

            (try_begin),
                (gt, ":horse", -1),
                (agent_is_active, ":horse"),#valid
                (agent_is_alive, ":horse"),

                # use running away to force dismount for player
                (try_begin),
                    (agent_slot_eq, ":horse", slot_agent_is_running_away, 1),
                    (agent_stop_running_away, ":horse"),
                    (agent_set_slot, ":horse", slot_agent_is_running_away, 0),
                (try_end),

                (init_position, pos10),
                (agent_get_speed, pos10, ":horse"),
                (position_get_x, ":x", pos10),
                (position_get_y, ":y", pos10),
                (position_get_z, ":z", pos10),
                (agent_get_rider, ":rider", ":horse"),

                # init scene prop for first time
                (try_begin),
                    (scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_init, 1),
                    (agent_is_active, ":rider"),
                    (agent_is_alive, ":rider"),
                    (agent_is_human, ":rider"),
                    (agent_set_animation, ":rider", "anim_chariot_rider"),
                    (try_begin),
                        (neg|agent_is_non_player, ":rider"),
                        (assign, "$g_player_chariot_agent", ":horse"),
                        (display_message, "@Enable chariot camera."),
                    (try_end),
                    (scene_prop_set_slot, ":scene_prop_id", slot_scene_prop_init, 2),
                (try_end),
                # (assign, reg1, ":x"),
                # (assign, reg2, ":y"),
                # (assign, reg3, ":z"),
                # (display_message, "@x {reg1}, y {reg2}, z {reg3}"),
                # check damage if moving fast
                (try_begin),
                    (gt, ":y", 1000),
                    (store_div, ":y_upper_bound", ":y", 1000),
                    (store_random_in_range, ":damage", -3, ":y_upper_bound"),
                    (agent_is_active, ":rider"),
                    (agent_is_alive, ":rider"),
                    (agent_is_human, ":rider"),
                    (agent_get_troop_id, ":rider_troop", ":rider"),
                    (store_skill_level, ":riding_skill", "skl_riding", ":rider_troop"),
                    (val_sub, ":damage", ":riding_skill"),
                    (ge, ":damage", 1),
                    (prop_instance_receive_damage, ":scene_prop_id", ":rider", ":damage"),
                    (try_begin),
                        (neg|agent_is_non_player, ":rider"),
                        (assign, reg10, ":damage"),
                        (assign, reg11, ":y_upper_bound"),
                        (assign, reg13, ":riding_skill"),
                        (display_message, "@High speed damaged your chariot! (Damage: {reg10}, velocity: {reg11} m/s, skill: {reg13})", message_negative),
                    (try_end),
                (try_end),
                # check crash with others
                (try_begin),
                    (this_or_next|gt, ":x", 2000),
                    (this_or_next|gt, ":y", 2000),
                    (gt, ":z", 2000),
                    (call_script, "script_check_chariots_crashed", ":scene_prop_id"),
                    (assign, ":crash_prop_id", reg0),
                    (gt, ":crash_prop_id", -1),

                    # (display_message, "@Apply crash effects", message_negative),

                    (store_div, ":y_upper_bound", ":y", 1000),
                    (val_add, ":y_upper_bound", 1),

                    (try_begin),
                        (agent_is_active, ":rider"),
                        (agent_is_alive, ":rider"),
                        (agent_is_human, ":rider"),
                        (agent_is_non_player, ":rider"),
                        (this_or_next|eq, ":crash_prop_id", "spr_quadriga_chariot_destroyed"),
                        (this_or_next|eq, ":crash_prop_id", "spr_basic_chariot_b_destroyed"),
                        (eq, ":crash_prop_id", "spr_basic_chariot_destroyed"),
                        (val_mul, ":y_upper_bound", 2),
                        # (val_div, ":y_upper_bound", 2),
                    (else_try),
                        (this_or_next|eq, ":crash_prop_id", "spr_quadriga_chariot_destroyed"),
                        (this_or_next|eq, ":crash_prop_id", "spr_basic_chariot_b_destroyed"),
                        (eq, ":crash_prop_id", "spr_basic_chariot_destroyed"),
                        (val_mul, ":y_upper_bound", 3),
                    (else_try),
                        (val_mul, ":y_upper_bound", 4),
                    (try_end),
                    (store_random_in_range, ":damage", 1, ":y_upper_bound"),

                    (prop_instance_receive_damage, ":scene_prop_id", ":rider", ":damage"),

                    (prop_instance_get_position, pos47, ":scene_prop_id"),
                    (particle_system_burst, "psys_dummy_smoke_big", pos47, 3),
                    (particle_system_burst, "psys_dummy_straw_big", pos47, 10),
                    (play_sound_at_position, "snd_dummy_destroyed", pos47),

                    (try_begin),
                        (agent_is_active, ":rider"),
                        (agent_is_alive, ":rider"),
                        (agent_is_human, ":rider"),
                        (neg|agent_is_non_player, ":rider"),
                        (assign, reg10, ":damage"),
                        (display_message, "@Chariot crashed and got damaged! (Damage: {reg10})", message_negative),
                    (try_end),
                (try_end),
                # animation for wheel
                (try_begin),#forwards
                    (this_or_next|scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_moving, prop_moving_backward),
                    (scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_moving, prop_not_moving),
                    (this_or_next|gt, ":x", 0),
                    (this_or_next|gt, ":y", 0),
                    (gt, ":z", 0),
                    (scene_prop_set_slot, ":scene_prop_id", slot_scene_prop_moving, prop_moving_forward),
                    (prop_instance_deform_in_cycle_loop, ":scene_prop_id", 17, 1, 1000),
                    (prop_instance_play_sound, ":scene_prop_id", "snd_chariot", sf_looping),
                (else_try),#backwards
                    (this_or_next|scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_moving, prop_moving_forward),
                    (scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_moving, prop_not_moving),
                    (lt, ":y", 0),
                    (scene_prop_set_slot, ":scene_prop_id", slot_scene_prop_moving, prop_moving_backward),
                    (prop_instance_deform_in_cycle_loop, ":scene_prop_id", 1, 17, 2000),
                    (prop_instance_play_sound, ":scene_prop_id", "snd_chariot", sf_looping),
                (else_try),#standing
                    (this_or_next|scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_moving, prop_moving_backward),
                    (scene_prop_slot_eq, ":scene_prop_id", slot_scene_prop_moving, prop_moving_forward),
                    (eq, ":x", 0),
                    (eq, ":y", 0),
                    (eq, ":z", 0),
                    (scene_prop_set_slot, ":scene_prop_id", slot_scene_prop_moving, prop_not_moving),
                    (prop_instance_stop_sound, ":scene_prop_id"),
                    (prop_instance_deform_in_cycle_loop, ":scene_prop_id", 0, 0, 1),
                    # (prop_instance_stop_animating, ":scene_prop_id"),
                (try_end),
            (else_try),#stop the animation of horse if it is dead
                (scene_prop_set_slot, ":scene_prop_id", slot_scene_prop_moving, prop_disabled),#disable
                (prop_instance_stop_sound, ":scene_prop_id"),
                (prop_instance_deform_in_cycle_loop, ":scene_prop_id", 0, 0, 1),
            (try_end),
        (try_end),
    (try_end),
]),
