# script_check_chariots_crashed
# Checks if a given chariot prop has crashed into another chariot.
("check_chariots_crashed",[
    (store_script_param, ":chariot_instance", 1),
    (set_fixed_point_multiplier, 1000),

    (store_mission_timer_a, ":cur_timer"),
    (scene_prop_get_slot, ":last_crash", ":chariot_instance", scene_prop_timer),
    # (assign, reg11, ":cur_timer"),
    # (assign, reg10, ":last_crash"),
    # (assign, reg12, ":chariot_instance"),
    # (display_message, "@Check chariot {reg12} cur time {reg11} last crash at {reg10}"),

    (assign, ":crash_prop_id", -1), # Default to no crash
    (val_sub, ":cur_timer", ":last_crash"),
    (try_begin),
        (gt, ":cur_timer", 3),

        (init_position, pos21),
        (prop_instance_get_position, pos21, ":chariot_instance"), # My chariot's position

        (troop_set_slot, "trp_temp_array_c", 1, "spr_basic_chariot"),
        (troop_set_slot, "trp_temp_array_c", 2, "spr_basic_chariot_destroyed"),
        (troop_set_slot, "trp_temp_array_c", 3, "spr_basic_chariot_b"),
        (troop_set_slot, "trp_temp_array_c", 4, "spr_basic_chariot_b_destroyed"),
        (troop_set_slot, "trp_temp_array_c", 5, "spr_quadriga_chariot"),
        (troop_set_slot, "trp_temp_array_c", 6, "spr_quadriga_chariot_destroyed"),

        (try_for_range, ":slot", 1, 7),
            (eq, ":crash_prop_id", -1), # Default to no crash
            (troop_get_slot, ":scene_prop_to_check", "trp_temp_array_c", ":slot"),
            (scene_prop_get_num_instances, ":num_props", ":scene_prop_to_check"),
            (ge, ":num_props", 1),

            # (assign, reg10, ":num_props"),
            # (assign, reg11, ":scene_prop_to_check"),
            # (display_message, "@{reg10} props for {reg11}"),

            (try_for_range, ":dummy", 0, ":num_props"),
                (scene_prop_get_instance, ":other_prop_instance", ":scene_prop_to_check", ":dummy"),
                (prop_instance_is_valid, ":other_prop_instance"),
                (neq, ":other_prop_instance", ":chariot_instance"), # Don't check against myself

                # (assign, reg11, ":scene_prop_to_check"),
                # (assign, reg10, ":other_prop_instance"),
                # (display_message, "@Check prop {reg11} instance {reg10}"),

                # Get the position of the other chariot
                (init_position, pos22),
                (prop_instance_get_position, pos22, ":other_prop_instance"),

                # Only cast a ray if they are reasonably close (e.g., less than 4 meters)
                (get_distance_between_positions, ":distance", pos21, pos22),
                # (assign, reg10, ":distance"),
                # (display_message, "@Distance: {reg10}"),

                (lt, ":distance", 395),

                # (position_copy_rotation, pos22, pos21), # Orient the ray to point at the other chariot
                # (display_message, "@Try to cast a ray"),
                # (init_position, pos24), # This will receive the hit location
                # (cast_ray, ":instance_hit", pos24, pos22, 500),
                # (assign, reg10, ":instance_hit"),
                # (try_begin),
                #     (gt, ":instance_hit", -1),
                #     (prop_instance_get_scene_prop_kind, reg11, ":instance_hit"),
                # (else_try),
                #     (assign, reg11, -1),
                # (try_end),
                # (display_message, "@instance_hit: {reg10}, prop id: {reg11}"),
                # (eq, ":instance_hit", ":other_prop_instance"),
                # (assign, ":num_props", -1),
                (assign, ":crash_prop_id", ":scene_prop_to_check"),


                (scene_prop_set_slot, ":chariot_instance", scene_prop_timer, ":cur_timer"),
                # (assign, reg10, ":cur_timer"),
                # (display_message, "@Crash detected at time {reg10}!"),
            (try_end),
        (try_end),
    (try_end),
    (assign, reg0, ":crash_prop_id"),
]),
